local Text_Activity = readonly({
  Activity_100432_ActivityTips = {
    Text = "<Title:イベントルール>\n・「催眠妖虫」イベント開催中、守秘者はクレメンタインを含む専用の編成を使用し、試遊ステージを体験できます。\n・試遊ステージでは、編成中の覚醒体の調整はできません。\n<Title:イベント報酬>\n・初めて試遊ステージをクリア後、イベント画面で報酬を受け取れます。"
  },
  Activity_100433_ActivityName = {
    Text = "仁愛の司教"
  },
  Activity_100433_ActivityTips = {
    Text = "<Title:イベントルール>\n・「仁愛の司教」イベント開催中、守秘者はサルバドルを含む専用の編成を使用し、試遊ステージを体験できます。\n・試遊ステージでは、編成中の覚醒体の調整はできません。\n<Title:イベント報酬>\n・初めて試遊ステージをクリア後、イベント画面で報酬を受け取れます。"
  },
