  Activity_116470_ActivityName = {
    Text = "白夜の終わり"
  },
  Activity_116470_ActivityPlot = {
    Text = "彼らは運命の果てですれ違い、再び動き出した時計はすでに遅すぎた。ただあの悔恨に満ちた心だけが、闇の中のすべての穢れを照らし尽くすと誓った。"
