  Activity_116470_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「祝福の儀」のみ参加可能です。"
  },
  Activity_116470_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密保持者は期間限定プレイ「交わりし苦血」および「実績報酬」を通じてイベント通貨「謁見の奉礼」、「懺悔の奉礼」、「忠誠の奉礼」を収集できます。「謁見の奉礼」、「懺悔の奉礼」、「忠誠の奉礼」は「祝福の儀式」で商品を購入でき、イベント限定SR命輪「聖子の尊容」、流明の芯、無垢の芯などが含まれます。\n2、イベント期間中、「異夢視界：天の彼方·下」が期間限定で無料アンロックされ、イベント実績を達成するとイベント限定アイコン「銀の鍵の名において：ポリュデウケス」を獲得できます！\n\n<Title:イベント期間>\n1、10月20日 9:00 – 11月3日 9:00（GMT+8）、すべてのイベントプレイに参加可能。\n2、11月3日 9:00 – 11月10日 9:00（GMT+8）、「祝福の儀式」と実績報酬のみ参加可能。\n\n<Title:交わりし苦血>\n1、「交わりし苦血」には7つのステージがあり、1日ごとに1つが自動開放されます。\n2、挑戦するたびに「霊啡肽」×120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能がアンロックされます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、校友会の助っ人を使用して、より簡単にクリアすることができます。\n\n<Title: 回憶の渦>\n·イベント開始後、毎時間自動で60「謁見の奉礼」を獲得し、最大25時間分まで蓄積できます。\n\n<Title: 祝福の儀式>\n1、「祝福の儀式」には3つのショップがあり、開放時間は以下の通りです：\n·「肉身の洗浄」：10月20日 9時に開放。\n·「魂の懺悔」：10月21日 9時に開放。\n·「罪の析出」：10月22日 9時に開放。\n2、毎回の交換で750「謁見の奉礼」/「懺悔の奉礼」/「忠誠の奉礼」を消費し、画室内の5つのアイテム報酬をランダムに獲得します。\n3、各画室のアイテム報酬は「特殊アイテム」と「通常アイテム」の2種類に分かれており、リセット時に特殊アイテム報酬の残り数量を上限まで戻すことができます。具体的なルールは以下の通りです：\n（1）最初の2回のリセット：「特殊アイテム」の残り数量がなくなった後、秘密保持者はリセットを選択でき、リセット後は「特殊アイテム」と「通常アイテム」の残り数量が上限まで戻ります。また、交換を続けることも可能で、「通常アイテム」の残り数量もなくなった場合は、リセットを行わないと交換を続けることができません。\n（2）3回目以降のリセット：「通常アイテム」の残り数量がなくなった後にのみリセットが可能で、リセットにより「通常アイテム」の残り数量が上限まで戻りますが、「特殊アイテム」はリセットされません。\n\n<Title:イベントボーナス>\n1、秘密保持者が特定の覚醒体または命輪を所持している場合（編成不要）、「交わりし苦血」ステージ任務報酬の「謁見の奉礼」、「懺悔の奉礼」、「忠誠の奉礼」に追加のドロップボーナスが適用されます。具体的なボーナスは以下の通りです：\n·覚醒体「ポリュデウケス」：啓霊0/1/2/3以上で、ボーナス20％/30％/40％/50％。\n·SSR命輪「歪みし騎士の詩」：重位0/1/2/3以上で、ボーナス20％/30％/40％/50％。\n·SR命輪「聖子の尊容」：重位0/1/2/3以上で、ボーナス20％/30％/40％/50％。\n2、異なる覚醒体または命輪の「イベントボーナス」は累積方式で計算されます。 \n3、特別に、狂気難易度の初回クリア報酬は「イベントボーナス」の影響を受けません。\n\n<Title:異夢視界>\n1、イベント期間中、「異夢視界：天の彼方·下」を無料でアンロックできます。\n2、イベント終了後、「異夢視界：天の彼方·下」の調査進捗は保持され、イベント期間中に未完了の調査イベントを完了した場合でも、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「異夢視界：天の彼方·下」をアンロックしなかった場合、イベント終了後も「現実起点」×7を消費してアンロックできます。\n3、イベント期間中かどうかに関わらず、「異夢視界：天の彼方·下」をクリアすると「鍵令：血涙の聖心」を獲得できます。"
  },
  Activity_116470_BannerText = {
    Text = "期間限定イベント開催中！"
