  Activity_116765_ActivityTips = {
    Text = "イベントルール：\n1、秘密の番人が指定の紀行任務を完了すると、「刻印の旅立ち」で報酬を受け取ることができます。\n2、「上級紀行」をアンロックすると、任務完了時に追加報酬を受け取ることができます。\n3、今回の「上級紀行」の購入には期限があり、期限を過ぎると購入できなくなります。秘密の番人の皆様は11月3日9：00までに計画的にご購入ください。\n4、ご注意：本イベントでアンロックした「上級紀行」は本イベントでのみ有効です。秘密の番人の皆様は計画的にご利用ください。"
  },
  Activity_116765_BannerText = {
    Text = "特別紀行イベント期間限定開催！"
  },
  Activity_116818_ActivityName = {
    Text = "原初再戦"
  },
  Activity_116818_ActivityPlot = {
    Text = "「群星」はあの方の眼――あの方に代わって、世のすべてを見つめ、あるいは監視している。\nあの方の視線から逃れたと思っているだろう。だが事実は――お前はまだあの方の夢の中にいる。\n「捕まえた――」\nお前を捕らえた刹那、群星たちは満足の溜息を漏らした。"
  },
  Activity_116818_ActivityStageEndContent = {
    Text = "イベント終了"
  },
  Activity_116818_ActivityTips = {
    Text = "<Title: 原初再戦>\n·「原初再戦」には7つの再現不可能な、原初の視座に直接挑戦するステージが含まれます。イベント開始から2日間は1つ開放、3日目に3つ開放、その後2日間は毎日1つずつ開放されます。\n·各挑戦で対応する星辰原初の視座を撃破すると、対応する報酬を獲得できます。\n·各種星辰原初の視座には大量の分身が存在し、いずれかの秘密保持者がある種類の星辰原初の視座に勝利するたびに、その種類の「残存数」が1減少します。その種類の星辰原初の視座が殲滅されると、該当ステージは閉鎖され、再挑戦できなくなります。\n·各ステージでは異なる造物が提供され、強力なバフを付与します。\n·全ステージで助っ人の選択が必須です。イベント全体を通じて、相互フォロー中の各秘密保持者は1回のみ助っ人として利用できます。助っ人を使用するため、実際の同調率報酬は基本報酬からさらに50%増加します。\n·毎日、各覚醒体・運命の輪・鍵令は1回のみ出撃可能です。\n·イベント期間中、特遣記録「群星の詠嘆調」は無料で解放され、前提条件は不要です！「原初再戦」終了後は、「調査行動–星辰篇–第四章」を完了してから特遣記録「群星の詠嘆調」を開放する必要があります。\n\n<Title: レベル補正>\n·「原初再戦」にはレベル補正メカニズムがあり、すべての秘密保持者が共に戦えるようになっています！\nレベル補正ルールは以下の通りです：\n  ·調査チーム内で、レベルが60未満の覚醒体は本挑戦中レベル60に補正されます。\n  ·調査チーム内で、スキルレベルが5未満の覚醒体は本挑戦中スキルレベル5に補正されます。\n  ·調査チーム内で、「狂気の前兆」がレベル6未満の覚醒体は本挑戦中レベル6に補正されます。\n  ·調査チーム内で、「霊塑適性」がレベル5未満の覚醒体は本挑戦中レベル5に補正されます。\n  ·秘密保持者のレベルが60未満の場合、本挑戦中レベル60に補正されます。\n\n<Title:特遣記録>\n·イベント期間中、「特遣記録：群星の詠嘆調」は無料で解放され、前提条件は不要です！\n·イベント終了後、「特遣記録：群星の詠嘆調」の調査進捗は保持されます。イベント期間中に未完了の調査イベントを完了した場合も、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「特遣記録：群星の詠嘆調」を解放していない場合、イベント終了後は「調査行動–星辰篇–第四章」を完了し、「現実起点」×7を消費して特遣記録「群星の詠嘆調」を開放する必要があります。\n·イベント期間中かどうかに関わらず、「特遣記録：群星の詠嘆調」をクリアすると「鍵令：再会の願い」を獲得できます。"
  },
