    Text = "任務完了後、以下の限定覚醒体から1名を選んで覚醒できます！"
  },
  Activity_119693_ActivityTips = {
    Text = "<Title:イベントルール>\n·イベント期間中、各秘密保持者は累計200回鍵令を使用すると、8名の限定SSR覚醒体から1名を選んで覚醒できます。対象は熔毀·ドール、クレメンタイン、コッパーサント、カストル、デュルセイン、ケイティグラ、ピックマン、ポルクスです。\n·秘密保持者が既に覚醒済みの覚醒体を選択した場合、同一SSR覚醒体の2〜16回目の獲得時は、毎回対応する覚醒体の欠片1個と「根源沈殿」×50に変換されます。17回目以降の獲得時は、限定SSR覚醒体が「精粋霊核欠片」×2、「霊核欠片」×6、「根源沈殿」×250に変換されます。"
