  Activity_119694_ActivityTips = {
    Text = "<Title:イベントルール>\n·秘密保持者は指定の紀行任務を完了後、「明星の導き」で報酬を受け取ることができます。\n·「上級紀行」を解放すると、任務完了後に追加報酬を受け取ることができます。\n·今回の「上級紀行」の購入には期限があり、期限を過ぎると購入できなくなります。秘密保持者は1月26日9：00（GMT+8）までにご検討の上ご購入ください。\n·ご注意：本イベントで解放された「上級紀行」は本イベントでのみ有効です。秘密保持者の皆様は計画的にご利用ください。"
