  Activity_120496_ActivityName = {
    Text = "輪廻紀行"
  },
  Activity_120496_ActivityTips = {
    Text = "イベントルール：\n1、秘密の番人が指定の紀行任務を完了すると、「輪廻紀行」で報酬を受け取ることができます。\n2、「輪廻紀行」は常時開放されています。\n3、「上級紀行」をアンロックすると、任務完了時に追加報酬を受け取ることができます。\n4、ご注意：本イベントでアンロックした「上級紀行」は本イベントでのみ有効です。秘密の番人の皆様は計画的にご利用ください。"
