  Activity_120954_ActivityName = {
    Text = "星々の歌"
  },
  Activity_122195_ActivityName = {
    Text = "霧境の燔礼"
  },
  Activity_122195_ActivityPlot = {
    Text = "黎明の光が敬虔なる者の苦しみを解き放ち、星々を舟として、兄弟姉妹を高く懸かる国へと運ぶ。\n迷える子羊は門の中で歌い踊り、星の燭が永遠の神庭を飾る。\nしかし門の向こうの霧はとうに呼び声に応じて訪れていた。その霧は欺き、騙し、ただ己の歪んだ趣味を満たすためだけに。\nその霧はそのために「黎明」を封じ、解脱を試みる道を断ち切った。\n彼女はここで、世界のもう一つの終焉を見届けることになる。"
  },
  Activity_122195_ActivityStageEndContent = {
    Text = "イベントは終了しました。現在は「茉夏の小屋」のみ参加可能です"
  },
  Activity_122195_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密保持者は期間限定プレイ「迷失の自我」と「実績報酬」を通じてイベント通貨「迷霧の視」、「迷霧の夢」、「迷霧の源」を収集できます。「迷霧の視」、「迷霧の夢」、「迷霧の源」は「茉夏の小屋」で商品の購入に使用でき、イベント限定SR命輪「理性の明灯」、流明の芯、無垢の芯などが含まれます。\n2、イベント期間中、「多次元接続：銀と血の洗礼」が期間限定で無料アンロックされ、イベント実績を達成するとイベント限定アイコン「銀鍵の名において：茉夏」も獲得できます！\n\n<Title:イベント期間>\n1、12月29日 9:00 – 1月12日 9:00（GMT+8）、すべてのイベントプレイに参加できます。\n2、1月12日 9:00 – 1月19日 9:00（GMT+8）、「茉夏の小屋」と実績報酬のみ参加可能です。\n\n<Title:迷失の自我>\n1、「迷失の自我」には7つのステージが含まれ、1日ごとに1つ自動開放されます。\n2、挑戦するたびに「霊啡肽」×120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能がアンロックされます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、同窓会の助っ人を使用して、より簡単にクリアすることができます。\n\n<Title: 茉夏の小屋>\n「茉夏の小屋」には3つのショップがあり、開放時間は以下の通りです：\n·「素材室」： 12月29日 9時に開放。\n·「入夢室」： 12月30日 9時に開放。\n·「育成室」： 12月31日 9時に開放。\nショップ内で商品を選択して直接購入できます。\n\n<Title:イベントボーナス>\n1、秘密保持者が特定の覚醒体または命輪を所持している場合（出撃不要）、「迷失の自我」ステージ任務報酬の「迷霧の視」、「迷霧の夢」、「迷霧の源」に追加のドロップボーナスが適用されます。具体的なボーナスは以下の通りです：\n·覚醒体「茉夏」：啓霊0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SSR命輪「世界の果てまで狂戮」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SR命輪「理性の明灯」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%。\n2、異なる覚醒体または命輪の「イベントボーナス」は累積方式で計算されます。 \n3、特別に、狂乱難易度の初回クリア挑戦報酬は「イベントボーナス」の影響を受けません。\n\n<Title:多次元接続>\n1、イベント期間中、「多次元接続：銀と血の洗礼」は無料でアンロックできます。\n2、イベント終了後、「多次元接続：銀と血の洗礼」の調査進捗は保持され、イベント期間中に未完了の調査イベントを完了した場合もイベント期間中と同じ調査報酬を獲得できます。イベント期間中に「多次元接続：銀と血の洗礼」をアンロックしなかった場合、イベント終了後も「現実起点」×3を消費してアンロックできます。\n3、イベント期間中かどうかに関わらず、「多次元接続：銀と血の洗礼」をクリアすると「鍵令：霧境より来たる」を獲得できます。"
  },
  Activity_122195_BannerText = {
    Text = "遊興イベント期間限定開催！"
