  Activity_122520_ActivityName = {
    Text = "雨の町に潜む影・復刻"
  },
  Activity_122520_ActivityPlot = {
    Text = "その朧げで湿った夜の雨の中、運命の出会いがあなたを待っていた。\n彼女の名前、その姿は馴染み深く、穏やかで優雅な声はいつもあなたの心を不思議と安心させた。\nけれど、あなたは忘れていた。\n人間の願いを叶えるのはいつだって神か悪魔だけなのだと……\nさぁ、はたして彼女はどちらに属しているのか？"
  },
  Activity_122520_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「魔女の宝庫」のみ参加可能です。"
  },
  Activity_122520_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密保持者は期間限定プレイ「魔女小店」と「実績報酬」を通じてイベント通貨を収集できます。イベント通貨は「魔女の宝庫」で交換してアイテム報酬を獲得でき、イベント限定SR命輪「魔女のつば広帽」、賢者の石、無垢の芯、流明の芯などが含まれます。\n2、イベント期間中「特遣記録：雨鎮幽影」が無料開放され、イベント実績を達成するとイベント限定アイコン「銀鍵の名において：ダフデル」も獲得できます！\n\n<Title:イベント期間>\n1、1月12日 9:00 – 1月26日 9:00（GMT+8）、すべてのイベントコンテンツに参加できます。\n2、1月26日 9:00 – 2月2日 9:00（GMT+8）、「魔女の宝庫」と「実績報酬」のみ利用可能で、その他のコンテンツはすべて終了し参加できません。\n\n<Title: 魔女小店>\n1、「魔女小店」には5つのステージが含まれ、2日ごとに1つ自動開放されます。\n2、挑戦するたびに「霊啡肽」×120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能がアンロックされます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、同窓会の助っ人を使用して、より簡単にクリアすることができます。\n\n<Title: イベントボーナス>\n1、秘密保持者が特定の覚醒体または命輪を所持している場合（出撃不要）、「魔女小店」ステージ任務報酬の「蒼白野獣頭骨」、「幽影野獣頭骨」、「殷紅野獣頭骨」に追加のドロップボーナスが適用されます（再現を含む）。具体的なボーナスは以下の通りです：\n·覚醒体「ダフデル」：啓霊0/1/2/3以上、ボーナス20%/30%/40%/50%\n·SSR命輪「至高の珍蔵品」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%\n·SR命輪「魔女のつば広帽」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体または命輪の「イベントボーナス」は累積方式で計算されます。 \n3、特別に、狂乱難易度の初回クリア挑戦報酬は「イベントボーナス」の影響を受けません。\n\n<Title: 魔女の宝庫>\n1、「魔女の宝庫」は全部で3つあり、開放時間は以下の通りです：\n·「憂い解消の逸品」： 1月12日 9:00 – 2月2日 9:00。\n·「華麗なる秘宝」： 1月14日 9:00 – 2月2日 9:00。\n·「珍蔵の奇貨」： 1月16日 9:00 – 2月2日 9:00。\n2、交換するたびに750「蒼白野獣頭骨」/「幽影野獣頭骨」/「殷紅野獣頭骨」を消費し、宝庫の中からランダムで5つのアイテム報酬を獲得します。\n3、各宝庫のアイテム報酬は「特殊アイテム」と「通常アイテム」の2種類に分かれ、リセット時に指定アイテム報酬の残数を上限まで回復できます。具体的なルールは以下の通りです：\n（1）最初の2回のリセット：「特殊アイテム」の残数がなくなった後、秘密保持者はリセットを選択でき、リセット後は「特殊アイテム」と「通常アイテム」の残数が上限まで回復します。また、交換を続けることも可能で、「通常アイテム」の残数もなくなった場合、リセットしないと交換を続けられません。\n（2）3回目以降のリセット：「通常アイテム」の残数がなくなった後にのみリセットが可能で、リセットにより「通常アイテム」の残数が上限まで回復しますが、「特殊アイテム」はリセットされません。\n\n<Title: 特遣記録>\n1、イベント期間中「特遣記録：雨鎮幽影」が無料開放されます。\n2、イベント終了後、「特遣記録：雨鎮幽影」の調査進捗は保持され、イベント期間中に「特遣記録：雨鎮幽影」をアンロックしなかった場合、イベント終了後も「現実起点」×7を消費してアンロックできます。\n3、イベント期間中かどうかに関わらず、「特遣記録：雨鎮幽影」をクリアすると「鍵令：灰霧真容」を獲得できます。"
  },
