  Activity_123322_ActivityTips = {
    Text = "<Title:イベントルール>\n1、秘密の番人が指定の紀行任務を完了すると、「銀霜紀行」で報酬を受け取ることができます。\n2、「銀霜紀行」は1月12日 9:00（GMT+8）に終了します。\n3、「上級紀行」をアンロックすると、任務完了時に追加報酬を受け取ることができます。\n4、ご注意：本イベントでアンロックした「上級紀行」は本イベントでのみ有効です。秘密の番人の皆様は計画的にご利用ください。"
