  Activity_124051_ActivityName = {
    Text = "深淵の祀り・復刻"
  },
  Activity_124051_ActivityPlot = {
    Text = "深海の水鏡に映る影の中、王の夢は消え、神国もまた朽ち果てた。\n彼女は太古の幻夢から歩み出でて、未来の崩壊した廃墟に踏み入る。\n深淵に問うても、それはただ沈黙し深淵に祈れども、答えるは己のみ。"
  },
  Activity_124051_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「深淵の応答」のみ参加可能です。"
  },
  Activity_124051_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密保持者は期間限定プレイ「神国降臨」、「王の勅令」および「実績報酬」で活動通貨を収集できます。活動通貨は「沈淵の応答」にて進献することで道具報酬を獲得できます。イベント限定SR運命輪「深海の呼び声」、賢者の石、無垢の芯、流明の芯などが含まれます。\n2、イベント期間中「異夢視界：冒涜」が無料開放されます。イベント実績を達成すると、イベント限定アイコン「銀鍵の名の下に：ミリアム」も獲得できます！\n\n<Title:イベント期間>\n1、3月9日 9:00 – 3月23日 9:00（GMT+8）、すべてのイベントコンテンツに参加可能。\n2、3月23日 9:00 – 3月30日 9:00（GMT+8）、「沈淵の応答」と「実績報酬」のみ利用可能。その他のコンテンツは終了し参加できません。\n\n<Title: 神国降臨>\n1、「神国降臨」には5つのステージがあり、2日ごとに1つ自動開放されます。\n2、挑戦するたびに「霊啡肽」×120を消費し、挑戦成功で活動通貨を獲得します。\n3、ステージクリア後、そのステージの「再現」機能が解放されます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、校友会の助っ人や「共鳴：海淵祭儀」を使用して、より簡単にクリアすることができます。\n\n<Title: 祀物ボーナス>\n1、秘密保持者が特定の覚醒体または運命輪を所持している場合（出撃不要）、「神国降臨」ステージ任務報酬の「祀者の涙」、「祀者の血」、「祀者の髄」に追加のドロップボーナスが適用されます（再現を含む）。具体的なボーナスは以下の通りです：\n·覚醒体「ミリアム」：啓霊0/1/2/3以上、ボーナス20%/30%/40%/50%\n·SSR運命輪「敬虔なる偉力」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%\n·SR運命輪「深海の呼び声」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体または運命輪の「祀物ボーナス」は累積方式で計算されます。 \n3、特別に、狂乱難易度の初回クリア挑戦報酬は「祀物ボーナス」の影響を受けません。\n\n<Title:共鳴：海淵祭儀>\n1、秘密保持者はイベント実績を達成することで「虔信の心」を獲得できます。 \n2、「虔信の心」を消費して「共鳴：海淵祭儀」を発動すると、以下のボーナスを獲得できます：\n（1）イベントプレイ「神国降臨」で秘密保持者がより強くなり、挑戦がより簡単になります。\n（2）「神国降臨」挑戦完了後に獲得する活動通貨が増加します。\n（3）イベントプレイ「王の勅令」が発動します。\n\n<Title: 王の勅令>\n·共鳴「祭献試練」を発動すると、毎時間自動で60「祀者の涙」を獲得し、最大25時間分まで蓄積できます。\n\n<Title: 沈淵の応答>\n1、「沈淵の応答」には3つの祭壇があり、開放時間は以下の通りです：\n·「瑩涙祭壇」： 3月9日 9時〜3月30日 9時。\n·「猩血祭壇」： 3月11日 9時〜3月30日 9時。\n·「霊髄祭壇」： 3月13日 9時〜3月30日 9時。\n2、祭品を進献するたびに「祀者の涙」/「祀者の血」/「祀者の髄」×750を消費し、祭壇内の5つのアイテム報酬をランダムに獲得します。\n3、各祭壇のアイテム報酬は「特殊アイテム」と「通常アイテム」の2種類に分かれ、リセット時に指定アイテム報酬の残数を上限まで戻すことができます。具体的なルールは以下の通りです：\n（1）最初の3回のリセット：「特殊アイテム」の残数がなくなった後、秘密保持者はリセットを選択でき、リセット後は「特殊アイテム」と「通常アイテム」の残数が上限まで戻ります。また、リセットせずに祭品の進献を続けることも可能で、「通常アイテム」の残数もなくなった場合は、リセットしないと進献を続けられません。\n（2）4回目以降のリセット：「通常アイテム」の残数がなくなった後にのみリセット可能で、リセットにより「通常アイテム」の残数が上限まで戻りますが、「特殊アイテム」はリセットされません。\n\n<Title: 異夢視界>\n1、イベント期間中「異夢視界：冒涜」が無料開放されます。\n2、イベント終了後、「異夢視界：冒涜」の調査進捗は保持されます。イベント期間中に「異夢視界：冒涜」を解放していない場合、イベント終了後も「現実起点」×7を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「異夢視界：冒涜」をクリアすると「鍵令：海の祭」を獲得できます。\n\n<Title:復刻補填>\n1、以前に「異夢視界：冒涜」を解放済みの秘密保持者は、今回の復刻イベント期間中に再度解放する際に「祀者の涙」×700の補填を受け取れます。\n2、以前にイベント限定アイコン「銀鍵の名の下に：ミリアム」を獲得済みの秘密保持者は、重複獲得時に自動的に「無形者の招待状」×1に変換されます。\n3、以前に共鳴発動素材「虔信の心」を獲得済みの秘密保持者は、余分な「虔信の心」1個につき自動的に「薔薇金券」×5000に変換されます。\n"
  },
  Activity_124051_BannerText = {
    Text = "遊興イベント期間限定開催！"
  },
  Activity_124052_ActivityName = {
    Text = "サブステージ無料解放"
  },
  Activity_124053_ActivityName = {
    Text = "茨の女王"
  },
  Activity_124053_ActivityTips = {
    Text = "<Title:イベントルール>\n・「茨の女王」イベント開催中、守秘者はワンダを含む専用の編成を使用し、試遊ステージを体験できます。\n・試遊ステージでは、編成中の覚醒体の調整はできません。\n<Title:イベント報酬>\n・初めて試遊ステージをクリア後、イベント画面で報酬を受け取れます。"
  },
  Activity_124800_ActivityName = {
    Text = "逆転回合"
  },
  Activity_124801_ActivityName = {
    Text = "位相逆転"
  },
  Activity_124801_ActivityPlot = {
    Text = "「みんなに万象牌を遊ばせたい！」\n他の時空の来客が偶然の出来事で位相対人戦の空間に入り込み、元の姿とは大きく異なる形に改造した。\n空間を再び逆転させるために、異なる時空の守秘者が最強者を決め、この「お客様」に挑戦することに。"
  },
  Activity_124801_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は「相位対局」に参加して「実績報酬」の実績を達成し、「魔法のドングリ」を受け取れます。\n2、「魔法のドングリ」は「ターン奇賞」で豊富な報酬を受け取れます。イベント限定アイコン「逆転ターン：万象カード」、10個のイベント限定スタンプ、「砕裂余夢」、「群星余夢」などが含まれます。\n3、イベント期間中「多次元接続：逆転ターン」が無料開放されます！\n4、イベント期間中、「多次元接続：逆転ターン：異界からの来客」をクリアした守秘者は、「相位対局」の対戦背景が期間限定で「逆転ターン：意識空間」に変更されます。\n\n<Title:実績報酬>\n1、「実績報酬」には「秘儀試練」、「栄勲試練」、「閾限試練」が含まれ、守秘者は実績目標を達成して「魔法のドングリ」を受け取れます。\n2、「秘儀試練」実績では\n·相手の覚醒体を3体撃破するごとに「魔法のドングリ」×10を獲得、最大50回達成可能。\n·狂気爆発を6回発動するごとに「魔法のドングリ」×10を獲得、最大50回達成可能。\n·カードを20枚使用するごとに「魔法のドングリ」×10を獲得、最大50回達成可能。\n3、コア課題で一時解放された「覚醒体」、「命輪」、「鍵令」は通常通り「実績報酬」のカウント対象となります。フレンドマッチとパスワード対局は「実績報酬」のカウント対象外です。\n\n<Title:ターン奇賞>\n1、守秘者は「魔法のドングリ」を累積すると対応する報酬を受け取れます。「魔法のドングリ」×3600を累積するとすべてのコア報酬を獲得でき、「魔法のドングリ」×6000を累積するとすべての報酬を獲得できます！\n2、「逆転ターン：異界からの来客」クリア後に累積100–900「魔法のドングリ」の報酬が解放され、「逆転ターン：万象逆転の瞬間」クリア後に累積1000–6000「魔法のドングリ」の報酬が解放されます。\n\n<Title:多次元接続>\n1、イベント期間中「多次元接続：逆転ターン」が無料開放されます。\n2、イベント終了後、「多次元接続：逆転ターン」の調査進捗は保持されます。イベント期間中に「多次元接続：逆転ターン」を解放しなかった場合、イベント終了後も「現実起点」×3を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「多次元接続：逆転ターン」をクリアすると「鍵令：酒場の扉」を獲得できます。\n\n<Title:イベント期間>\n本イベントは3月16日 9:00–3月30日 9:00（GMT+8）の期間のみ開放されます。3月30日 9:00（GMT+8）以降イベントは終了しますので、守秘者の皆さんは「ターン奇賞」の報酬を忘れずに受け取ってくださいね！"
  },
  Activity_124801_BannerText = {
    Text = "特別イベント期間限定開催！"
  },
  Activity_124801_UnlockConditionExplanation = {
    Text = "「調査」3-2・通常をクリアで解放"
  },
  Activity_124834_ActivityName = {
    Text = "霧の名のもとに"
  },
  Activity_124834_ActivityPlot = {
    Text = "忘却前夜 × 霧境序列\nコラボ特別招待\n\n「茉夏、調査団の…………あ、いや、もう調査団の先鋒じゃないんだった。じゃあ、改めて自己紹介するね――私は茉夏、ただのかわいい女の子だよ〜」"
  },
  Activity_124834_ActivityTips = {
    Text = "<Title:イベントルール>\n·「霧の名のもとに」イベント期間中に調査行動第一章「東区秘事」をクリアすると、新たな限定SSR覚醒体「茉夏」を無料で獲得できます！\n·同一SSR覚醒体を2〜16回目に獲得した場合、毎回対応する覚醒体の欠片1個と「根源沈殿」×50に変換されます。17回目以降に獲得した場合、限定SSR覚醒体は「精粋霊核欠片」×2、「霊核欠片」×6、「根源沈殿」×250に変換されます。"
  },
