  Activity_124987_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「人格解析」のみ参加可能です。"
  },
  Activity_124987_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密保持者は期間限定プレイ「記憶エンコード」、「エッジストレージ」および「実績報酬」を通じてイベント通貨「記憶パズル」を収集できます。「記憶パズル」は「人格解析」で商品を購入でき、イベント限定SR命輪「銀鱈の決意」、流明の芯、無垢の芯などが含まれます。\n2、イベント期間中、「特遣記録：静寂の裂殖」が期間限定で無料解放されます。イベント実績を達成すると、イベント限定アイコン「銀鍵の名において：」24「」も獲得できます！\n\n<Title:イベント期間>\n1、2月23日 9:00–3月9日 9:00（GMT+8）、すべてのイベントプレイに参加可能。\n2、3月9日 9:00–3月16日 9:00（GMT+8）、「人格解析」と実績報酬のみ参加可能。\n\n<Title:記憶エンコード>\n1、「記憶エンコード」には5つのステージがあり、2日ごとに1つずつ自動開放されます。\n2、挑戦するたびに「霊啡肽」×120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能が解放されます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、校友会の助っ人と「共鳴：解離性症候」を使用して、より楽にクリアすることができます。\n\n<Title:理性ボーナス>\n1、秘密保持者が特定の覚醒体または命輪を所持している場合（編成不要）、「記憶エンコード」ステージ任務報酬の「記憶パズル」に追加のドロップボーナスが適用されます。具体的なボーナスは以下の通りです：\n·覚醒体「24」：啓霊0/1/2/3以上、ボーナス20％/30％/40％/50％。\n·SSR命輪「畸体回噬」：重位0/1/2/3以上、ボーナス20％/30％/40％/50％。\n·SR命輪「銀鱈の決意」：重位0/1/2/3以上、ボーナス20％/30％/40％/50％。\n2、異なる覚醒体または命輪の「理性ボーナス」は加算方式で計算されます。 \n3、特記事項として、狂乱難易度の初回クリア報酬は「理性ボーナス」の影響を受けません。\n\n<Title:共鳴：解離性症候>\n1、秘密保持者はイベント実績を達成することで「分裂の心」を獲得できます。 \n2、「分裂の心」を消費して「共鳴：解離性症候」を発動すると、以下のボーナスを獲得できます：\n（1）秘密保持者がイベントプレイ「記憶エンコード」と「特遣記録：静寂の裂殖」でより強くなり、挑戦がより楽になります。\n（2）「記憶エンコード」挑戦完了後に獲得できる報酬が増加します。\n（3）イベントプレイ「エッジストレージ」が解放されます。\n\n<Title: エッジストレージ>\n1、共鳴「診断：多重人格」を発動すると、毎時間自動的に「記憶パズルα」×60を獲得し、最大25時間分まで蓄積できます。\n2、共鳴「認知同調」を発動すると、毎時間自動的に「記憶パズルβ」×30を獲得し、最大25時間分まで蓄積できます。\n\n<Title:特遣記録>\n1、イベント期間中、「特遣記録：静寂の裂殖」が無料で解放されます。\n2、イベント終了後、「特遣記録：静寂の裂殖」の調査進捗は保持されます。イベント期間中に未完了の調査イベントを完了した場合も、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「特遣記録：静寂の裂殖」を解放しなかった場合、イベント終了後も「現実起点」×7を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「特遣記録：静寂の裂殖」をクリアすると「鍵令：すべての彼女」を獲得できます。\n\n<Title:復刻補填>\n1、以前に「特遣記録：静寂の裂殖」を解放済みの秘密保持者は、今回の復刻イベント期間中に再解放する際、「記憶パズルα」×700の補填を受け取れます。\n2、以前にイベント限定アイコン「銀鍵の名において：」24「」を獲得済みの秘密保持者は、重複獲得時に自動的に「無形者の招待状」×1に変換されます。\n3、以前に共鳴発動素材「分裂の心」を獲得済みの秘密保持者は、余分な「分裂の心」を1つ獲得するごとに自動的に「薔薇金券」×5000に変換されます。\n"
  },
