    Text = "<Title:イベントルール>\n・「魂の狩人」イベント開催中、守秘者は血ノ鎖・ヘロットを含む専用の編成を使用し、試遊ステージを体験できます。\n・試遊ステージでは、編成中の覚醒体の調整はできません。\n<Title:イベント報酬>\n・初めて試遊ステージをクリア後、イベント画面で報酬を受け取れます。"
  },
  Activity_125364_ActivityName = {
    Text = "海城旧聞"
  },
  Activity_125364_ActivityPlot = {
    Text = "権力、愛欲、紙酔金迷…………深い屋敷の中、屍が横たわる祭壇の上で、古き存在がゆっくりと目を開いた。\nああ、しかしこれは恐ろしい物語ではない。「彼」はあなたを「愛して」いる、「彼」は永遠にあなたを「守る」…………「彼」はすべての「最良のもの」を、あなたに捧げよう。"
  },
  Activity_125364_ActivityStageEndContent = {
    Text = "イベントは終了しました。現在は「荒宅野奉」のみ参加可能です"
  },
  Activity_125364_ActivityTips = {
    Text = "<Title:イベント概要>\n イベント期間中、秘密保持者は期間限定プレイ「玄女無相」と「実績報酬」を通じてイベント通貨「梨膏糖」を収集できます。「梨膏糖」は「荒宅野奉」で報酬と交換でき、イベント限定SR命輪「玉蘭の餌」、流明の芯、無垢の芯、賢石の欠片、擬態凝晶などが含まれます。\n\n<Title:玄女無相>\n1、「玄女無相」には探索不要で直接戦闘する素材ステージが9つ含まれ、毎日1つずつ開放されます。\n2、挑戦するたびに「霊啡肽」×120を消費し、挑戦成功で育成素材とイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能がアンロックされます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、同窓会の助っ人を使用して、より簡単にクリアすることができます。\n\n<Title:イベントボーナス>\n1、秘密保持者が特定の覚醒体または命輪を所持している場合（出撃不要）、「玄女無相」ステージ任務報酬の「梨膏糖」に追加のドロップボーナスが適用されます（再現を含む）。具体的なボーナスは以下の通りです：\n·覚醒体「徐」：啓霊0/1/2/3以上、ボーナス20%/30%/40%/50%\n·SSR命輪「枉蹙眉」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%\n·SR命輪「玉蘭の餌」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体または命輪の「イベントボーナス」は累積方式で計算されます。 \n3、特別に、狂乱難易度の初回クリア挑戦報酬は上記ボーナスの影響を受けません。\n\n<Title: 荒宅野奉>\n1、「供奉」するたびに750「梨膏糖」を消費し、「荒宅野奉」の中からランダムで5つのアイテム報酬を獲得します。\n2、「荒宅野奉」のアイテム報酬は「特殊アイテム」と「通常アイテム」の2種類に分かれ、リセット時に特殊アイテム報酬の残数を上限まで回復できます。具体的なルールは以下の通りです：\n（1）最初の5回のリセット：「特殊アイテム」の残数がなくなった後、秘密保持者はリセットを選択でき、リセット後は「特殊アイテム」と「通常アイテム」の残数が上限まで回復します。また、交換を続けることも可能で、「通常アイテム」の残数もなくなった場合、リセットしないと交換を続けられません。\n（2）6回目以降のリセット：「通常アイテム」の残数がなくなった後にのみリセットが可能で、リセットにより「通常アイテム」の残数が上限まで回復しますが、「特殊アイテム」はリセットされません。\n\n<Title:意識潜游>\n1、イベント期間中、「扇下夜談」は無料でアンロックできます。\n2、イベント終了後、「扇下夜談」の調査進捗は保持され、イベント期間中に未完了の調査イベントを完了した場合もイベント期間中と同じ調査報酬を獲得できます。イベント期間中に「扇下夜談」をアンロックしなかった場合、イベント終了後も「現実起点」×3を消費してアンロックできます。\n3、イベント期間中かどうかに関わらず、「意識潜游：扇下夜談」をクリアすると「鍵令：深宅往事」を獲得できます。\n\n<Title:イベント期間>\n1、1月26日 9:00 – 2月9日 9:00（GMT+8）、イベント概要のすべてのコンテンツに参加できます。\n2、2月9日 9:00 – 2月16日 9:00（GMT+8）、「荒宅野奉」と「実績報酬」のみ利用可能で、その他のコンテンツはすべて終了し参加できません。\n3、2月16日 9:00（GMT+8）以降、未交換の「梨膏糖」は1個につき「薔薇金券」×40の比率で回収されます。秘密保持者はメールをご確認ください。"
  },
