  Activity_126275_ActivityPlot = {
    Text = "紡輪は静かに回り、太古より止まることなく。糸に沿って踊れ、偉大なる織者よ。運命は、汝が逃れられぬ舞台。\n裁定者。救済者。主人。囚人…………\nこの舞台に足を踏み入れた時、汝に与えられた役は、もはや選ぶことなどできない。"
