  Activity_126275_ActivityStageEndContent = {
    Text = "イベントは終了しました。現在は「劇場ギフトショップ」のみ参加可能です"
  },
  Activity_126275_ActivityTips = {
    Text = "<Title:イベント概要>\nイベント期間中、守秘者は期間限定のプレイ「人形の舞台」と「達成報酬」を通じてイベント通貨「ベルベット座席券」を収集できます。「ベルベット座席券」は「劇場ギフトショップ」で報酬と交換でき、イベント限定のSR命輪「運命の糸車」、空幻のコア、ヘブンズコア、賢石の破片、擬態凝晶などが含まれます。\n\n<Title:人形の舞台>\n1、「人形の舞台」には探索なしで直接戦闘の素材ステージが5つ含まれており、2日ごとに1つが開放されます。\n2、各挑戦には「エンフェリン」× 120が消費され、挑戦成功により育成素材とイベント通貨が得られます。\n3、ステージクリア後、そのステージの「再現」機能が解放されます。注意：再現機能を使用する際は、同調率を得ることができません。\n4、同窓会の助戦を使用して、より楽にクリアすることができます。\n\n<Title:イベント加成>\n1、守秘者は特定の覚醒体または命輪（出陣は不要）を持っていると、「人形の舞台」ステージの任務報酬の「ベルベット座席券」に追加のドロップボーナスを与えることができます（再現を含む）。具体的なボーナスは以下の通りです：\n·覚醒体「アラクネ」：霊知0/1/2/3以上、ボーナス20%/30%/40%/50%\n·SSR命輪「永遠の織りの網」：重複位置0/1/2/3以上、ボーナス20%/30%/40%/50%\n·SR命輪「運命の糸車」：重複位置0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体または命輪の「活動加成」は重複して計算されます。\n3、特に、狂気の難易度の初回挑戦報酬は上記のボーナスの影響を受けません。\n\n<Title: 劇場ギフトショップ>\n1、各「ギフト交換」には750「ベルベット座席券」が消費され、「劇場ギフトショップ」の中の5つのアイテム報酬がランダムに得られます。\n2、「劇場ギフトショップ」のアイテム報酬は「特別アイテム」と「通常アイテム」の2種類に分かれており、リセット時に特別アイテムの残り数量を上限にリセットできます。具体的なルールは以下の通りです：\n（1）最初の5回のリセット：特別アイテムに残り数量がなくなった場合、守秘者はリセットを選択できます。リセット後、特別アイテムと通常アイテムの残り数量は上限にリセットされます。または、交換を続けることもできます。通常アイテムも残り数量がなくなった場合、リセットしなければ交換を続けることができません。\n（2）6回目以降のリセット：通常アイテムに残り数量がなくなった場合にのみリセットが行え、リセットは通常アイテムの残り数量を上限にリセットし、特別アイテムはリセットされません。\n\n<Title:イベント期間>\n1、4月20日9:00 - 5月18日9:00（GMT+8）、イベント概要のすべての内容に参加できます。\n2、5月18日9:00 - 5月25日9:00（GMT+8）、「劇場ギフトショップ」と「達成報酬」のみが残り、他の内容は終了し参加できません。\n3、5月25日9:00（GMT+8）以降、未交換の「ベルベット座席券」は各交換につき「薔薇金券」× 40の割合で回収されますので、守秘者はメールを確認してください。"
  },
  Activity_126275_BannerText = {
    Text = "遊興イベント期間限定開催！"
  },
  Activity_126365_ActivityName = {
    Text = "命縷紀行"
  },
  Activity_126365_ActivityTips = {
    Text = "イベントルール：\n1、秘密の番人が指定の紀行任務を完了すると、「命縷紀行」で報酬を受け取ることができます。\n2、「命縷紀行」は常時開放されています。\n3、「上級紀行」をアンロックすると、任務完了時に追加報酬を受け取ることができます。\n4、ご注意：本イベントでアンロックした「上級紀行」は本イベントでのみ有効です。秘密の番人の皆様は計画的にご利用ください。"
  },
  Activity_126366_ActivityName = {
    Text = "歴程追憶献礼·星辰篇Ⅴ"
  },
  Activity_126366_ActivityPlot = {
    Text = "封印された記憶、過去の行程。追憶の時、敬意を忘れずに。"
  },
  Activity_126492_ActivityName = {
    Text = "古国雑俎"
  },
  Activity_126492_ActivityTips = {
    Text = "<Title: 古国雑俎>\n·今回の期間限定紀行には8つのギフトパックが含まれ、最初のギフトパックは直接無料で受け取ることができ、第2〜8のギフトパックは「古国雑俎」を購入後に受け取ることができます。\n·「古国雑俎」を購入後、すぐに第2のギフトパック報酬を受け取ることができます。後続のギフトパックはそれぞれ一定時間経過後に受け取ることができます。\n·1月26日 9：00までに「古国雑俎」を購入すると、追加報酬として専用アイコン「扇中真形」、「無形者の招待状」×10を獲得できます！1月26日 9：00以降に購入した場合、期間限定専用報酬は獲得できなくなります。 \n· 購入後、今回の期間限定紀行の持続期間は永久となり、すべてのギフトパックを受け取った翌日にイベントが終了します。\n·「古国雑俎」の購入には期間制限があり、期限を過ぎると購入できなくなります。秘密保持者の皆様は2月23日 9：00までにご検討の上ご購入ください。"
  },
  Activity_126492_BannerText = {
    Text = "特別紀行イベント期間限定開催！"
  },
  Activity_127173_ActivityName = {Text = "描き手"},
  Activity_127173_ActivityTips = {
    Text = "<Title:イベントルール>\n・「画家」イベント開催中、守秘者はピックマンを含む専用の編成を使用し、試遊ステージを体験できます。\n・試遊ステージでは、編成中の覚醒体の調整はできません。\n<Title:イベント報酬>\n・初めて試遊ステージをクリア後、イベント画面で報酬を受け取れます。"
  },
  Activity_129488_ActivityName = {
    Text = "疾走する歓楽特急"
  },
  Activity_129488_ActivityPlot = {
    Text = "列車の中、苛立った咆哮が絶えず個室から響いてくる。\n「サルヴァドル、第三車両に支援が必要だ！」\n「ワンダ、お前が操っている敵を車両後部に送れ、奴らが追いついてきた！」\n「レック！ナンパしてないで！早く窓の外のやつを追い払ってくれ！」\n豪華個室で頭を抱えているあなたは、小さな影がこっそりとポケットに忍び込んだことにまったく気づいていなかった。\n「えへへ、やっぱりこうじゃなくっちゃ面白くないよね。」\n「なかなかいい映像が撮れたね〜じゃあ次は――お助けマン」N「ちゃんの出番だよ〜」"
  },
  Activity_129488_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密の守り手は「専用列車の軌跡」から豊富な期間限定報酬を獲得できます。イベント終了後は「専用列車の軌跡」の報酬は受け取れなくなりますので、期間限定報酬はお早めにお受け取りください。\n2、イベント期間中、「列車出発」に参加するとレベル補正が適用されます。具体的なルールは以下の通りです：\n  ·調査チーム内のレベル60未満の覚醒体は、今回のチャレンジ中レベル60まで補正されます。\n  ·調査チーム内のスキルレベル5未満の覚醒体は、今回のチャレンジ中スキルレベル5まで補正されます。\n  ·調査チーム内の「狂気の予兆」がレベル6未満の覚醒体は、今回のチャレンジ中レベル6まで補正されます。\n  ·調査チーム内の「霊塑適性」がレベル5未満の覚醒体は、今回のチャレンジ中レベル5まで補正されます。\n  ·秘密の守り手のレベルが60未満の場合、今回のチャレンジ中レベル60まで補正されます。\n\n<Title:特遣記録>\n1、イベント期間中「特遣記録：祈歳祭行きの列車」が無料で開放されます。\n2、イベント終了後、「特遣記録：祈歳祭行きの列車」の調査進捗は保持されます。イベント期間中に「特遣記録：祈歳祭行きの列車」を解放しなかった場合、イベント終了後も「現実起点」×7を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「特遣記録：祈歳祭行きの列車」をクリアすると「鍵令：歳末花火」を獲得できます。\n\n<Title:疾走する歓楽専用列車>\n1、「疾走する歓楽専用列車」は「星辰篇」ルールを採用した連続チャレンジモードです。秘密の守り手は変化に富むランダムエンカウントの中で、複数の調査行動に登場した最終ボスに連続で挑みます！\n2、プレイ中の造物所持上限は最大36個まで引き上げることができます。\n3、チャレンジ中は3種類の調査行動の強力な「共鳴」効果を同時に所持・強化できます。\n4、応急霊知体を1回使用するごとに、今回のチャレンジで獲得する「VIPポイント」が20％減少します。\n5、途中退出して進捗を保持することが可能ですが、チームの状態は外部の育成変化と同期更新されません。進捗は最大で前回のチャレンジから7日後まで保持され、保持期間中にチャレンジを続行しなかった場合はチャレンジ放棄とみなされ、進捗は保持されなくなります。\n\n<Title:VIP名簿>\n1、イベント期間中、「VIP名簿」の記録は保持されます。イベント終了後は学園イベントの周期に合わせて記録がリセットされます。\n2、「VIP名簿」にはチャレンジで優秀な成績を収めた秘密の守り手が記録されます。各期の学園イベント期間中に1回チャレンジし、「VIPポイント」の獲得に成功した秘密の守り手が「VIP名簿」に登録されます。\n3、「VIP名簿」のランキングは、1回のチャレンジで獲得した最多の「VIPポイント」と最少の「ターン数」を基準とします。繰り返しチャレンジしてランキングを上げることができます。\n\n<Title:イベント期間>\n1、2月9日 9:00〜3月9日 9:00（GMT+8）、すべてのイベントコンテンツに参加可能です。\n2、3月9日 9:00（GMT+8）以降、イベントは「記憶回廊」に収録され、「専用列車の軌跡」の報酬は受け取れなくなります。"
  },
