  Activity_130175_ActivityPlot = {
    Text = "世界はあまりにも物寂しく、世界はあまりにも荒れ果てて。\nどうか耳を傾けて、どうかその目を向けてほしい。\n軋む血肉が、長い沈黙の中で待ち続ける。タンポポが砂漠に咲き誇るその時を。\nやがてそれは、輝くほどの愛に満たされて、再び新たな命を得るだろう。"
