  },
  Activity_130175_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定ゲームプレイ「Darkroom Notes」と「達成報酬」を通じてイベント通貨「純白の鱗粉」「赤い鱗粉」「輝光の鱗粉」を収集し、「タンポポの園圃」で商品と交換できます。交換商品には、イベント限定SR命輪「汚泥の中の童話」、ルーメンのコア、ヘブンズコアなどが含まれます。\n2、イベント期間中、「チーム編成-多次元接続：Forgotten seeds of love」が期間限定で無料解放されます。さらにイベント実績を完了することで、イベント限定アイコン「銀の鍵の名において：沙耶」を獲得できます！\n\n<Title:イベント期間>\n1、5月30日 9:00 - 8月24日 9:00（GMT+8）、すべてのイベントゲームプレイに参加できます。\n2、8月24日 9:00 - 8月31日 9:00（GMT+8）、参加できるのは「タンポポの園圃」と達成報酬のみです。\n\n<Title:Darkroom Notes>\n1、「Darkroom Notes」には7つのステージがあり、毎日1つ自動で開放されます。\n2、挑戦ごとに「エンフェリン」×120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。注意：「リプレイ」機能を使用すると同調率を獲得できません。\n4、フレンドの救援を利用すると、より簡単にクリアできます。\n\n<Title: タンポポの園圃>\n1、「タンポポの園圃」には3つの店舗があり、開放時間は以下の通りです：\n·「育種園圃」： 5月30日 9時開放。\n·「生長園圃」： 5月31日 9時開放。\n·「満開園圃」： 6月1日 9時開放。\n2、1回の交換ごとに「純白の鱗粉」/「赤い鱗粉」/「輝光の鱗粉」×750を消費し、「タンポポの園圃」内の5つのアイテム報酬をランダムに獲得します。\n3、各「タンポポの園圃」のアイテム報酬は「特別アイテム」と「通常アイテム」の2種類に分かれます。リセット時に特別アイテム報酬の残量を上限まで戻すことができます。具体的なルールは以下の通り：\n（1）最初2回までのリセット：「特別アイテム」の数量がなくなった場合、守秘者はリセットを選ぶことができ、「特別アイテム」と「通常アイテム」の残量を上限まで戻せます。もしくはそのまま交換を続けることもできますが、「通常アイテム」も数量がなくなった場合は、リセットを行う必要があります。\n（2）3回目以降のリセット：「通常アイテム」の残り数量がなくなった場合にのみリセット可能になります。リセットにより「通常アイテム」の残量を上限まで戻せますが、「特別アイテム」は戻りません。\n\n<Title:イベントボーナス>\n1、特定の覚醒体や命輪を所持すると適用されます（参戦は不要）。「Darkroom Notes」ステージ報酬の3種類のイベント通貨に追加ドロップボーナスが得られます：\n·覚醒体「沙耶」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SSR命輪「花香る世界を願って」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SR命輪「汚泥の中の童話」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%。\n2、複数の「イベントボーナス」は累計で計算されます。 \n3、注意、狂気の難易度の初回クリア報酬は「イベントボーナス」の影響を受けません。\n\n<Title:多次元接続>\n1、イベント期間中、「チーム編成-多次元接続：Forgotten seeds of love」が無料で解放されます。\n2、イベント終了後も調査進度は保留されます。イベント期間中に完了しなかった調査事件をイベント後に完了した場合も、対応する報酬を獲得できます。イベント期間中に未ロックの場合、イベント終了後も「起点装置」×3を消費すれば解放可能です。\n3、イベント期間中・終了後にかかわらず、「チーム編成-多次元接続：Forgotten seeds of love」をクリアすると「キーオーダー：新しい世界への献身」を獲得できます。"
  },
