  Activity_130176_ActivityTips = {
    Text = "<Title:イベントルール>\n・「開花する愛」イベント開催期間中、守秘者は沙耶を含むシステム指定編成で、指定ステージを無制限に体験できます。\n・体験ステージプレイ時、編成中の覚醒体は変更できません。\n<Title:イベント報酬>\n・初回ステージクリア時、イベント画面で試遊報酬を受け取れます。"
  },
  Activity_130376_ActivityName = {
    Text = "一時的なテキスト"
  },
  Activity_130376_ActivityTips = {
    Text = "<Title:活動ルール>\n·「一時的テキスト」活動開催期間中、シークレットキーパーは暮星・ティンクトを含むシステムプリセット編隊を使用して、指定ステージを無制限に体験できます。\n·活動ステージを体験する際、編隊内の覚醒体を調整することはできません。\n<Title:活動報酬>\n·初めてステージ挑戦を達成した後、活動画面で試遊報酬を受け取ることができます。"
  },
