  Activity_130922_ActivityName = {Text = "渦巻き"},
  Activity_130922_ActivityTips = {
    Text = "<Title:イベントルール>\n·「渦」イベント開催期間中、秘密の番人はモスを含むシステムプリセットチームを使用して、指定ステージを無制限に体験できます。\n·体験イベントステージでは、編成中の覚醒体を調整することはできません。\n<Title:イベント報酬>\n·初めてステージチャレンジを達成すると、イベント画面で試遊報酬を受け取ることができます。"
  },
  Activity_130923_ActivityName = {
    Text = "霊知啓発パスⅡ"
  },
  Activity_130923_ActivityPlot = {
    Text = "購入後、「モス」は\n<BlueQuality:人格深化 +4、超限爆発を解放>可能"
  },
  Activity_130924_ActivityName = {
    Text = "霊知啓発パスⅠ"
  },
  Activity_130924_ActivityPlot = {
    Text = "購入後、「モス」の<BlueQuality:啓霊 3>を解放可能"
  },
  Activity_130925_ActivityName = {
    Text = "メスクスの呼び声"
  },
  Activity_130925_ActivityPlot = {
    Text = "大海の深淵で、渦がすべてを飲み込んでいる。\nメスクスの下の悪魔が巨大な口を開き、近づくすべての生き物を平等に招いている。\nそれは来る日も来る日も回転し、何度も何度も咆哮し、いつか必ず訪れる運命の者を呼んでいる。\nおいで、おいで、「水草」があなたを絡め取り、「礁石」があなたに寄り添う。漆黒の海底で、あなたは災いと踊る運命にある。\nそして災いもまた、あなたの最後の願いに応えるだろう。\nおかえりなさい、選ぶことのできない運命の者よ。"
  },
  Activity_130925_ActivityStageEndContent = {
    Text = "イベントは終了しました。現在は「モスの宝庫」のみ参加可能です"
  },
  Activity_130925_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密保持者は期間限定プレイ「モスと海」および「実績報酬」を通じてイベント通貨「海螺一号」、「海螺二号」、「海螺三号」を収集できます。「海螺一号」、「海螺二号」、「海螺三号」は「モスの宝庫」で商品を購入でき、イベント限定SR命輪「囚われし狂気」、流明の芯、無垢の芯などが含まれます。\n2、イベント期間中、「意識潜遊：沈溺」が期間限定で無料解放されます。イベント実績を達成すると、イベント限定アイコン「銀鍵の名において：モス」も獲得できます！\n\n<Title:イベント期間>\n1、3月9日 9:00–4月6日 9:00（GMT+8）、すべてのイベントプレイに参加可能。\n2、4月6日 9:00–4月13日 9:00（GMT+8）、「モスの宝庫」と実績報酬のみ参加可能。\n\n<Title:モスと海>\n1、「モスと海」には7つのステージがあり、1日ごとに1つずつ自動開放されます。\n2、挑戦するたびに「霊啡肽」×120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能が解放されます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、校友会の助っ人を使用して、より楽にクリアすることができます。\n\n<Title: モスの宝庫>\n1、「モスの宝庫」には3つのショップがあり、開放時間は以下の通りです：\n·「宝箱一号」：3月9日 9時に開放。\n·「宝箱二号」：3月10日 9時に開放。\n·「宝箱三号」：3月11日 9時に開放。\n2、交換するたびに「海螺一号」/「海螺二号」/「海螺三号」×750を消費し、「モスの宝庫」の中から5つのアイテム報酬をランダムに獲得します。\n3、各「モスの宝庫」のアイテム報酬は「特殊アイテム」と「通常アイテム」の2種類に分かれており、リセット時に特殊アイテム報酬の残数を上限まで戻すことができます。具体的なルールは以下の通りです：\n（1）最初の2回のリセット：「特殊アイテム」の残数がなくなった後、秘密保持者はリセットを選択でき、リセット後は「特殊アイテム」と「通常アイテム」の残数が上限まで戻ります。また、交換を続けることも可能で、「通常アイテム」の残数もなくなった場合、リセットを行わないと交換を続けられません。\n（2）3回目以降のリセット：「通常アイテム」の残数がなくなった後にのみリセットが可能で、リセットにより「通常アイテム」の残数が上限まで戻りますが、「特殊アイテム」はリセットされません。\n\n<Title:イベントボーナス>\n1、秘密保持者が特定の覚醒体または命輪を所持している場合（編成不要）、「モスの宝庫」ステージ任務報酬の「海螺一号」、「海螺二号」、「海螺三号」に追加のドロップボーナスが適用されます。具体的なボーナスは以下の通りです：\n·覚醒体「モス」：啓霊0/1/2/3以上、ボーナス20％/30％/40％/50％。\n·SSR命輪「遥かなるエデン」：重位0/1/2/3以上、ボーナス20％/30％/40％/50％。\n·SR命輪「囚われし狂気」：重位0/1/2/3以上、ボーナス20％/30％/40％/50％。\n2、異なる覚醒体または命輪の「イベントボーナス」は加算方式で計算されます。 \n3、特記事項として、狂乱難易度の初回クリア報酬は「イベントボーナス」の影響を受けません。\n\n<Title:意識潜遊>\n1、イベント期間中、「意識潜遊：沈溺」が無料で解放されます。\n2、イベント終了後、「意識潜遊：沈溺」の調査進捗は保持されます。イベント期間中に未完了の調査イベントを完了した場合も、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「意識潜遊：沈溺」を解放しなかった場合、イベント終了後も「現実起点」×3を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「意識潜遊：沈溺」をクリアすると「鍵令：溺死の純真」を獲得できます。"
  },
  Activity_130925_BannerText = {
    Text = "遊興イベント期間限定開催！"
  },
  Activity_131090_ActivityName = {
    Text = "燃える饗宴・復刻"
  },
  Activity_131090_ActivityPlot = {
    Text = "イサラウ、湖中の城……その場所はワンダの故郷と言い伝えられている。\n今、あなたは夢の門をくぐり抜け、無数の鐘が鳴り響く、古の塔群へと辿りつく……"
  },
  Activity_131090_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「ワンダの秘宝箱」のみ参加可能です。"
  },
  Activity_131090_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定プレイ「燃える群宴」と「実績報酬」でイベント通貨「原生脛骨」、「円葉菊石」、「螺旋遺跡」を収集できます。イベント通貨は「ワンダの珍宝匣」でイベント限定SR命輪「イサラウの眼差し」、流明の芯、無垢の芯などの商品を購入できます。\n2、イベント期間中、「意識潜游：燃える群宴」が期間限定で無料解放され、イベント実績を達成するとイベント限定アイコン「銀鍵の名の下に：ワンダ」も獲得できます！\n\n<Title:イベント期間>\n1、3月23日 9:00–4月20日 9:00（GMT+8）、すべてのイベントプレイに参加可能。\n2、4月20日 9:00–4月27日 9:00（GMT+8）、「ワンダの珍宝匣」と実績報酬のみ参加可能。\n\n<Title:湖中の城>\n1、「湖中の城」には7つのステージがあり、毎日1つ自動開放されます。\n2、挑戦するたびに「霊啡肽」×120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能が解放されます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、校友会の助っ人と「共鳴：代行密令」を使用して、より楽にクリアできます。\n\n<Title:珍宝ボーナス>\n1、守秘者が特定の覚醒体または命輪を所持している場合（出撃不要）、「湖中の城」ステージ任務報酬のイベント通貨に追加のドロップボーナスが付与されます。具体的なボーナスは以下の通りです：\n·覚醒体「ワンダ」：啓霊0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SSR命輪「女王の戒律」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SR命輪「イサラウの眼差し」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%。\n2、異なる覚醒体または命輪の「珍宝ボーナス」は加算方式で計算されます。\n3、特別に、狂乱難易度の初回クリア報酬は「珍宝ボーナス」の影響を受けません。\n\n<Title:共鳴：代行密令>\n1、守秘者はイベント実績を達成して「享楽の心」を獲得できます。\n2、「享楽の心」を消費して「共鳴：代行密令」を発動すると、守秘者は「湖中の城」でより強くなり、挑戦がより楽になります。また、クリア時に追加のイベント通貨を獲得できます。\n\n<Title:意識潜游>\n1、イベント期間中、「燃える群宴」を無料で解放できます。\n2、イベント終了後、「燃える群宴」の調査進捗は保持されます。イベント期間中に未完了の調査イベントを完了した場合も、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「燃える群宴」を解放しなかった場合、イベント終了後も「現実起点」×3を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「燃える群宴」をクリアすると「鍵令：腐爛の盛宴」を獲得できます。\n\n<Title:復刻補填>\n1、以前に「意識潜游：燃える群宴」を解放済みの守秘者は、今回の復刻イベント期間中に再解放時、「原生脛骨」×300の補填を獲得できます。\n2、以前にイベント限定アイコン「銀鍵の名の下に：ワンダ」を獲得済みの守秘者は、重複獲得時に自動的に「無形者の招待状」×1に変換されます。\n3、以前に共鳴発動素材「享楽の心」を獲得済みの守秘者は、余分な「享楽の心」1個につき自動的に「薔薇金券」×5000に変換されます。\n"
  },
