  Activity_131370_ActivityTips = {
    Text = "<Title:イベントルール>\n1、秘密保持者は指定の紀行任務を完了後、「ラッキーウィナー」で報酬を受け取ることができます。\n2、「ラッキーウィナー」は4月6日 9:00に終了します。\n3、「高級紀行」をアンロック後、任務完了時に追加報酬を受け取ることができます。\n4、ご注意：本イベントでアンロックした「高級紀行」は本イベントでのみ有効です。秘密保持者の皆様は計画的にご利用ください。"
  },
  Activity_131370_BannerText = {
    Text = "特別紀行イベント期間限定開催！"
  },
  Activity_131849_ActivityName = {
    Text = "永遠の記憶"
  },
  Activity_131849_ActivityTips = {
    Text = "<Title: 永遠の記憶>\n·今回の期間限定紀行には8つのパックが含まれ、最初のパックは無料で直接受け取ることができます。第2～8のパックは「永遠の記憶」を購入後に受け取ることができます。\n·「永遠の記憶」を購入すると、すぐに第2のパック報酬を受け取ることができます。以降のパックはそれぞれ一定時間経過後に受け取り可能になります。\n·5月30日 9：00までに「永遠の記憶」を購入すると、追加報酬として専用アイコン「愉快な捕食」、「無形者の招待状」×10を獲得できます！5月30日 9：00以降に購入した場合、期間限定専用報酬は獲得できません。\n·「永遠の記憶」の購入には期限があり、期限を過ぎると購入できなくなります。秘密保持者は6月29日 9：00までにご検討の上ご購入ください。"
  },
  Activity_131849_BannerText = {
    Text = "特別紀行イベント期間限定開催！"
  },
  Activity_132331_ActivityName = {
    Text = "マダム・レッド"
  },
  Activity_132331_ActivityTips = {
    Text = "<Title:イベントルール>\n·「レッドレディ」イベント開催期間中、秘密の守り手は「ソレイユ」を含むシステムプリセットチームを使用して、指定ステージを無制限で体験できます。\n·体験イベントステージでは、編成内の覚醒体を変更できません。\n<Title:イベント報酬>\n·初めてステージチャレンジを達成すると、イベント画面で試遊報酬を受け取れます。"
  },
  Activity_132332_ActivityName = {
    Text = "サブステージ無料解放"
  },
  Activity_132333_ActivityName = {
    Text = "神王の復活"
  },
  Activity_132333_ActivityPlot = {
    Text = "果てなき渇望の祈りの中、彼は長き眠りから束の間目覚め、退屈な世界へと真実の視線を投じる。\n\nしかし、永遠の生命の中では——\nその一時すら、あまりに短い。"
  },
  Activity_132333_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「意識の深淵」のみ参加可能です。"
  },
  Activity_132333_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密の守り手は期間限定プレイ「深海の凝視」と「実績報酬」を通じてイベント通貨「疲弊の緒思」、「悲愁の緒思」、「歓悦の緒思」を収集できます。イベント通貨は「覚知海淵」で商品を購入でき、イベント限定SR命輪「青石の王座」、流明の芯、無垢の芯、賢石の欠片、擬態凝晶などが含まれます。\n2、イベント期間中、イベント実績を達成すると、イベント限定アイコン「銀鍵の名のもとに：トゥルー」、イベント限定SR命輪「青石の王座」、銀芯、大量のイベント通貨も獲得できます！\n\n<Title:イベント期間>\n1、4月6日 9:00 – 5月4日 9:00（GMT+8）、すべてのイベントプレイに参加可能。\n2、5月4日 9:00 – 5月11日 9:00（GMT+8）、「覚知海淵」と実績報酬のみ参加可能。\n\n<Title:深海の凝視>\n1、「深海の凝視」には5つのステージがあり、2日ごとに1つ自動開放されます。\n2、挑戦するたびに「霊啡肽」×120を消費し、挑戦成功でイベント通貨を獲得します。\n3、ステージクリア後、そのステージの「再現」機能が解放されます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、校友会の助っ人を使用して、より簡単にクリアすることができます。\n\n<Title:緒思ボーナス>\n1、秘密の守り手が特定の覚醒体または命輪を所持している場合（編成不要）、「深海の凝視」ステージ任務報酬のイベント通貨に追加のドロップボーナスが適用されます。具体的なボーナスは以下の通りです：\n·覚醒体「トゥルー」：啓霊0/1/2/3以上、ボーナス20％/30％/40％/50％。\n·SSR命輪「神王の頌歌」：重ね位0/1/2/3以上、ボーナス20％/30％/40％/50％。\n·SR命輪「青石の王座」：重ね位0/1/2/3以上、ボーナス20％/30％/40％/50％。\n2、異なる覚醒体または命輪の「緒思ボーナス」は加算方式で計算されます。\n3、特別に、狂乱難易度の初回クリア報酬は「緒思ボーナス」の影響を受けません。\n\n<Title: 覚知海淵>\n1、「覚知海淵」は4月6日 9:00 – 5月11日 9:00（GMT+8）の期間のみ開放されます。\n2、5月11日 9:00（GMT+8）以降、未交換の「疲弊の緒思」、「悲愁の緒思」、「歓悦の緒思」は1個あたり「薔薇金券」×40の比率で回収されます。秘密の守り手はメールをご確認ください。\n\n<Title:意識潜游>\n1、イベント期間中、「意識潜游：戴冠の日」を無料で解放できます。\n2、イベント終了後、「意識潜游：戴冠の日」の調査進捗は保持され、イベント期間中に未完了の調査イベントを完了した場合も、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「意識潜游：戴冠の日」を解放しなかった場合、イベント終了後も「現実起点」×3を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「意識潜游：戴冠の日」をクリアすると「鍵令：群星の庇護」を獲得できます。\n\n<Title:復刻補填>\n1、以前に「意識潜游：戴冠の日」を解放済みの秘密の守り手は、今回の復刻イベント期間中に再度解放した際に「疲弊の緒思」×300の補填を獲得できます。\n2、以前にイベント限定アイコン「銀鍵の名のもとに：トゥルー」を獲得済みの秘密の守り手は、重複獲得時に自動的に「無形者の招待状」×1に変換されます。"
  },
