  Activity_132688_ActivityTips = {
    Text = "<Title:アクティビティ概要>\n 1、守秘者がアクティビティの指定タスクを完了すると、「流明之芯」・アクティビティ限定アバター「ウインクル·大型ターミナル」・「エリカ·ポータブルターミナル」・「コレクションの切手：守秘者」を受け取れる。さらに新登場の1星幻衣「ナウティラ·螺紋の反響」・「ヘロット·束縛の瞬間」などのアクティビティ限定報酬もあり！ \n 2、本アクティビティは永久開放です。アクティビティ内のすべてのタスクを完了し、報酬をすべて受け取った翌日9:00（GMT+8）以降、本アクティビティは終了し、表示されなくなります。\n 3、以前にログイン報酬機能で「PCデバイスでログイン」または「モバイルデバイスでログイン」タスクをすでに完了している場合、ここでは重複して完了とはカウントされません。"
