  Activity_132908_ActivityTips = {
    Text = "イベントルール：\n1、秘密保持者は指定の紀行任務を完了後、「仮テキスト」で報酬を受け取ることができます。\n2、「高級紀行」をアンロック後、任務完了時に追加報酬を受け取ることができます。\n3、今回の「高級紀行」の購入には期間制限があり、期限を過ぎると購入できなくなります。秘密保持者の皆様は5月20日9：00までにご検討の上ご購入ください。\n6、ご注意：本イベントでアンロックした「高級紀行」は本イベントでのみ有効です。秘密保持者の皆様は計画的にご利用ください。"
