  Activity_133272_ActivityName = {
    Text = "偉大なる征服·復刻"
  },
  Activity_133272_ActivityPlot = {
    Text = "偉大なる時代はいずれ滅びゆくかもしれない。だが、偉大なる勇士たちの意志は決して滅びない。\n墓碑は彼らを埋められず、鎖は彼らを馴らせない。\n新たなる征途が現れ、美味なる焼肉が征服の道の果てで手招きする時、戦士たちは突撃を開始し、栄光の戦利品を手中に収める。\nこの不滅の勇気のために、この神聖なる帝国のために高らかに歌おう！\nローマ！ローマ！"
  },
  Activity_133272_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「貢物の献上」のみ参加可能です。"
  },
  Activity_133272_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密の守り手は期間限定プレイ「神聖なる狩食」を通じてイベント通貨「美味レオ焼肉」を収集できます。「美味レオ焼肉」は「貢物を捧げよ」で商品を購入でき、流明の芯、無垢の芯などが含まれます。\n2、イベント期間中、「異夢視界：キッチン征服記」が期間限定で無料アンロックされます。\n\n<Title:イベント期間>\n1、5月4日 9:00–5月18日 9:00（GMT+8）、すべてのイベントプレイに参加可能です。\n2、5月18日 9:00–5月25日 9:00（GMT+8）、「貢物を捧げよ」と実績報酬のみ参加可能です。\n\n<Title:神聖なる狩食>\n1、「神聖なる狩食」には5つのステージが含まれ、2日ごとに1つ自動開放されます。\n2、挑戦するたびに「霊啡肽」×120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能がアンロックされます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、同窓会の助っ人を使用して、より簡単にクリアすることができます。\n\n<Title: 貢物を捧げよ>\n「貢物を捧げよ」ショップ内でイベント通貨「美味レオ焼肉」を使用して商品を選択し、直接購入できます。\n\n<Title:異夢視界>\n1、イベント期間中、「異夢視界：キッチン征服記」を無料でアンロックできます。\n2、イベント終了後、「異夢視界：キッチン征服記」の調査進捗は保持され、イベント期間中に未完了の調査イベントを完了した後もイベント期間中と同じ調査報酬を獲得できます。イベント期間中に「異夢視界：キッチン征服記」をアンロックしなかった場合、イベント終了後も「現実起点」×7を消費してアンロックできます。\n3、イベント期間中かどうかに関わらず、「異夢視界：キッチン征服記」をクリアすると「鍵令：狩食の決意」を獲得できます。"
  },
