  Activity_133301_ActivityTips = {
    Text = "<Title:イベントルール>\n1、旅人が指定されたバトルパスのクエストを完了すると、「フォンテーヌ茶韻」で報酬を受け取ることができます。\n2、「フォンテーヌ茶韻」は5月18日9:00に終了します。\n3、「上級バトルパス」を解放すると、クエスト完了後に追加報酬を受け取ることができます。\n4、ご注意：本イベントで解放した「上級バトルパス」は本イベント期間中のみ有効です。旅人の皆さんは計画的にご利用ください。"
