  },
  Activity_134393_ActivityTips = {
    Text = "<Title:イベントルール>\n·イベント期間中、秘密保持者は毎日ログイン後「群星に捧ぐ」にて記念限定SSR命輪「群星に捧ぐ」を受け取ることができます。合計16回受け取り可能です。\n·報酬は秘密保持者の累計ログインに応じて順次解放されます。当日のログイン報酬は9時（GMT+8）に更新されます。"
