  Activity_138582_ActivityTips = {
    Text = "<Title:イベントルール>\n1、秘密保持者は指定の紀行任務を達成すると、「桜庭茶会」で報酬を受け取れます。\n2、「桜庭茶会」は6月15日 09:00に終了します。\n3、「上級紀行」をアンロックすると、任務達成時に追加報酬を受け取れます。\n4、ご注意：本イベントでアンロックした「上級紀行」は本イベントのみ有効です。秘密保持者は計画的にご利用ください。"
  },
  Activity_138582_BannerText = {
    Text = "特別紀行イベント期間限定開催！"
  },
  Activity_139116_ActivityName = {
    Text = "夢のような出会い"
  },
  Activity_139116_ActivityTips = {
    Text = "<Title:イベントルール>\n·秘密保持者は指定の紀行任務を完了すると、「夢のような邂逅」にて報酬を受け取ることができます。\n·「上級紀行」を解放すると、任務完了後に追加報酬を受け取ることができます。\n·今回の「上級紀行」の購入には期限があり、期限を過ぎると購入できなくなります。秘密保持者は6月29日9：00（GMT+8）までにご検討の上ご購入ください。\n·ご注意：本イベントで解放された「上級紀行」は本イベントのみ有効です。秘密保持者は計画的にご利用ください。"
