  Activity_139117_ActivityName = {
    Text = "虚夢の贈り物"
  },
  Activity_139117_ActivityTips = {
    Text = "<Title:概要>\n·イベント期間中、秘密保持者は指定目標を達成すると「虚夢礼贈」で対応する報酬を受け取れます。"
  },
  Activity_139117_BannerText = {
    Text = "群星余夢を無料で獲得！"
  },
  Activity_139591_ActivityName = {
    Text = "猫の「恩返し」"
  },
  Activity_139591_ActivityPlot = {
    Text = "「緊急通知、全校の教職員・生徒は直ちに現在の作業を中断し、脱走した実験体の捕獲に協力してください。」\n「繰り返します、全校の教職員・生徒は直ちに現在の作業を中断し、脱走した…………くそっ！猫が入ってきた！」\n放送から慌てふためく声が聞こえた時、学園全体はすでに黒い毛玉に覆い尽くされ、皆が実験室から逃げ出した小さな悪戯っ子たちの捕獲に大わらわだった。\nどうやら祈歳祭の仕返しとばかりに、黒猫たちはゆっくりと整然とあなたの寮に集まってきている。\nとはいえ…………大量の金券と銀芯を持ってきていることを考えると、仕返しに来たのか「恩返し」に来たのか、判断しがたい。\n注意、乱獲は禁物ですよ。"
  },
  Activity_139591_ActivityStageEndContent = {
    Text = "イベント終了"
  },
  Activity_139591_ActivityTips = {
    Text = "<Title: 猫の「恩返し」>\n·猫の「恩返し」には7つの再現不可・直接挑戦のステージが含まれ、イベント期間中毎日1ステージずつ開放されます。\n·各挑戦で対応する「次元黒猫」を倒すと、任務進捗が累積され、「黒猫捕獲記録」にて対応する報酬を受け取ることができます。\n·各「次元黒猫」には大量の分身が存在し、イベント期間中は回数無制限で挑戦に参加でき、オート戦闘に対応しています。\n·各ステージでは異なる造物が提供され、強力なバフを付与します。\n·全ステージで助っ人の選択が必須です。イベント全体を通じて、相互フォローしている秘密保持者は1回のみ助っ人として参加できます。\n\n<Title: レベル補正>\n·猫の「恩返し」にはレベル補正メカニズムがあり、各秘密保持者が共に戦えるようになっています！\nレベル補正ルールは以下の通りです：\n  ·調査チーム内で、レベルが60未満の覚醒体は本挑戦中60レベルに補正されます。\n  ·調査チーム内で、スキルレベルが5未満の覚醒体は本挑戦中5レベルに補正されます。\n  ·調査チーム内で、「狂気の前兆」が6未満の覚醒体は本挑戦中6レベルに補正されます。\n  ·調査チーム内で、「霊塑適性」が5未満の覚醒体は本挑戦中5レベルに補正されます。\n  ·秘密保持者のレベルが60未満の場合、本挑戦中60レベルに補正されます。\n\n<Title:黒猫捕獲記録>\n·イベント期間中、秘密保持者は対応する「次元黒猫」を倒すと、対応する任務進捗が累積され、「黒猫捕獲記録」にて対応する報酬を受け取ることができます。「個人捕獲記録」と「学園捕獲記録」に分かれています。「個人捕獲記録」は秘密保持者の個人任務です。「学園捕獲記録」は学園全体の秘密保持者の任務です。\n\n<Title:捕獲ランキング>\n·イベント期間中、秘密保持者は「捕獲ランキング」にて「捕獲回数ランキング」と「協力回数ランキング」を確認できます。\n\n<Title:イベント期間>\n· 6月15日 9:00（GMT+8）まで、秘密保持者はイベントページからイベントに参加できます。この時間以降、新たな秘密保持者の挑戦参加は受け付けられません。イベントがまだ終了していない場合、既に参加している秘密保持者は引き続き挑戦を行えます。\n·6月15日 9:00（GMT+8）までに「捕獲総数」を達成した場合、イベントは6月29日 9:00（GMT+8）に終了します。6月15日 9:00（GMT+8）までに「捕獲総数」を達成できなかった場合、イベントは「捕獲総数」達成から14日後に終了します。"
  },
  Activity_139591_BannerText = {
    Text = "特別イベント期間限定開催！"
  },
  Activity_139922_ActivityTips = {
    Text = "<Title:イベントルール>\n・「催眠妖虫」イベント開催中、守秘者はクレメンタインを含む専用の編成を使用し、試遊ステージを体験できます。\n・試遊ステージでは、編成中の覚醒体の調整はできません。\n<Title:イベント報酬>\n・初めて試遊ステージをクリア後、イベント画面で報酬を受け取れます。"
  },
  Activity_139923_ActivityName = {
    Text = "無形の交響曲"
  },
  Activity_139923_ActivityPlot = {
    Text = "交響曲とは、織り成す芸術だ。異なる楽器の軌跡が交差し、縦横に広がる壮大な譜面を描く。\nその綾の中で、すべての音符がおのおのの役割を全うする。\n耳を傾けよ——比類なき交響曲が、今まさに幕を開ける。"
  },
  Activity_139923_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「安眠宮殿」のみ参加可能です。"
  },
  Activity_139923_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密保持者は期間限定プレイ「轟鳴の音」と「実績報酬」を通じてイベント通貨「高揚楽章」を収集できます。「高揚楽章」は「安眠宮殿」で豊富な報酬と交換でき、イベント限定SR命輪「永久に止まぬ演奏」、「無垢の芯」、「流明の芯」、「賢石の欠片」、「擬態凝晶」などが含まれます。\n2、イベント期間中、「実績報酬」の任務を達成するとイベント限定アイコン「銀鍵の名において：ハーメルン」、イベント限定SR命輪「永久に止まぬ演奏」、銀芯および大量のイベント通貨「高揚楽章」を獲得できます。\n\n<Title:イベント期間>\n1、6月15日 9:00 – 7月13日 9:00（GMT+8）、すべてのイベントコンテンツに参加可能。\n2、7月13日 9:00 – 7月20日 9:00（GMT+8）、「安眠宮殿」と「実績報酬」のみ利用可能、その他のコンテンツは終了し参加不可。\n\n<Title: 轟鳴の音>\n1、「轟鳴の音」には9つのステージがあり、毎日自動的に1つ開放されます。\n2、挑戦するたびに「霊啡肽」×120を消費し、異なるステージに挑戦すると異なる素材ドロップに加え、イベント通貨「高揚楽章」を獲得できます。\n3、本イベントのステージは直接戦闘の素材ステージで、クリア後に再現可能！「再現」するたびに「霊啡肽」×120を消費します。\n4、ご注意：「再現」機能を使用する際、同調率を獲得できません。\n\n<Title: 楽章ボーナス>\n1、秘密保持者が特定の覚醒体または命輪を所持している場合（編成不要）、「轟鳴の音」ステージ任務報酬の「高揚楽章」に追加のドロップボーナスが適用されます（再現を含む）。具体的なボーナスは以下の通り：\n·覚醒体「ハーメルン」：啓霊0/1/2/3以上、ボーナス20％/30％/40％/50％\n·SSR命輪「永遠安魂曲」：重位0/1/2/3以上、ボーナス20％/30％/40％/50％\n·SR命輪「永久に止まぬ演奏」：重位0/1/2/3以上、ボーナス20％/30％/40％/50％\n2、異なる覚醒体または命輪の「楽章ボーナス」は加算方式で計算されます。\n3、特別に、狂乱難易度の初回クリア報酬は「楽章ボーナス」の影響を受けません。\n\n<Title: 安眠宮殿>\n1、「安眠宮殿」は6月15日 9:00 – 7月13日 9:00（GMT+8）の期間のみ開放されます。\n2、7月20日 9:00（GMT+8）以降、未交換の「高揚楽章」は1個につき「薔薇金券」×40の比率で回収されます。秘密保持者はメールをご確認ください。"
  },
