  Activity_140082_ActivityStageEndContent = {
    Text = "イベントは終了しました。現在は「隠密の拠点」のみ参加可能です"
  },
  Activity_140082_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は限時ゲームプレイ「灰燼の追跡」、「紛争のない宴」および「実績報酬」を通じてイベント通貨「豊かさの」印「」、「死の」印「」、「戦争の」印「」を収集できます。「豊かさの」印「」、「死の」印「」、「戦争の」印「」は「隠れた拠点」で商品を購入するために使用でき、イベント限定SR命輪「迫近する太陽」、ルーメンのコア、ヘブンズコアなどが含まれます。\n2、イベント期間中、「不滅の極昼」が期間限定で無料解放され、イベント実績を達成すると、イベント限定アバター「銀の鍵の名において：ケティグラ」も獲得できます！\n\n<Title:イベント期間>\n1、9月7日 9:00 - 10月5日 9:00（GMT+8）、すべてのイベントゲームプレイに参加できます。\n2、10月5日 9:00 - 10月12日 9:00（GMT+8）、「隠れた拠点」と実績報酬のみ参加可能です。\n\n<Title:灰燼の追跡>\n1、「灰燼の追跡」には7つのステージが含まれ、1日ごとに1つ自動開放されます。\n2、挑戦するたびに「エンフェリン」× 120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。ご注意：「リプレイ」機能使用時は同調率を獲得できません。\n4、校友会の救援を使用して、より簡単にクリアすることができます。\n\n<Title: 隠れた拠点>\n「隠れた拠点」には三つのショップがあり、開始時間は以下の通りです：\n·「コレクションの宝庫」： 9月7日 9時開始。\n·「委託の秘密の部屋」： 9月8日 9時開始。\n·「戦闘キャンプ」： 9月9日 9時開始。\nショップ内で商品を選択して直接購入できます。\n\n<Title:イベントボーナス>\n1、守秘者が特定の覚醒体または命輪を所持している場合（出撃不要）、「灰燼の追跡」ステージタスク報酬の「豊かさの」印「」、「死の」印「」、「戦争の」印「」に追加ドロップボーナスが適用されます。具体的なボーナスは以下の通りです：\n·覚醒体「ケティグラ」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SSR命輪「琥珀色の死」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SR命輪「迫近する太陽」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%。\n2、異なる覚醒体または命輪の「イベントボーナス」は重複して計算されます。\n3、特に、狂気の難易度の初回クリア挑戦報酬は「イベントボーナス」の影響を受けません。\n\n<Title: 紛争のない宴>\n1、毎時間自動的に60「豊かさの」印「」を獲得し、最大25時間分を蓄積できます。\n\n<Title:意識潜行>\n1、イベント期間中、「不滅の極昼」を無料で解放できます。\n2、イベント終了後、「不滅の極昼」の調査進度は保留され、イベント期間中に完了しなかった調査事件を完了した後もイベント期間中と同じ調査報酬を獲得できます。イベント期間中に「不滅の極昼」を解放しなかった場合、イベント終了後も「起点装置」×3を消費して解放できます。\n3、イベント期間中かどうかにかかわらず、「意識潜行：不滅の極昼」をクリアすると「キーオーダー：沈まない太陽」を獲得できます。"
  },
