    Text = "<Title:活動ルール>\n1、守秘者が指定の紀行任務を完了すると、「秘境游記」で報酬を受け取れます。\n2、「秘境游記」は7月27日 09:00に終了します。\n3、「上級紀行」を解放後、任務完了で追加報酬を受け取れます。\n4、ご注意：本活動で解放した「上級紀行」は本活動のみ有効です。守秘者は理性的にご消費ください。"
  },
  Activity_141509_BannerText = {
    Text = "特別紀行イベント期間限定開催！"
