  Activity_141533_ActivityName = {
    Text = "永遠のエポヤンス"
  },
  Activity_141533_ActivityPlot = {
    Text = "声高らかに笑い、夜通し祝い合おう。\n鉤爪で敵の喉を貫き、平凡な時間を深淵の中で錆びさせよう。\n私たちはもう老い、平凡さ、孤独に捕まることはない。\nここはエポヤンス、私たちは永遠に幸せで、永遠に集い続ける。\n私たちは永遠に離れない。"
  },
  Activity_141533_ActivityStageEndContent = {
    Text = "活動は終了しました。現在は「果てなき狩場」のみ参加できます"
