  Activity_141533_ActivityTips = {
    Text = "<Title:活動概要>\n1、活動期間中、守秘者は期間限定ゲームプレイ「高所巡狩」と「実績報酬」で活動通貨「新鮮な」獲物「」「巨大な」獲物「」「古老の」獲物「」を収集し、「無辺の狩場」で商品と交換できます。活動限定SR命輪「岐路を指す羅針盤」、ルーメンのコア、ヘブンズコアなどが含まれます。\n2、活動期間中、「意識潜行：永遠のエポヤンス」が期間限定で無料解放されます。活動実績を達成すると活動限定アイコン「銀の鍵の名において：ポントス」も獲得できます！\n\n<Title:活動期間>\n1、6月29日 9:00 - 7月27日 9:00（GMT+8）、すべての活動ゲームプレイに参加できます。\n2、7月27日 9:00 - 8月3日 9:00（GMT+8）、「無辺の狩場」と実績報酬のみ参加できます。\n\n<Title:高所巡狩>\n1、「高所巡狩」には7つのステージが含まれ、毎日自動で1つ開放されます。\n2、挑戦するたびに「エンフェリン」×120を消費し、挑戦成功で活動通貨を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。ご注意：「リプレイ」機能使用時は同調率を獲得できません。\n4、校友会の救援を使用して、より楽にクリアできます。\n\n<Title: 無辺の狩場>\n「無辺の狩場」には三つのショップがあり、開放時間は以下の通りです：\n·「鉄弓矢」：6月29日 9時開放。\n·「熱兵器」：6月30日 9時開放。\n·「魔法」：7月1日 9時開放。\nショップ内で商品を選択して直接購入できます。\n\n<Title:活動ボーナス>\n1、守秘者が特定の覚醒体または命輪を所持している場合（出撃不要）、「高所巡狩」ステージ任務報酬の三種類の活動通貨のドロップに追加ボーナスが付与されます：\n·覚醒体「ポントス」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SSR命輪「生きた囚人籠」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SR命輪「岐路を指す羅針盤」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%。\n2、異なる覚醒体または命輪の「活動ボーナス」は重複して計算されます。\n3、特別に、狂気の難易度初回クリア挑戦報酬は「活動ボーナス」の影響を受けません。\n\n<Title:意識潜行>\n1、活動期間中、「意識潜行：永遠のエポヤンス」を無料解放できます。\n2、活動終了後、調査進度は保留されます。活動期間中に未完了の調査事件は活動後に完了しても対応する報酬を獲得できます。活動期間中に未解放の場合、活動終了後も「起点装置」×3を消費して解放できます。\n3、活動期間中かどうかに関わらず、「意識潜行：永遠のエポヤンス」をクリアすると「キーオーダー：ホロウマン」を獲得できます。"
  },
