  Activity_141535_ActivityPlot = {
    Text = "夏、海辺、眩い太陽、そして多くの見慣れた顔ぶれ。\n黒陽の照らす下、すべてを忘れ、あらゆる幻想を満たすこの狂宴の美夢に溺れよう。"
