  Activity_141535_ActivityTips = {
    Text = "<Title:活動概要>\n1、活動期間中、「異夢視界：さようなら、ネバーランド」が期間限定で無料解放！\n2、活動期間中、累計7日間ログインすると「彻夏狂欢」で「ルーメンのコア」×10を獲得でき、7日目にはさらに限定対戦アイコン「バレーボール『大将』」を追加獲得できます。\n\n<Title:活動期間>\n1、7月6日 9:00 - 7月20日 9:00（GMT+8）、すべての活動に参加できます。\n\n<Title:異夢視界>\n1、活動期間中、「異夢視界：さようなら、ネバーランド」を無料解放できます。\n2、活動終了後、「異夢視界：さようなら、ネバーランド」の調査進度は保留されます。活動期間中に未完了の調査事件を完了した場合も、活動期間中と同じ調査報酬を獲得できます。活動期間中に「異夢視界：さようなら、ネバーランド」を未ロックの場合、活動終了後も「起点装置」×7を消費して解放できます。\n3、活動期間中かどうかに関わらず、「異夢視界：さようなら、ネバーランド」をクリアすると「キーオーダー：定格された仲夏の記念」を獲得できます。"
