  Activity_144359_ActivityTips = {
    Text = "<Title:イベントルール>\n1、守秘者が指定の旅程タスクを完了すると、「万象を覗く」で報酬を受け取ることができます。\n2、「万象を覗く」は8月24日 9:00に終了します。\n3、「上級紀行」を解放後、タスク完了時に追加報酬を受け取ることができます。\n4、ご注意：本イベントで解放した「上級紀行」は本イベントのみ有効です。守秘者はご自身の判断で合理的にご消費ください。"
