  Activity_145382_ActivityTips = {
    Text = "<Title:イベントルール>\n·「堕ちた鯨」イベント開催期間中、守秘者は蝕滅・ロータンを含むシステムプリセット編隊を使用して、指定ステージを無制限に体験できます。\n·イベントステージ体験中は、編隊内の覚醒体を調整できません。\n<Title:イベント報酬>\n·初めてステージ挑戦を達成した後、イベント画面で試遊報酬を受け取ることができます。"
