  Activity_145458_ActivityName = {
    Text = "リヴァイアサンの遊戯"
  },
  Activity_145458_ActivityPlot = {
    Text = "強欲な英雄は不滅の王座を望み、絶望した母親は子の蘇生を望み、発狂した術士は禁忌の知識を望んだ――彼らはその御前に跪き、万年聞き続けた言葉で乞い願った。\n祂は彼らに全てを与え、そして彼らが全てを失うのを見届けた。祂は四千もの凄惨な角逐を見てきたが、決して満足することはなかった。\n今度は、闘技場の門があなたのために開かれる。さあ、祂に告げよ、あなたが渇望するものを。\n祂に告げよ、あなたがあの四千の亡魂と、一体何が違うのかを。"
  },
  Activity_145458_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「仮テキスト」のみ参加可能です。"
  },
  Activity_145458_ActivityTips = {
    Text = "<Title:イベント概要>\nイベント期間中、シークレットキーパーは期間限定コンテンツ「貪戮の角逐」と「実績報酬」でイベント通貨「血染めの供物」を集めることができます。「血染めの供物」は「闘技場の祭壇」で報酬と交換でき、イベント限定SR命輪「不滅の餓骨」、ルーメンのコア、ヘブンズコア、賢石の破片、擬態凝晶などが含まれます。\n\n<Title:貪戮の角逐>\n1、「貪戮の角逐」には 5 つのステージが含まれており、2 日ごとに 1 つ自動開放されます。\n2、挑戦するたびに「エンフェリン」× 120 を消費し、挑戦成功でイベント通貨「血染めの供物」を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。ご注意：「リプレイ」機能使用時は同調率を獲得できません。\n4、同窓会の助っ人を使用して、より楽にクリアすることができます。\n\n<Title:イベントボーナス>\n1、シークレットキーパーが特定の覚醒体または命輪を所持している場合（出撃不要）、「貪戮の角逐」ステージのクエスト報酬の「血染めの供物」に追加ドロップボーナスを付与できます（リプレイ含む）。具体的なボーナスは以下の通りです：\n·覚醒体「蝕滅・ロータン」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n·SSR命輪「天より堕ちる」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n·SR命輪「不滅の餓骨」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体または命輪の「イベントボーナス」は重複加算で計算されます。 \n3、特別に、狂気の難易度の初回クリア挑戦報酬は上記のボーナスの影響を受けません。\n\n<Title:意識潜行>\n1、イベント期間中、「意識潜行：鯨天陨落の時まで」を無料で解放できます。\n2、イベント終了後、「意識潜行：鯨天陨落の時まで」の調査進度は保留され、イベント期間中に未完了の調査事件を完了した後もイベント期間中と同じ調査報酬を獲得できます。イベント期間中に「意識潜行：鯨天陨落の時まで」を未ロックの場合、イベント終了後も「起点装置」×3を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「意識潜行：鯨天陨落の時まで」をクリアすると「キーオーダー：鯨を呑み込む嵐」を獲得できます。\n\n<Title:イベント期間>\n1、7 月 27 日 9:00 - 8 月 24 日 9:00（GMT+8）、イベント概要に記載されているすべてのコンテンツに参加できます。\n2、8 月 24 日 9:00 - 8 月 31 日 9:00（GMT+8）、「闘技場の祭壇」と「実績報酬」のみ残り、その他のコンテンツは終了済みで参加できません。\n3、8 月 31 日 9:00（GMT+8）以降、残った未交換の「血染めの供物」は1個につき「薔薇金券」× 40 の割合で回収されます。シークレットキーパーはメールの受け取りにご注意ください。"
  },
  Activity_145458_BannerText = {
    Text = "遊興イベント期間限定開催！"
  },
  Activity_145459_ActivityName = {
    Text = "サブステージ無料解放"
  },
  Activity_145465_ActivityName = {
    Text = "もしすべてが普段通りなら·クローン"
  },
  Activity_145465_ActivityPlot = {
    Text = "もし災厄が訪れなかったら、みんなの生活はどんなものだったのだろうと、あなたは想像したことがある。\n世界を救う力は使い道を失い、毎日平凡な学園生活とわずかな単位の取得に奔走する。グラウンドにはもう戦闘訓練の姿はなく、代わりに並ぶサークル活動のテントと、勧誘やはしゃぎ声が響く。下校のチャイムが鳴れば、腹を空かせた学生たちがたちまち食堂に押し寄せる…………\nあなたが気にかけている人たちの扉を叩いたら、どんな笑顔が見られるだろう？"
  },
  Activity_145465_ActivityStageEndContent = {
    Text = "[すべてが日常のままなら]イベントは終了しました。現在は「生徒会オフィスビル」のみ参加可能です"
