  Activity_145465_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定ゲームプレイ「陽光の下に新しいこと」でイベント通貨「海辺の特産貝殻」を集めることができます。「海辺の特産貝殻」は「学生会館」で商品の購入に使用でき、ルーメンのコア、ヘブンズコア、賢石の破片などが含まれます。\n2、イベント期間中、「異夢視界：さようなら、ネバーランド」が期間限定で無料解放！\n\n<Title:イベント期間>\n1、8月3日 9:00 - 8月17日 9:00（GMT+8）、すべてのイベントゲームプレイに参加できます。\n2、8月17日 9:00 - 8月24日 9:00（GMT+8）、「学生会館」と実績報酬のみ参加可能です。\n\n<Title:陽光の下に新しいこと>\n1、「陽光の下に新しいこと」には5つのステージが含まれ、2日ごとに1つ自動開放されます。\n2、挑戦するたびに「エンフェリン」×120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。ご注意：「リプレイ」機能使用時は同調率を獲得できません。\n4、同窓会の助っ人を使用して、より楽にクリアすることができます。\n\n<Title: 学生会館>\n「学生会館」にはショップが1つあり、8月3日 9時に開放されます。\nショップ内で商品を選択して直接購入できます。\n\n<Title:異夢視界>\n1、イベント期間中、「異夢視界：さようなら、ネバーランド」を無料で解放できます。\n2、イベント終了後、「異夢視界：さようなら、ネバーランド」の調査進度は保留され、イベント期間中に完了しなかった調査イベントを完了した後もイベント期間中と同じ調査報酬を獲得できます。イベント期間中に「異夢視界：さようなら、ネバーランド」を解放しなかった場合、イベント終了後も「起点装置」×7を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「異夢視界：さようなら、ネバーランド」をクリアした後に「キーオーダー：美夢の一瞬」を獲得できます。"
  },
  Activity_145465_BannerText = {
    Text = "遊興イベント期間限定開催！"
  },
  Activity_145466_ActivityName = {
    Text = "サブステージ無料解放"
  },
  Activity_145717_ActivityName = {
    Text = "新月と深雪"
  },
  Activity_145717_ActivityPlot = {
    Text = "七度の礼拝、三度の宣誓、あの純白の仙女への敬虔な信仰を胸に天と雪の境へと登りさえすれば、彼女はあなたのすべて、すべての願いを叶えてくれる。\nそれぞれの者にそれぞれの目的があり、それぞれの目的の下にそれぞれの嘘がある。\n彼らを掘り起こし、彼らを晒せ――無垢な表象に屈する前に。\n彼女と共にこの深雪へと沈んではならない。"
  },
  Activity_145717_ActivityStageEndContent = {
    Text = "活動は終了済みです。現在は「仙女の典儀」のみ参加可能です"
  },
  Activity_145717_ActivityTips = {
    Text = "<Title:活動概要>\n1、活動期間中、シークレットキーパーは期間限定ゲームプレイ「ウマーパティの宝物」と「実績報酬」で活動通貨「赤いリンゴ」「金のリンゴ」「飴リンゴ」を集め、「仙女の典儀」で商品と交換できます。交換品には活動限定SR命輪「穏やかな真実」、ルーメンのコア、ヘブンズコアなどが含まれます。\n2、活動期間中に活動実績を達成すると、活動限定アイコン「銀の鍵の名において：カラブ」も獲得できます！\n\n<Title:活動期間>\n1、8 月 24 日 9:00 - 9 月 21 日 9:00（GMT+8）、すべてのイベントゲームプレイに参加可能。\n2、9 月 21 日 9:00 - 9 月 28 日 9:00（GMT+8）、「仙女の典儀」と実績報酬のみ参加可能。\n\n<Title:ウマーパティの宝物>\n1、「ウマーパティの宝物」には 7 つのステージが含まれ、毎日自動的に 1 つ開放されます。\n2、挑戦するたびに「エンフェリン」× 120 を消費し、挑戦成功で活動通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能が解放されます。ご注意：「再現」機能使用時は同調率を獲得できません。\n4、同窓会の助っ人を使用して、より楽にクリアすることができます。\n\n<Title: 仙女の典儀>\n1、「仙女の典儀」には三つのショップがあり、開放時間は以下の通りです：\n·「浅雪の祝福」： 8 月 24 日 9 時開放。\n·「寒霜の祝福」： 8 月 25 日 9 時開放。\n·「純白の祝福」： 8 月 26 日 9 時開放。\n2、「祝福を受ける」ごとに「赤いリンゴ」/「金のリンゴ」/「飴リンゴ」× 750 を消費し、「仙女の典儀」の中からランダムで五つのアイテム報酬を獲得します。\n3、各「仙女の典儀」のアイテム報酬は「特別アイテム」と「通常アイテム」の二種類に分かれており、リセット時に特別アイテム報酬の残り数量を上限までリセットできます。具体的なルールは以下の通りです：\n（1）最初の2回のリセット：「特別アイテム」の残り数量がなくなった後、シークレットキーパーはリセットを選択できます。リセット後は「特別アイテム」と「通常アイテム」の残り数量が上限までリセットされます；また交換を続けることも選択でき、「通常アイテム」の残り数量もなくなった場合は、リセットを行わないと交換を続けられません。\n（2）3回目以降のリセット：「通常アイテム」の残り数量がなくなった後にのみリセットが可能となり、リセットにより「通常アイテム」の残り数量が上限までリセットされますが、「特別アイテム」はリセットされません。\n\n<Title:活動ボーナス>\n1、シークレットキーパーが特定の覚醒体または命輪を所持している場合（出撃不要）、「ウマーパティの宝物」のステージタスク報酬における三種類の活動通貨のドロップに追加ボーナスが付与されます：\n·覚醒体「カラブ」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SSR命輪「甘美な欺瞞」：重複位置0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SR命輪「穏やかな真実」：重複位置0/1/2/3以上、ボーナス20%/30%/40%/50%。\n2、複数の「活動ボーナス」は重複して計算されます。 \n3、ご注意：狂気の難易度の初回クリア挑戦報酬は「活動ボーナス」の影響を受けません。"
  },
