  Activity_15793_ActivityPlot = {
    Text = "雨が降る夜には、いつも失意と寂寥が付きまとう。\n愛を失う者、尊厳を失う者。\nそして、己の首を失う者もいる。"
  },
  Activity_15793_ActivityTips = {
    Text = "<Title:参加条件>\n·「調査行動」2–9·ノーマルをクリア後に参加可能。\n<Title:調査イベント>\n·イベント期間中、毎日「雨町の幽影」の新しい調査イベントが1つ公開されます。秘密保持者は物資を消費せずに調査を解放して実施でき、調査イベントをクリアすると無垢の芯、調査バッジ、秘密保持者経験値などの調査報酬を獲得できます。\n·イベント終了後、「雨町の幽影」の調査進捗は保持されます。秘密保持者は特遣記録で融蝕の珠を消費して未解放の調査を解放でき、イベント期間中に未完了の調査イベントをクリアした場合もイベント期間中と同じ調査報酬を獲得できます。<Title:期間限定報酬>\n·イベント期間中に期間限定報酬が登場します。秘密保持者が「雨町の幽影」ノーマルモードをクリアし、「雨町の幽影」の調査イベントを完了すると、無垢の芯、賢者の石、銀芯報酬を獲得できます！期間限定報酬はイベント期間中のみ開放され、イベント終了後は完了·受取ができなくなります。"
  },
