  },
  Activity_23671_ActivityTips = {
    Text = "イベントルール：\n1、「深潜対弈」イベント期間中、秘密保持者が「幻夢深潜」と「相位対弈」で獲得する秘密保持者経験値が倍増し、1日の上限が480ポイントに引き上げられます。同時にコア課題を解放している場合、その経路で獲得した秘密保持者経験値はさらに倍増しますが、1日の上限は480ポイントのまま変わりません。\n2、当日未使用の倍増秘密保持者経験値は翌日9時（GMT+8）にリセットされます。秘密保持者の皆さん、お早めに消化してくださいね〜"
  },
  Activity_23693_ActivityName = {
    Text = "蒼白の末裔"
  },
  Activity_23693_ActivityPlot = {
    Text = "伝説によると、ロンディニウムの地下には唯一の扉がある。\nそれは蒼白の主のもとへと通じている…………"
  },
  Activity_23693_ActivityTips = {
    Text = "<Title:参加条件>\n·意識潜游「騎士の願い」ノーマルモードをクリア後に参加可能。 \n<Title:調査イベント>\n·イベント期間中、毎日「蒼白の後裔」の新しい調査イベントが1つ公開されます。秘密保持者は物資を消費せずに調査を解放して実施でき、調査イベントをクリアすると無垢の芯、調査バッジ、秘密保持者経験値などの調査報酬を獲得できます。\n·イベント終了後、「蒼白の後裔」の調査進捗は保持されます。秘密保持者は意識潜游で融蝕の珠を消費して未解放の調査を解放でき、イベント期間中に未完了の調査イベントをクリアした場合もイベント期間中と同じ調査報酬を獲得できます。<Title:期間限定報酬>\n·イベント期間中に期間限定報酬が登場します。秘密保持者が「蒼白の後裔」ノーマルモードをクリアし、「蒼白の後裔」の調査イベントを完了すると、漆黒の錠前、銀芯報酬を獲得できます！期間限定報酬はイベント期間中のみ開放され、イベント終了後は完了·受取ができなくなります。"
  },
  Activity_23693_UnlockConditionExplanation = {
    Text = "意識潜行「騎士の願い」をクリアで解放"
  },
  Activity_23723_ActivityName = {
    Text = "嵐の前兆"
  },
  Activity_23723_ActivityTips = {
    Text = "イベントルール：\n1、イベント期間中、調査行動の第五章は一時的に閉鎖され、鍵令「永世の執念」は一時的に調査行動第四章のクリアで獲得できます。\n2、イベント終了後、調査行動第五章は再び開放され、鍵令「永世の執念」は引き続き調査行動第五章のクリアが必要となります。\n3、また、以前に達成した第五章の実績報酬、ステージ実績報酬、探索報酬、クリア報酬はすべて保持されます。再開放時（現在の予定は12月27日）、関連する完了済みの進捗は可能な限り引き継がれ、再度完了する必要はありません。"
  },
  Activity_23870_ActivityTips = {
    Text = "イベントルール：\n1、イベント期間中、イベントミッションを達成すると報酬を獲得できます。\n2、イベント終了後、未受取のイベント報酬は受け取れなくなります。秘密保持者の皆さんはお早めに受け取ることをお忘れなく〜"
  },
  Activity_23936_ActivityName = {
    Text = "昇格演繹"
