  Activity_23936_ActivityTips = {
    Text = "イベントルール：\n1、「昇格演繹」イベント期間中、秘密保持者が「海淵残像」で調査または再現を行うと、報酬が50％追加されます（秘密保持者経験値を除く）。1日の回数制限はありません。"
