  Activity_24194_ActivityName = {
    Text = "マダム・レッド"
  },
  Activity_24194_ActivityTips = {
    Text = "<Title:イベントルール>\n・「マダム・レッド」イベント開催中、守秘者はソレールを含む専用の編成を使用し、試遊ステージを体験できます。\n・試遊ステージでは、編成中の覚醒体の調整はできません。\n<Title:イベント報酬>\n・初めて試遊ステージをクリア後、イベント画面で報酬を受け取れます。"
  },
  Activity_24195_ActivityName = {
    Text = "泥濘の花"
  },
  Activity_24195_ActivityTips = {
    Text = "<Title:イベントルール>\n・「泥濘の花」イベント開催中、守秘者はリリーを含む専用の編成を使用し、試遊ステージを体験できます。\n・試遊ステージでは、編成中の覚醒体の調整はできません。\n<Title:イベント報酬>\n・初めて試遊ステージをクリア後、イベント画面で報酬を受け取れます。"
  },
  Activity_24992_ActivityName = {
    Text = "学園の贈り物"
  },
  Activity_24992_ActivityTips = {
    Text = "イベントルール：\n1、守秘者が毎日ログインすると、「学園の贈り物」で当日ログイン報酬を受け取れます。\n2、報酬は守秘者の累計ログインに応じて順次解放され、当日ログイン報酬は9:00（GMT+8）に更新されます。"
  },
  Activity_25011_ActivityName = {
    Text = "一歩の距離"
  },
  Activity_25011_ActivityPlot = {
    Text = "一歩前に進み、別の時空に足を踏み入れた。"
  },
  Activity_25011_ActivityTips = {
    Text = "<Title:参加条件>\n·意識潜游「騎士の願い」ノーマルモードをクリア後に参加可能。 \n<Title:調査イベント>\n·イベント期間中、毎日「一歩の距離」の新しい調査イベントが1つ公開されます。秘密保持者は物資を消費せずに調査を解放して実施でき、調査イベントをクリアすると無垢の芯、調査バッジ、秘密保持者経験値などの調査報酬を獲得できます。\n·イベント終了後、「一歩の距離」の調査進捗は保持されます。秘密保持者は意識潜游で融蝕の珠を消費して未解放の調査を解放でき、イベント期間中に未完了の調査イベントをクリアした場合もイベント期間中と同じ調査報酬を獲得できます。<Title:期間限定報酬>\n·イベント期間中に期間限定報酬が登場します。秘密保持者が「一歩の距離」ノーマルモードをクリアし、「一歩の距離」の調査イベントを完了すると、ラッキーキャンディ、銀芯報酬を獲得できます！期間限定報酬はイベント期間中のみ開放され、イベント終了後は完了·受取ができなくなります。"
  },
  Activity_25011_UnlockConditionExplanation = {
    Text = "意識潜行「騎士の願い」をクリアで解放"
  },
  Activity_25012_ActivityName = {
    Text = "薔薇の讃歌"
  },
  Activity_25012_ActivityPlot = {
    Text = "皆様、こんばんは。\n穏やかな夜の幕開けです。お手元には是非美酒のご用意を。\nこれは長い物語。どうぞごゆっくりお聞きください……"
  },
  Activity_25012_ActivityTips = {
    Text = "<Title:参加条件>\n·「調査行動」2–9·ノーマルをクリア後に参加可能。\n<Title:調査イベント>\n·イベント期間中、毎日「薔薇礼賛」の新しい調査イベントが1つ公開されます。秘密保持者は物資を消費せずにアンロックして調査を行うことができ、調査イベント完了後に無垢の芯、調査バッジ、秘密保持者経験値などの調査報酬を獲得できます。\n·イベント終了後、「薔薇礼賛」の調査進捗は保持され、秘密保持者は特遣記録で融蝕の珠を消費して未アンロックの調査をアンロックし、イベント期間中に未完了の調査イベントを完了することでイベント期間中と同じ調査報酬を獲得できます。<Title:期間限定報酬>\n·イベント期間中に期間限定報酬が登場します。秘密保持者は「薔薇礼賛」ノーマルモードをクリアし、「薔薇礼賛」の調査イベントを完了すると、無垢の芯、賢者の石、銀芯報酬を獲得できます！期間限定報酬はイベント期間中のみ開放され、イベント終了後は完了および受け取りができなくなります。"
  },
  Activity_25012_UnlockConditionExplanation = {
    Text = "「調査行動」2–9·ノーマル クリア後にアンロック"
  },
  Activity_34754_ActivityName = {
    Text = "物語の魔法"
  },
  Activity_34754_ActivityTips = {
    Text = "<Title:参加条件>\n・「調査」2-9・通常をクリア後に参加可能。\n<Title:調査>\n・イベント期間中、毎日「物語の魔法」の新しい調査が公開され、守秘者は物資を消費せずに調査を解放して実施できます。調査を完了すると、ヘブンズコア、調査勲章、守秘者経験値がもらえます。\n・イベント終了後も、「物語の魔法」の調査進捗は維持され、特務記録で融蝕の珠を消費して未解放の調査を解放し、イベント中に完了できなかった調査を完了すると、イベント中と同じ報酬が得られます。<Title:限定報酬>\n・イベント期間中に限定報酬が公開され、守秘者が「物語の魔法」通常モードをクリアし、「物語の魔法」の調査を完了すると、ヘブンズコア、賢者の石、シルバーコアが得られます。限定報酬はイベント期間中のみ開放され、イベント終了後は完了および受領できません。"
  },
  Activity_34755_ActivityName = {
    Text = "物語の魔法"
  },
  Activity_34755_ActivityTips = {
    Text = "<Title:イベント概要>\n・イベント期間中、「脚本の謎」プレイが期間限定で開放され、「特務記録：物語の魔法」が無料で解放されます！\n\n<Title:脚本の謎>\n・「脚本の謎」には9つの難易度のステージがあり、推奨レベルは30〜70で、低い難易度のステージをクリアすると、より高い難易度のステージが解放されます。\n・挑戦ごとにエンフェリン×60を消費し、クリアするたびにイベント通貨「揺蕩う閃き」を獲得できます。ステージの難易度が高いほど、獲得できる「揺蕩う閃き」が多くなります！\n・「揺蕩う閃き」は「魔法の脚本屋」で大量の覚醒体育成素材と交換でき、イベント限定SR運命の札「35mmの魔法」も交換できます。この運命の札は将来再登場または常設覚醒に追加される可能性があります。\n・挑戦ごとに、ボス以外の敵、イベント、マップがランダムに変化する可能性があり、ステージ内に出現する造物もより多くなります！\n・「脚本の謎」ではフレンドの救援を利用できます。\n\n<Title:共鳴と達成>\n・「演技の心」を消費して「共鳴：監督の演出指示」を活性化すると、守秘者は「脚本の謎」でより強くなり、挑戦をより簡単にできます。\n・守秘者は達成報酬を完了することで「演技の心」を獲得でき、さらに達成報酬からイベント限定アイコン「銀の鍵の名のもとに：リリー」も獲得できます！\n\n<Title:特務記録>\n・イベント期間中、毎日「物語の魔法」の新しい調査イベントが1つ公開されます。守秘者は物資を消費せずに解放して調査でき、調査イベントを完了するとヘブンズコア、調査バッジ、守秘者経験値などの調査報酬を獲得できます。\n・イベント終了後、「物語の魔法」の調査進捗は保持されます。守秘者は特務記録で融蝕の珠を消費して未解放の調査を解放でき、イベント期間中に未完了の調査イベントを完了しても、イベント期間中と同じ調査報酬を獲得できます。\n・イベント期間中に限定達成報酬が公開されます。守秘者は「物語の魔法」ノーマルモードをクリアし、「物語の魔法」の調査イベントを完了すると、達成報酬から銀芯報酬を受け取れます！達成報酬はイベント期間中のみ有効で、イベント終了後は完了・受取ができなくなります。\n"
  },
