  Activity_35844_ActivityName = {
    Text = "深海の淑女"
  },
  Activity_35844_ActivityTips = {
    Text = "<Title:イベントルール>\n・「深海の淑女」イベント開催中、守秘者はマーフィーを含む専用の編成を使用し、試遊ステージを体験できます。\n・試遊ステージでは、編成中の覚醒体の調整はできません。\n<Title:イベント報酬>\n・初めて試遊ステージをクリア後、イベント画面で報酬を受け取れます。"
  },
  Activity_35983_ActivityName = {
    Text = "学園の贈り物"
  },
  Activity_35983_ActivityTips = {
    Text = "イベントルール：\n1、守秘者が毎日ログインすると、「学園の贈り物」で当日ログイン報酬を受け取れます。\n2、報酬は守秘者の累計ログインに応じて順次解放され、当日ログイン報酬は9:00（GMT+8）に更新されます。"
  },
  Activity_36841_ActivityName = {
    Text = "いつも通り"
  },
  Activity_36841_ActivityPlot = {
    Text = "これはオレッタのシンプルで楽しい一日、これが彼女の毎日。"
  },
  Activity_36841_ActivityTips = {
    Text = "<Title:参加条件>\n·意識潜游「騎士の願い」ノーマルモードをクリア後に参加可能。 \n<Title:調査イベント>\n·イベント期間中、秘密保持者は物資を消費せずに調査を解放して実施でき、調査イベントをクリアすると無垢の芯、調査バッジ、秘密保持者経験値などの調査報酬を獲得できます。\n·イベント終了後、「万事如常」の調査進捗は保持されます。秘密保持者は意識潜游で融蝕の珠を消費して未解放の調査を解放でき、イベント期間中に未完了の調査イベントをクリアした場合もイベント期間中と同じ調査報酬を獲得できます。<Title:期間限定報酬>\n·イベント期間中に期間限定報酬が登場します。秘密保持者が「万事如常」ノーマルモードをクリアし、「万事如常」の調査イベントを完了すると、漆黒の錠前、銀芯報酬を獲得できます！期間限定報酬はイベント期間中のみ開放され、イベント終了後は完了·受取ができなくなります。"
  },
  Activity_36841_UnlockConditionExplanation = {
    Text = "意識潜行「騎士の願い」をクリアで解放"
  },
  Activity_36885_ActivityName = {
    Text = "燃える饗宴"
  },
  Activity_36886_ActivityName = {
    Text = "茨の女王"
  },
  Activity_36886_ActivityTips = {
    Text = "<Title:イベントルール>\n・「茨の女王」イベント開催中、守秘者はワンダを含む専用の編成を使用し、試遊ステージを体験できます。\n・試遊ステージでは、編成中の覚醒体の調整はできません。\n<Title:イベント報酬>\n・初めて試遊ステージをクリア後、イベント画面で報酬を受け取れます。"
  },
  Activity_38716_ActivityName = {
    Text = "調査リスタート"
  },
  Activity_38716_ActivityTips = {
    Text = "<Title:イベント概要>\n・守秘者は「帰校報酬」で直接「再起補給」報酬を受け取れます。\n・指定のトレーニングタスクを完了すると、「調査再起」イベントで報酬を受け取れます。\n・すべてのトレーニングタスクを完了すると、追加報酬も受け取れます。"
  },
  Activity_38717_ActivityName = {
    Text = "帰校報告"
  },
  Activity_38717_ActivityTips = {
    Text = "<Title:イベント概要>\n・守秘者は毎日ログイン後に「帰校報告」で当日ログイン報酬を受け取れます。\n・報酬は守秘者の累計ログインに応じて順次解放され、当日ログイン報酬は15:00に更新されます。"
  },
  Activity_38805_ActivityName = {
    Text = "燃える饗宴"
  },
  Activity_38805_ActivityPlot = {
    Text = "イサラウ、湖中の城……その場所はワンダの故郷と言い伝えられている。\n今、あなたは夢の門をくぐり抜け、無数の鐘が鳴り響く、古の塔群へと辿りつく……"
  },
  Activity_38805_ActivityTips = {
    Text = "<Title:イベント概要>\n・イベント期間中、「燃える饗宴」プレイが期間限定で開放され、「意識潜行：燃える饗宴」が期間限定で無料解放されます！\n\n<Title:湖中の城>\n・「湖中の城」には7つのステージがあり、2日ごとに1つ開放されます！各ステージの敵やイベントはランダムに変化する可能性があります。\n・ご注意ください。各ステージで報酬として得られる素材の種類、数量、混合比率は変化する可能性があります。早く開放されるステージほど素材の種類が単純で、遅く開放されるステージほど種類が豊富ですが総量も多くなります。ご自身のニーズに合わせて攻略方法を選んでください！\n・各ステージには7つの難易度があり、推奨レベルは15〜65で、すべての難易度がデフォルトで解放されています。\n・挑戦ごとにエンフェリン×120を消費し、難易度が高いほど獲得できる報酬が多くなります。自分に合った難易度を選んで挑戦してください。\n・ステージ報酬の素材は「ワンダの秘宝箱」商店で大量の覚醒体育成素材と交換でき、イベント限定アイコン「銀の鍵の名のもとに：ワンダ」も入手できます。\n・フレンドの救援と「共鳴：代行の密令」を利用すると、より簡単にクリアできます。\n\n<Title:共鳴と達成>\n・「享楽の心」を消費して「共鳴：代行の密令」を活性化すると、守秘者は「湖中の城」でより強くなり、挑戦をより簡単にできます。また、クリア時に追加のイベント通貨を獲得できます。\n・守秘者は達成報酬を完了することで「享楽の心」を獲得でき、「ワンダの秘宝箱」商店でも交換できます。\n\n<Title:意識潜行>\n・イベント期間中、「燃える饗宴」が無料で解放されます。毎日「燃える饗宴」の新しい調査イベントが1つ公開され、調査イベントを完了するとヘブンズコア、調査バッジ、守秘者経験値などの調査報酬を獲得できます。\n・イベント終了後も「燃える饗宴」の調査進捗は保持され、イベント期間中に未完了の調査イベントを完了しても、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「燃える饗宴」を解放しなかった場合、イベント終了後も「起点装置」×3を消費して解放できます。\n・イベント期間中に限定達成報酬が公開されます。守秘者は「燃える饗宴」の調査イベントを完了すると、達成報酬から銀芯報酬を受け取れます！達成報酬はイベント期間中のみ有効で、イベント終了後は完了・受取ができなくなります。\n"
  },
  Activity_41378_ActivityName = {
    Text = "禁区特訓"
  },
  Activity_41378_ActivityTips = {
    Text = "イベントルール：\n1、「禁区特訓」で指定された任務を完了すると、報酬を受け取れます。\n2、「禁区特訓」は恒常的に開放されます。\n3、「上級紀行」を解放すると、任務完了後に追加報酬を受け取れます。\n\n注意：「上級紀行」は本イベント内のみ有効です。慎重にご活用ください。"
  },
