  Activity_44273_ActivityName = {
    Text = "霊魂の牧人"
  },
  Activity_44273_ActivityPlot = {
    Text = "彼はあなた方のために苦しみを受けあなた方の災いをその身に担った。\n彼が捧げた血肉により、あなた方は癒され、彼が捧げた命により、あなた方は赦しを得た。"
  },
  Activity_44273_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定プレイ「聖堂の道」と「市民の善意」、「達成報酬」を通じてイベント通貨「チャリティ券」を収集できます。「チャリティ券」は「聖堂チャリティ会場」でランダムな商品と交換でき、交換報酬には、イベント限定SR運命の札「鏡の中の人」、ヘブンズコア、ルミナスコアなどが含まれます。\n2、「特務記録：血の色」をクリアすると新キーオーダー「神の御業」を獲得できます。イベント期間中、「特務記録：血の色」が期間限定で無料解放され、達成報酬を完了すると、イベント限定アイコン「銀の鍵の名のもとに：サルバドル」を獲得できます！\n\n<Title:聖堂の道>\n1、「聖堂の道」には5つのステージがあり、守秘者は「特務記録：血の色」の第2/4/6/7/9ステージをクリアすることで順次解放されます。\n2、各ステージには7つの難易度があり、推奨レベルは15〜65で、すべての難易度がデフォルトで解放されています。各ステージの敵やイベントはランダムに変化する可能性があります。\n3、フレンドの救援と「共鳴：魂の分岐点」を利用すると、より簡単にクリアできます。\n4、挑戦ごとに120点のエンフェリンを消費し、難易度が高いほど、クリア時に獲得できる「チャリティ券」が多くなります。また、守秘者はダブル挑戦を選択でき、240点のエンフェリンを消費して、2倍の「チャリティ券」と守秘者経験値を獲得できます。\n\n<Title:輝光ボーナス>\n1、「魂の輝光」の影響により、覚醒体「サルバドル」、SSR運命の札「神言の石板」、SR運命の札「鏡の中の人」は「聖堂の道」ステージ報酬の「チャリティ券」に追加ドロップボーナスを付与できます。具体的なボーナスは以下の通り：\n（1）方式一：守秘者が特定の覚醒体または運命の札を所持（参戦は不要）\n・覚醒体「サルバドル」：霊知啓発0/1/2/3以上、ボーナス30％/40％/50％/60％\n・SSR運命の札「神言の石板」：強化0/1/2/3以上、ボーナス30％/40％/50％/60％\n・SR運命の札「鏡の中の人」：強化0/1/2/3以上、ボーナス15％/20％/25％/30％\n（2）方式二：特定の覚醒体または運命の札の救援を使用\n・覚醒体「サルバドル」：ボーナス10％\n・SSR運命の札「神言の石板」：ボーナス10％\n・SR運命の札「鏡の中の人」：ボーナス5％\n2、同一の覚醒体または運命の札について、2つの方式の「輝光ボーナス」はより高い方のみが適用され、累計されません。\n3、異なる覚醒体や運命の札の「輝光ボーナス」は累計で計算されます。上記のルールに従い、守秘者は最大150％の「輝光ボーナス」を獲得できます！\n\n<Title:共鳴：魂の分岐点>\n1、守秘者は達成報酬を完了することで「悔恨の心」を獲得できます。\n2、「悔恨の心」を消費し、「共鳴：魂の分岐点」を起動すると、以下のボーナスを得られます：\n（1）イベントプレイ「聖堂の道」と「特務記録：血の色」において守秘者が強化され、挑戦が容易になります。\n（2）「聖堂の道」クリア後の同調率が向上します。\n（3）イベントコンテンツ「市民の善意」を起動できます。\n\n<Title:市民の善意>\n1、共鳴「安易な方法」を起動後、1時間ごとに60の「チャリティ券」を自動で獲得できます。最大25時間分を貯められます。\n2、共鳴「贖罪、贖罪」を起動後、1時間ごとに1800の薔薇金券を自動で追加獲得できます。\n\n<Title:聖堂チャリティ会場>\n1、守秘者は「チャリティ券」を使用して「聖堂チャリティ会場」の商店でランダムに商品を交換できます。イベント限定SR運命の札「鏡の中の人」、ルミナスコア、ヘブンズコアなどの商品があなたを待っています〜\n2、聖堂チャリティ会場には3つの商店があり、開放時間は以下の通りです：\n・商店「グレイおばさんの店」：初期開放。\n・商店「ジョン爺のマジカルバザー」：イベント4日目に開放。\n・商店「スミスの特別セール」：イベント7日目に開放。\n3、商店ごとに商品が異なりますので、守秘者は自分のニーズに合わせて商品を選んで交換してください。\n4、各商店には特別アイテムと通常アイテムが含まれ、1回の交換ごとに「チャリティ券」を600枚消費し、商店内の5つの商品をランダムに獲得します。\n5、商店内のすべての特別アイテムが交換された後、守秘者は商店の在庫補充を要求するか、そのまま交換を続けることができます。商店内のすべての商品が交換された場合、守秘者は在庫補充を行ってから交換を続ける必要があります。\n6、各商店の最初の2回の在庫補充では、商店内のすべての商品の残量が上限まで補充されます。3回目以降の在庫補充では、特別アイテムは補充されず、通常アイテムのみが補充されます。在庫補充後、それまでに交換しきれなかった商品の残量は保持されませんので、守秘者はよく考えてから在庫補充を選択してくださいね〜\n\n<Title:特務記録>\n1、イベント期間中、特務記録「血の色」が無料で解放されます。2日ごとに「血の色」の新しい調査イベントが公開され、調査イベントを完了するとキーオーダー「神の御業」、ヘブンズコア、調査バッジ、守秘者経験値などの調査報酬を獲得できます。\n2、イベント終了後、「血の色」の調査進捗は保持され、イベント期間中に未完了の調査イベントを完了しても、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「血の色」を解放していない場合、イベント終了後も「起点装置」×7を消費して解放できます。\n3、イベント期間中に限定達成報酬が公開されます。守秘者は「血の色」のすべての調査イベントを完了すると、達成報酬からアイコン「銀の鍵の名のもとに：サルバドル」を受け取れます！達成報酬はイベント期間中のみ有効で、イベント終了後は完了・受取ができなくなります。\n\n"
  },
