  Activity_45664_ActivityTips = {
    Text = "<Title:参加条件>\n·意識潜游「騎士の願い」ノーマルモードをクリア後に参加可能。 \n<Title:調査イベント>\n·イベント期間中、秘密保持者は物資を消費せずに調査を解放して実施でき、調査イベントをクリアすると無垢の芯、調査バッジ、秘密保持者経験値などの調査報酬を獲得できます。\n·イベント終了後、「巨人の隕落」の解放状態と調査進捗は保持され、イベント期間中に未完了の調査イベントをクリアした場合もイベント期間中と同じ調査報酬を獲得できます。イベント期間中に未解放の場合、イベント終了後に現実起点×3を消費して解放できます。<Title:期間限定報酬>\n·イベント期間中に期間限定報酬が登場します。秘密保持者が「巨人の隕落」ノーマルモードをクリアし、「巨人の隕落」の調査イベントを完了すると、次元凝晶、銀芯報酬を獲得できます！期間限定報酬はイベント期間中のみ開放され、イベント終了後は完了·受取ができなくなります。"
  },
  Activity_45664_UnlockConditionExplanation = {
    Text = "意識潜行「騎士の願い」をクリアで解放"
  },
  Activity_46167_ActivityName = {
