  },
  Activity_46167_ActivityTips = {
    Text = "<Title:イベントルール>\n・「分裂症患者・混沌」イベント開催中、守秘者は「24」を含む専用の編成を使用し、試遊ステージを体験できます。\n・試遊ステージでは、編成中の覚醒体の調整はできません。\n<Title:イベント報酬>\n・初めて試遊ステージをクリア後、イベント画面で報酬を受け取れます。"
