  Activity_46609_ActivityName = {
    Text = "多重治療"
  },
  Activity_46609_ActivityPlot = {
    Text = "「Hysteria」——別名ヒステリー症。\nこの時代、それはすなわち死を意味した。\nだが幸運にも、ミサゴの科学者と調査員もまた、正気の沙汰ではなかった。彼らは、この難題を克服することを決意したのだ。"
  },
  Activity_46609_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「人格解析」のみ参加可能です。"
  },
  Activity_46609_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「記憶の収集」と「大脳辺縁系」、「達成報酬」を通じてイベント通貨「記憶パズル」を収集できます。\n「記憶パズル」は「人格解析」で商品を購入でき、イベント限定SR運命の札「銀ダラの決意」、ルミナスコア、ヘブンズコア、賢者の石、豊富な育成素材が含まれます。\n2、「特務記録：静かな分裂」をクリアすると新たなキーオーダー「すべてが彼女」を獲得できます。イベント期間中、「特務記録：静かな分裂」が期間限定で無料解放され、イベント達成を完了するとイベント限定アイコン「銀の鍵の名のもとに：「24」」を獲得できます！\n\n<Title:イベント期間>\n1、4月27日 9:00 – 5月18日 9:00（GMT+8）の期間、すべてのイベント内容に参加でき、「特務記録：静かな分裂」が期間限定で無料解放されます。\n2、5月18日 9:00 – 5月25日 9:00（GMT+8）の期間、参加できるのは「人格解析」と「達成報酬」のみです。「特務記録：静かな分裂」は「起点装置」×7を消費して解放する必要があります。\n\n<Title:記憶の収集>\n1、「記憶の収集」には5つのステージがあり、守秘者は「特務記録：静かな分裂」の第2/4/6/8/10関をクリアすることで順次解放できます。\n2、各ステージには7つの難易度があり、推奨レベルは15〜65で、すべての難易度がデフォルトで解放されています。各ステージの敵とイベントはランダムに変化する可能性があります。\n3、フレンドの救援と「共鳴：解離性症候群」を利用すると、より簡単にクリアできます。\n4、挑戦ごとに120点のエンフェリンを消費し、難易度が高いほど、クリア時に獲得できる「記憶パズル」が多くなります。さらに守秘者は2倍挑戦を選択でき、240エンフェリンを消費して2倍の「記憶パズル」と守秘者経験値を獲得できます。\n\n<Title:理性ボーナス>\n1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「記憶の収集」ステージの任務報酬のイベント通貨「記憶パズル」の追加ドロップボーナスが得られます。\nボーナスは以下の通り：\n・覚醒体「「24」」：\n霊知啓発0/1/2/3以上、ボーナス15%/20%/25%/30%\n・覚醒体「ダフネ」：\n霊知啓発0/1/2/3以上、ボーナス15%/20%/25%/30%\n・SSR運命の札「奇体の反噬」：\n強化0/1/2/3以上、ボーナス15%/20%/25%/30%\n・SSR運命の札「至高の秘蔵品」：\n強化0/1/2/3以上、ボーナス15%/20%/25%/30%\n・SR運命の札「銀ダラの決意」：\n強化0/1/2/3以上、ボーナス15%/20%/25%/30%\n\n2、異なる覚醒体や運命の札の「理性ボーナス」は累計で計算されます。\n\n<Title:共鳴：解離性症候群>\n1、守秘者は達成報酬を完了することで「分裂の心」を獲得できます。\n2、「分裂の心」を消費し、「共鳴：解離性症候群」を起動すると、以下のボーナスを得られます：\n（1）イベントプレイ「記憶の収集」と「特務記録：静かな分裂」において守秘者が強化され、挑戦が容易になります。\n（2）「記憶の収集」クリア後の獲得報酬が向上します。\n（3）イベントコンテンツ「大脳辺縁系」を起動できます。\n\n<Title:大脳辺縁系>\n・共鳴「診断：人格分裂」を起動後、1時間ごとに60の「記憶パズルα」を自動で獲得できます。最大25時間分を貯められます。\n\n<Title:特務記録>\n1、イベント期間中、「特務記録：静かな分裂」が無料で解放されます。2日ごとに「静かな分裂」の新たな調査事件が追加され、調査事件を完了するとキーオーダー「すべてが彼女」、ヘブンズコア、調査バッジ、守秘者経験値などの調査報酬を獲得できます。\n2、イベント終了後、「特務記録：静かな分裂」の調査進捗は保持されます。イベント期間中に未完了の調査事件を完了しても、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「特務記録：静かな分裂」を解放していない場合、イベント終了後も「起点装置」×7を消費して解放できます。\n3、イベント期間中に期間限定の達成報酬が追加されます。守秘者が「特務記録：静かな分裂」のすべての調査事件を完了すると、イベント達成でアイコン「銀の鍵の名のもとに：「24」」を受け取れます！達成報酬はイベント期間中のみ開放され、イベント終了後は完了・受取ができなくなります。\n\n\n"
  },
