  Activity_48719_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「紊乱情欲」と「達成報酬」を通じてイベント通貨「豊穣の種核」を収集できます。\n「豊穣の種核」は「業の芽生え」で報酬と交換でき、交換報酬には、ルミナスコア、ヘブンズコア、豊富な育成素材が含まれます。\n2、イベント期間中、守秘者は「調査行動」2–9·通常をクリアするだけで「繁栄狂宴」に参加でき、覚醒体の同調率の条件を満たさなくても「繁栄狂宴事件」を解放できます。\nさらに、消費する「起点装置」数の要件も1個に減少します！\n3、神秘的な力の到来により、守秘者と覚醒体との関係がより深まる助けとなるようです。イベント期間中、すべての方法で獲得する同調率が2倍になります！\n\n<Title:イベント期間>\n1、5月18日 9:00 – 6月3日 9:00（GMT+8）の期間、イベント概要のすべての内容に参加できます。\n2、6月3日 9:00 – 6月10日 9:00（GMT+8）の期間、参加できるのは「業の芽生え」と「達成報酬」のみです。他の内容は終了となります。\n\n<Title:紊乱情欲>\n1、「紊乱情欲」には探索不要で直接戦闘を行うタイプの、10の素材獲得ステージがあり、毎日1つ開放されます。\n2、これらの素材獲得ステージでは、すべての覚醒体が直接覚醒し、設定された造物を獲得します。\nさらに、6ターン経過後に1度、タイスの助力を受けます。\n3、挑戦ごとに60点のエンフェリンを消費し、ステージクリア後にリプレイが解放されます。\n4、フレンドの救援を利用すると、より簡単にクリアできます。\n\n<Title:強欲ボーナス>\n1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「紊乱情欲」ステージの任務報酬のイベント通貨「豊穣の種核」の追加ドロップボーナスが得られます。（リプレイを含む）\nボーナスは以下の通り：\n・覚醒体「タイス」：\n霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「慈悲の育み」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「灼熱の吻別」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n\n2、異なる覚醒体や運命の札の「強欲ボーナス」は累計で計算されます。\n\n<Title:繁栄狂宴>\n1、「調査行動」7–3·通常をクリアすると、新たな特別調査コンテンツ「繁栄狂宴」が開放されます！\n2、「欲海翻波」イベントの到来により、覚醒体たちが神秘的な力の影響を受け、「繁栄狂宴」状態に陥りました…………守秘者の皆さん、ご注意ください！\n3、覚醒体の同調率が10級に達すると、その覚醒体の「繁栄狂宴事件」を解放でき、「起点装置」×7を消費して解放すると、「ヘブンズコア」×1を獲得できます！\n4、「欲海翻波」イベント期間中（6月3日 9:00前）、参加条件が「調査行動」2–9·通常クリアに緩和され、覚醒体の同調率の条件を満たさなくても「繁栄狂宴事件」を解放できます。さらに、消費する「起点装置」数の要件も1個に減少します！\n\n<Title:同調率2倍>\n1、神秘的な力の到来により、守秘者と覚醒体との関係がより深まる助けとなるようです。イベント期間中、すべての方法で獲得する同調率が2倍になります！\n2、他の同調率ボーナスとは乗算で計算されます（例：救援の同調率ボーナスなど）。\n<Title:達成報酬>\n1、すべての任務を完了すると報酬を獲得できます：銀芯×800、大量の「豊穣の種核」、イベント限定SR運命の札「灼熱の吻別」×16、イベント限定アイコン「銀の鍵の名のもとに：タイス」。\n2、16個の任務を含みます：「紊乱情欲」の各ステージを1回クリア、「紊乱情欲」で累計リプレイ10/20/30/40/50回、すべてのイベント達成を完了。\n\n\n\n"
  },
  Activity_48719_BannerText = {
    Text = "遊興イベント期間限定開催！"
  },
  Activity_48825_ActivityName = {
    Text = "校猫からのお礼"
  },
  Activity_48825_ActivityPlot = {
    Text = "以下の限定覚醒体から1体を選んで召喚！"
  },
  Activity_48825_ActivityTips = {
    Text = "<Title:概要>\n皆さまの熱い見守りがなければ、ミサゴは永遠に長い夜に埋もれていたかもしれません。今、私たちは約束を果たし、困難を乗り越え、半周年記念の時を迎えました。そこで、校猫が皆さまにこれまでの寄り添いへの感謝を込めて、特別な贈り物をお届けします。\n\n<Title:イベントルール>\n・イベント期間中、各守秘者は8体の限定SSR覚醒体から1体を選び、覚醒ができます。対象はトゥルー、ダフォダイル、ソレール、リリー、マーフィー、ワンダ、サルバドル、「24」。\n・既に覚醒している覚醒体を選ぶと、対応する覚醒体の欠片×1と根源の澱×50に変換されます。対象覚醒体の霊知啓発レベルが最大の場合は、霊核の欠片×1と根源の澱×150に変換されます。"
  },
  Activity_48825_BannerText = {
    Text = "限定覚醒体無料受取"
  },
  Activity_48826_ActivityName = {
    Text = "極夜と暁"
  },
  Activity_48826_ActivityPlot = {
    Text = "毎日ログインで記念限定SSR運命の札「極夜と暁」を合計16個受け取り可能！"
  },
  Activity_48826_ActivityTips = {
    Text = "<Title:概要>\nこれは守秘者へ捧げる一片の詩。理想について、信念について、そして手を携えて共に歩んだ時間について。真摯な心が決して鼓動を止めぬことを願い、銀の鍵が道を照らさんことを。\n\n<Title:イベントルール>\n・イベント期間中、守秘者は毎日「極夜と暁」で限定SSR運命の札「極夜と暁」を受け取り可能、合計16回。\n・報酬は守秘者の累計ログインに応じて順次解放され、当日ログイン報酬は9:00（GMT+8）に更新されます。"
  },
  Activity_48826_BannerText = {
