  Activity_48827_ActivityPlot = {
    Text = "不完全な統計によると、この半年間で校猫の帽子は学生たちに数千回も撮影され、いくつかの小さなシルバーコアが地面に落ちて誰も気にしませんでした。清掃担当の校務員は非常に困っており、学校はこれらのシルバーコアを収集して完全に洗浄し、失物招領所に保管していますので、持ち主は早急に取りに来てください。"
  },
  Activity_48827_ActivityTips = {
    Text = "<Title:概要>\nこの半年の間に、校猫の帽子は学生たちによって数千回も叩かれ、多くの小さく目立たないシルバーコアが地面に落ちているが、誰も気に留めていない。清掃を担当している校員は非常に困惑しており、現在学校はこれらのシルバーコアを回収し、完全に洗浄の上、遺失物置き場に保管している。持ち主は自ら取りに来てほしい。\n\n<Title:イベントルール>\n・イベント期間中、守秘者は毎日ログイン後に「帽子の中のシルバーコア」からシルバーコア×1000を受け取れ、最大で5回まで受け取れる。\n・報酬は守秘者の累計ログインに応じて順次解放され、当日ログイン報酬は9:00（GMT+8）に更新されます。"
