  Activity_51611_ActivityTips = {
    Text = "<Title:参加条件>\n・「調査」2-9・通常をクリア後に参加可能。\n<Title:調査>\n・イベント期間中、毎日「物語の魔法」の新しい調査が公開され、守秘者は物資を消費せずに調査を解放して実施できます。調査を完了すると、ヘブンズコア、調査勲章、守秘者経験値がもらえます。\n・イベント終了後も、「物語の魔法」の調査進捗は維持され、特務記録で融蝕の珠を消費して未解放の調査を解放し、イベント中に完了できなかった調査を完了すると、イベント中と同じ報酬が得られます。<Title:限定報酬>\n・イベント期間中に限定報酬が公開され、守秘者が「物語の魔法」通常モードをクリアし、「物語の魔法」の調査を完了すると、ヘブンズコア、賢者の石、シルバーコアが得られます。限定報酬はイベント期間中のみ開放され、イベント終了後は完了および受領できません。"
  },
