  Activity_52040_ActivityPlot = {
    Text = "深海の水鏡に映る影の中、王の夢は消え、神国もまた朽ち果てた。\n彼女は太古の幻夢から歩み出でて、未来の崩壊した廃墟に踏み入る。\n深淵に問うても、それはただ沈黙し深淵に祈れども、答えるは己のみ。"
