  Activity_52040_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「深淵の応答」のみ参加可能です。"
  },
  Activity_52040_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「神国の降臨」と「王の神託」、「達成報酬」を通じてイベント通貨を収集できます。\nイベント通貨は「深淵の応答」で捧げものとして使用し、交換報酬には、イベント限定SR運命の札「深海の呼び声」、賢石の破片、ヘブンズコア、ルミナスコアなどが含まれます。\n2、イベント期間中「異夢視界：冒涜」が無料で開放されます。\n\n<Title:イベント期間>\n1、6月17日9:00 - 7月1日9:00（GMT+8）の期間、すべてのイベント内容に参加できます。\n2、7月1日9:00 - 7月8日9:00（GMT+8）の期間、参加できるのは「深淵の応答」と「達成報酬」のみです。他の内容は終了となります。\n\n<Title: 神国の降臨>\n1、「神国の降臨」には5つのステージがあり、2日ごとに1つ自動で開放されます。\n2、挑戦ごとに120点のエンフェリンを消費し、イベント通貨「祭祀者の涙」、「祭祀者の血」、「祭祀者の髄」を獲得できます。ダブル挑戦時は240点のエンフェリンを消費し、ステージ任務報酬も2倍になりますが、同調率報酬は変わりません。\n3、「達成報酬」の完成度が100%に達すると、クリア済みステージの「リプレイ」機能が解放されます。\n1回の「リプレイ」には120点のエンフェリンを消費します。\n※注意：「リプレイ」機能を使用すると同調率を獲得できません。\n4、フレンドの救援と「共鳴：海淵の祭儀」を利用すると、より簡単にクリアできます。\n\n<Title: 祀物ボーナス>\n1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「神国の降臨」ステージ任務報酬のイベント通貨「祭祀者の涙」、「祭祀者の血」、「祭祀者の髄」の追加ドロップボーナスが得られます。（リプレイを含む）\nボーナスは以下の通り：\n・覚醒体「ミリアム」：\n霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「信仰の力」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「深海の呼び声」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n\n2、異なる覚醒体や運命の札の「祀物ボーナス」は累計で計算されます。\n\n<Title:共鳴：海淵の祭儀>\n1、守秘者は達成報酬を完了することで「敬虔の心」を獲得できます。\n2、「敬虔の心」を消費し、「共鳴：海淵の祭儀」を起動すると、以下のボーナスを得られます：\n（1）イベントプレイ「神国の降臨」において守秘者が強化され、挑戦が容易になります。\n（2）「神国の降臨」クリア時に獲得できるイベント通貨が増加します。\n（3）イベントコンテンツ「王の神託」を起動できます。\n\n<Title: 王の神託>\n・共鳴「生贄の試練」を起動後、1時間ごとに60の「祭祀者の涙」を自動で獲得できます。最大25時間分を貯められます。\n\n<Title: 深淵の応答>\n1、「深淵の応答」には3つの祭壇があり、開放時間は以下の通りです。\n・「晶泪の祭壇」：6月17日9:00開放。\n・「紅血の祭壇」：6月19日9:00開放。\n・「霊髄の祭壇」：6月21日9:00開放。\n2、1回の捧げ物ごとに「祭祀者の涙」/「祭祀者の血」/「祭祀者の髄」を500消費し、祭壇内のアイテム報酬から5つをランダムに獲得します。\n3、各祭壇のアイテム報酬は「神国の恩恵」と「凡庸の報酬」の2種類に分かれます。リセット時に指定アイテム報酬の残量を上限まで戻すことができます。\n具体的なルールは以下の通りです：\n（1）最初2回までのリセット：「神国の恩恵」の数量がなくなった場合、守秘者がリセットを選ぶことができ、「神国の恩恵」と「凡庸の報酬」の残量を上限まで戻せます。\nもしくは、そのまま捧げ物を続けることもできますが、「凡庸の報酬」も数量がなくなった場合は、リセットを行う必要があります。\n\n（2）3回目以降のリセット：「凡庸の報酬」の残り数量がなくなった場合にのみリセット可能になります。リセットにより「凡庸の報酬」の残量を上限まで戻せますが、「神国の恩恵」は戻りません。\n\n<Title: 異夢視界>\n1、「異夢視界」は新しい調査タイプです。通常のストーリー形式と比べて、よりテキスト表現に重きが置かれ、テキストの内容量も多くなっています。\n2、「異夢視界：冒涜」では、ミリアムの精神とのリンクを通じて、直接彼女の記憶を読み取り、以下の出来事を目撃します。\n幼少期のミリアムがリモリアの苦難を一つ一つ経験し、信仰の中で迷い、信仰の中でもがき、最終的に救世主と破壊者となる道を歩んでいきます…………\n3、イベント期間中「異夢視界：冒涜」が無料で解放されます。また、2日ごとに新しいストーリーが追加されます。\nクリア後に達成報酬として、シルバーコアや、イベント限定SR運命の札「深海の呼び声」などの報酬を獲得できます。達成報酬はイベント期間中にのみ開放され、イベント終了後は完了と受け取りができなくなります。\n4、イベント終了後、「異夢視界：冒涜」の調査進捗は保持されます。\nイベント期間中に「異夢視界：冒涜」を解放していない場合、イベント終了後も「起点装置」×7を消費して解放できます。\n5、イベント期間中かどうかに関わらず、「異夢視界：冒涜」をクリアすると「キーオーダー：海の祭」を獲得できます。\n\n\n\n"
  },
  Activity_52040_BannerText = {
    Text = "遊興イベント期間限定開催！"
  },
  Activity_53727_ActivityName = {
    Text = "復帰任務"
  },
  Activity_53727_ActivityTips = {
    Text = "<Title:イベント概要>\n・「復帰任務」タスクは4つのグループに分かれており、イベント開始の第1、2、3、4日に解放されます。\n・守秘者は「復帰任務」タスクを完了することで「カムバックチケット」を獲得できます。\n・「カムバックチケット」を使用して「復帰商店」で豊富な報酬と交換可能です。"
  },
  Activity_53728_ActivityName = {
    Text = "新たな旅の支援"
  },
  Activity_53728_ActivityTips = {
    Text = "<Title:イベント概要>\n·「新たな旅の支援」期間中、守秘者が「薬剤収集」「混濁の残像」「海底の残像」「血肉の残像」「次元の残像」「混沌地帯」「ポナペの廃墟」「蠕虫の棲家」「時空のくびれ」をクリアすると、薔薇金券と素材の報酬が2倍になります。毎日6回まで利用可能です。\n·当日の2倍報酬回数が翌日9:00（GMT+8）にリセットされるため、守秘者にはお早めの利用をお勧めします〜"
  },
  Activity_53729_ActivityName = {
    Text = "帰校報告"
  },
  Activity_53729_ActivityTips = {
    Text = "<Title:イベント概要>\n・守秘者は毎日ログイン後に「帰校報告」で当日ログイン報酬を受け取れます。\n・報酬は守秘者の累計ログインに応じて順次解放され、当日ログイン報酬は15:00に更新されます。"
  },
  Activity_53829_ActivityName = {
    Text = "薔薇の書"
  },
  Activity_53829_ActivityPlot = {
    Text = "煌びやかなダイヤモンド、まばゆい真珠の輝き……\n無数の華やかな装飾が、女帝であるかのような空虚な幻想をもたらす。\n今、彼女はその空虚を永遠に保つことを決意した。"
  },
  Activity_53829_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「金紅祭典」のみ参加可能です。"
  },
  Activity_53829_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「薔薇の記憶」と「達成報酬」を通じてイベント通貨「霊鳥の羽扇」を収集できます。「霊鳥の羽扇」は「金紅祭典」で豪華報酬と交換でき、交換報酬には、イベント限定SR運命の札「百万寵愛の眼」、ルミナスコア、ヘブンズコア、賢石の破片、擬態凝晶などが含まれます。\n2、イベント期間中、「達成報酬」の任務を完了するとイベント限定アイコン「銀の鍵の名のもとに：ソレール」、イベント限定SR運命の札「百万寵愛の眼」、シルバーコアおよび大量のイベント通貨「霊鳥の羽扇」を獲得できます。\n3、イベント期間中、「特務記録：薔薇の讃歌」が無料で開放されます。\n\n<Title:イベント期間>\n1、7月1日 9:00 - 7月15日 9:00（GMT+8）の期間、すべてのイベント内容に参加できます。\n2、7月15日 9:00 - 7月22日 9:00（GMT+8）の期間、参加できるのは「金紅祭典」と「達成報酬」のみで、その他のコンテンツは終了し参加できません。\n\n<Title:薔薇の記憶>\n1、「薔薇の記憶」には9つのステージがあり、毎日1つ自動で開放されます。\n2、各挑戦には「エンフェリン」×120を消費し、ステージ毎に異なる素材ドロップと、イベント通貨「霊鳥の羽扇」を獲得できます。\n3、今回のイベントは直接戦闘の素材ステージとなり、ステージクリア後、そのステージの「リプレイ」機能が解放されます。各「リプレイ」には「エンフェリン」×120を消費します。\n4、注意：「リプレイ」機能を使用すると同調率を獲得できません。\n\n<Title:羽扇ボーナス>\n1、守秘者が特定の覚醒体または運命の札を所持している場合（編成は不要）、「薔薇の記憶」ステージ報酬のイベント通貨「霊鳥の羽扇」の追加ドロップボーナスが得られます。（リプレイを含む）\n具体的なボーナスは以下の通り：\n・覚醒体「ソレール」：霊知啓発0/1/2/3以上、ボーナス20％/30％/40％/50％\n・SSR運命の札「薔薇の名において」：強化0/1/2/3以上、ボーナス20％/30％/40％/50％\n・SR運命の札「百万寵愛の眼」：強化0/1/2/3以上、ボーナス20％/30％/40％/50％\n2、異なる覚醒体や運命の札の「羽扇ボーナス」は累計で計算されます。\n\n<Title:特務記録>\n1、イベント期間中、すでに「特務記録：薔薇の讃歌」を解放済みの守秘者は、再解放時に「霊鳥の羽扇」×600の補償を獲得できます。\n2、「特務記録：薔薇の讃歌」では、守秘者はストーリープリセット「ソレール」を含む特殊編成で挑戦します。"
  },
  Activity_53829_BannerText = {
    Text = "遊興イベント期間限定開催！"
  },
  Activity_54375_ActivityName = {
    Text = "薔薇の讃歌"
  },
  Activity_54375_ActivityPlot = {
    Text = "皆様、こんばんは。\n穏やかな夜の幕開けです。お手元には是非美酒のご用意を。\nこれは長い物語。どうぞごゆっくりお聞きください……"
  },
  Activity_54375_ActivityTips = {
    Text = "<Title:参加条件>\n·「調査行動」2–9·ノーマルをクリア後に参加可能。\n<Title:調査イベント>\n·イベント期間中、毎日「薔薇礼賛」の新しい調査イベントが1つ公開されます。秘密保持者は物資を消費せずにアンロックして調査を行うことができ、調査イベント完了後に無垢の芯、調査バッジ、秘密保持者経験値などの調査報酬を獲得できます。\n·イベント終了後、「薔薇礼賛」の調査進捗は保持され、秘密保持者は特遣記録で融蝕の珠を消費して未アンロックの調査をアンロックし、イベント期間中に未完了の調査イベントを完了することでイベント期間中と同じ調査報酬を獲得できます。<Title:期間限定報酬>\n·イベント期間中に期間限定報酬が登場します。秘密保持者は「薔薇礼賛」ノーマルモードをクリアし、「薔薇礼賛」の調査イベントを完了すると、無垢の芯、賢者の石、銀芯報酬を獲得できます！期間限定報酬はイベント期間中のみ開放され、イベント終了後は完了および受け取りができなくなります。"
  },
  Activity_54402_ActivityName = {
    Text = "分裂症患者・混沌"
  },
  Activity_54402_ActivityTips = {
    Text = "<Title:イベントルール>\n・「分裂症患者・混沌」イベント開催中、守秘者は「24」を含む専用の編成を使用し、試遊ステージを体験できます。\n・試遊ステージでは、編成中の覚醒体の調整はできません。\n<Title:イベント報酬>\n・初めて試遊ステージをクリア後、イベント画面で報酬を受け取れます。"
