  Activity_54527_ActivityTips = {
    Text = "イベントルール：\n1、守秘者が毎日ログインすると、「学園の贈り物」で当日ログイン報酬を受け取れます。\n2、報酬は守秘者の累計ログインに応じて順次解放され、当日ログイン報酬は9:00（GMT+8）に更新されます。"
