  Activity_54596_ActivityName = {
    Text = "智識の贈り物"
  },
  Activity_54596_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント任務を完了後、以下の貴重な報酬が受け取れます。「魔封瓶」「輪転の書」「精神体カプセル」「循環基盤」「返魂のコア」「廻命のコア」、「忘却篇」限定覚醒体と命輪、「星辰篇」限定覚醒体と命輪など。\n更にイベント限定アイコンフレーム「白銀の証明」、守秘者経験値加速効果などの特別報酬もあります！\n2、本イベントは恒常的に開放されます。全任務を完了し報酬を受け取った後、翌日9:00（GMT+8）以降に終了し、表示されなくなります。\n\n<Title:至高の賛美>\n1、各イベント任務の完了後「至高の賛美」効果を獲得し、守秘者経験値の獲得速度を最大100%まで加速できます。複数の「至高の賛美」効果が同時に発生する場合、最も効果の高い内容が適用されます。\n2、より高い「至高の賛美」効果を解放または獲得すると、加速率と現在の加速可能な守秘者経験値総量に応じて、直ちに追加の経験値を獲得します。\n3、「至高の賛美」を解放後、守秘者が経験値を獲得するたびに、対応する加速率に応じた追加の経験値を獲得します。\n4、「至高の賛美」による追加経験値は、加速可能な経験総量には含めません。\n5、現在、加速可能な経験総量：{s1}。\n6、加速による追加獲得経験値：{s2}（{s3}%）。"
  },
  Activity_55110_ActivityName = {
    Text = "春が散る前に"
  },
  Activity_55110_ActivityPlot = {
    Text = "少女たちの笑い声が、まだ炎を知らぬ花園に響き渡る。\nこの美しい過去に立ち止まるといい、友よ。\nいまだ枯れぬ春が、過去の物語を静かに語るのを聞いてほしい。"
  },
  Activity_55110_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「コレットの温室」のみ参加可能です。"
  },
  Activity_55110_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「花園の記憶」、「ミューズのキス」および「達成報酬」を通じて、イベント通貨である3種類の「詩文」を収集できます。「詩文」は「コレットの温室」で交換を行うことができ、イベント限定SR運命の札「昔日の花と詩」、ルミナスコア、ヘブンズコア、賢石の破片、擬態凝晶などのアイテム報酬を獲得することができます。\n2、イベント期間中「特務記録：薔薇の住処」が無料開放されます。\n\n<Title:イベント期間>\n1、7月15日 9:00 - 7月29日 9:00（GMT+8）の期間、すべてのイベントコンテンツに参加可能です。\n2、7月29日 9:00 - 8月5日 9:00（GMT+8）の期間、参加できるのは「コレットの温室」と「達成報酬」のみで、その他のコンテンツは終了し参加できません。\n\n<Title:花園の記憶>\n1、「花園の記憶」は5つのステージがあり、2日ごとに1ステージが自動開放されます。\n2、挑戦ごとに「エンフェリン」×120を消費し、クリアするとイベント通貨「憂愁の詩文」、「後悔の詩文」、「歓喜の詩文」を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。\n※注意：「リプレイ」機能を使用すると同調率を獲得できません。\n4、フレンドの救援と「共鳴：花園の挽歌」を活用し、より簡単にクリア可能です。\n5、ステージ解放後2日目に、そのステージの超難度が解放されます。初回クリアで大量のイベント通貨報酬を獲得できます。\n6、注意：「超難度」はエンフェリンを消費せず、リプレイ不可で、初回以降は報酬はありません。\n\n<Title:詩文ボーナス>\n1、守秘者が特定の覚醒体または運命の札を所持している場合（編成は不要）、「花園の記憶」ステージの「憂愁の詩文」、「後悔の詩文」、「歓喜の詩文」に追加ドロップボーナスが得られます。（リプレイを含む）\nボーナスは以下の通り：\n・覚醒体「オルラ」：霊知啓発0/1/2/3以上、ボーナス20％/30％/40％/50％\n・SSR運命の札「詩の結び」：強化0/1/2/3以上、ボーナス20％/30％/40％/50％\n・SR運命の札「昔日の花と詩」：強化0/1/2/3以上、ボーナス20％/30％/40％/50％\n2、異なる覚醒体や運命の札の「詩文ボーナス」は累計で合計されます。\n3、特に、超難度の初回クリア報酬は上記のボーナスの影響を受けません。\n\n<Title:共鳴：花園の挽歌>\n1、守秘者はイベント実績を完了することで「灰の心」を獲得できます。\n2、「灰の心」を消費して、「共鳴：花園の挽歌」を起動すると、以下の効果が得られます。\n（1）イベントステージ「花園の記憶」で守秘者が強化され、挑戦がより簡単になります。\n（2）「花園の記憶」クリア後のイベント通貨が増えます。\n（3）イベントコンテンツ「ミューズのキス」が解放されます。\n\n<Title:ミューズのキス>\n・共鳴「万物成長」を起動後、1時間ごとに60の「憂愁の詩文」を自動で獲得し、最大25時間分まで蓄積されます。\n・共鳴「詩と花の交換」を発動すると、「ミューズのキス」は1時間ごとにさらに60の「後悔の詩文」を追加で獲得できます。\n\n<Title:コレットの温室>\n1、「コレットの温室」には3つの花壇があり、開放時間は以下の通りです：\n・「菖蒲の花壇」：7月15日 9時開放。\n・「桔梗の花壇」：7月17日 9時開放。\n・「薔薇の花壇」：7月19日 9時開放。\n2、1回の交換ごとに「憂愁の詩文」/「後悔の詩文」/「歓喜の詩文」を1000消費し、花壇のアイテム報酬から5つをランダムに獲得します。\n3、各花壇のアイテム報酬は「特別アイテム」と「通常アイテム」の2種類に分かれます。リセット時に「特別アイテム」報酬の残量を上限まで戻すことができます。\n具体的なルールは以下の通りです：\n（1）最初2回までのリセット：「特別アイテム」の数量がなくなった場合、守秘者がリセットを選ぶことができ、「特別アイテム」と「通常アイテム」の残量を上限まで戻せます。\nもしくは、そのまま交換を続けることもできますが、「通常アイテム」も数量がなくなった場合は、リセットを行う必要があります。\n\n（2）3回目以降のリセット：「通常アイテム」の残り数量がなくなった場合にのみリセット可能になります。リセットにより「通常アイテム」の残量を上限まで戻せますが、「特別アイテム」は戻りません。\n4、8月5日 9:00（GMT+8）以降、未交換の「詩文」は200個につき「薔薇金券×5000」の比率で回収されますので、守秘者はメールをご確認ください。\n\n<Title:特務記録>\n1、イベント期間中「特務記録：薔薇の住処」が無料で開放されます。2日ごとに新しい事件が追加され、「特務記録：薔薇の住処」をクリアすると、達成報酬でシルバーコア、イベント限定SR運命の札「昔日の花と詩」などを獲得できます。達成報酬はイベント期間中だけ開放され、イベント終了後にはクリアおよび受け取りはできません。\n2、イベント終了後も「特務記録：薔薇の住処」の調査進捗は保持します。イベント期間中に「特務記録：薔薇の住処」を開放していない場合でも、イベント終了後に「起点装置」×7を消費して開放可能です。\n3、イベント期間中かどうかに関わらず、「特務記録：薔薇の住処」をクリアすると「キーオーダー：春の詩集」を獲得できます。"
  },
  Activity_55110_BannerText = {
    Text = "遊興イベント期間限定開催！"
