  Activity_56427_ActivityName = {
    Text = "霊魂の牧人・復刻"
  },
  Activity_56427_ActivityPlot = {
    Text = "彼はあなた方のために苦しみを受けあなた方の災いをその身に担った。\n彼が捧げた血肉により、あなた方は癒され、彼が捧げた命により、あなた方は赦しを得た。"
  },
  Activity_56427_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「聖堂チャリティ会場」のみ参加可能です。"
  },
  Activity_56427_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「聖堂の道」と「市民の善意」、「達成報酬」を通じてイベント通貨「チャリティ券」を収集できます。\n「チャリティ券」は「聖堂チャリティ会場」でランダムな商品と交換でき、交換報酬には、イベント限定SR運命の札「鏡の中の人」、ヘブンズコア、ルミナスコアなどが含まれます。\n2、イベント期間中、「特務記録：血の色」が無料で開放され、「達成報酬」の任務を完了すると、イベント限定アイコン「銀の鍵の名のもとに：サルバドル」を獲得できます！\n\n<Title:イベント期間>\n1、8月26日 9:00 - 9月9日 9:00（GMT+8）、すべてのイベント内容に参加できます。\n2、9月9日 9:00 - 9月16日 9:00（GMT+8）、参加できるのは「聖堂チャリティ会場」と「達成報酬」のみです。他の内容は終了となり参加できません。\n\n<Title:聖堂の道>\n1、「聖堂の道」には5つのステージがあり、2日ごとに1つ自動で開放されます。\n2、挑戦ごとに120点のエンフェリンを消費し、挑戦成功でイベント通貨「チャリティ券」を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。\n※注意：「リプレイ」機能を使用すると同調率を獲得できません。\n4、フレンドの救援と「共鳴：魂の分岐点」を利用すると、より簡単にクリアできます。\n\n<Title:輝光ボーナス>\n1、魂の輝光の影響により、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「聖堂の道」ステージのイベント通貨「チャリティ券」の追加ドロップボーナスが得られます。（リプレイを含む）\nボーナスは以下の通り：\n・覚醒体「サルバドル」：\n霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「神言の石板」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「鏡の中の人」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n\n2、異なる覚醒体や運命の札の「輝光ボーナス」は累計で計算されます。\n3、特に、超難度の初回クリア報酬は「輝光ボーナス」の影響を受けません。\n\n<Title:共鳴：魂の分岐点>\n1、守秘者は達成報酬を完了することで「悔恨の心」を獲得できます。\n2、「悔恨の心」を消費し、「共鳴：魂の分岐点」を起動すると、以下のボーナスを得られます：\n（1）イベントプレイ「聖堂の道」と「特務記録：血の色」において守秘者が強化され、挑戦が容易になります。\n（2）「聖堂の道」クリア後の同調率が向上します。\n（3）イベントコンテンツ「市民の善意」を起動できます。\n\n<Title:市民の善意>\n1、共鳴「安易な方法」を起動後、1時間ごとに60の「チャリティ券」を自動で獲得できます。最大25時間分を貯められます。\n2、共鳴「贖罪、贖罪」を起動後、1時間ごとに1800の薔薇金券を自動で追加獲得できます。\n\n<Title:聖堂チャリティ会場>\n1、聖堂チャリティ会場には3つの商店があり、開放時間は以下の通りです。\n・「グレイおばさんの店」：8月26日 9:00開放。\n・「ジョン爺のマジカルバザー」：8月29日 9:00開放。\n・「スミスの特別セール」：9月1日 9:00開放。\n2、1回の交換ごとに「チャリティ券」を1000枚消費し、店舗内のアイテム報酬から5つをランダムに獲得します。\n3、各店舗のアイテム報酬は「特別アイテム」と「通常アイテム」の2種類に分かれます。リセット時に「特別アイテム」報酬の残量を上限まで戻すことができます。\n具体的なルールは以下の通りです：\n（1）最初2回までのリセット：「特別アイテム」の数量がなくなった場合、守秘者がリセットを選ぶことができ、「特別アイテム」と「通常アイテム」の残量を上限まで戻せます。\nもしくは、そのまま交換を続けることもできますが、「通常アイテム」も数量がなくなった場合は、リセットを行う必要があります。\n\n（2）3回目以降のリセット：「通常アイテム」の残り数量がなくなった場合にのみリセット可能になります。リセットにより「通常アイテム」の残量を上限まで戻せますが、「特別アイテム」は戻りません。\n4、9月16日 9:00（GMT+8）以降、未交換の「チャリティ券」は、200枚につき「薔薇金券×5000」の比率で回収されますので、守秘者はメールをご確認ください。\n\n<Title:特務記録>\n1、イベント期間中、「特務記録：血の色」が無料で解放されます。\n2、イベント終了後、「特務記録：血の色」の調査進捗は保持されます。イベント期間中に「特務記録：血の色」を解放していない場合、イベント終了後も「起点装置」×7を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「特務記録：血の色」をクリアすると「キーオーダー：神の御業」を獲得できます。\n\n<Title:復刻補償>\n1、以前に「特務記録：血の色」を解放済みの守秘者は、今回の復刻イベント期間中に再度解放した際に「チャリティ券」×700の補償を獲得できます。\n2、以前にイベント限定アイコン「銀の鍵の名のもとに：サルバドル」を獲得済みの守秘者は、重複獲得時に自動的に「チャリティ券」×2000に変換されます。\n3、以前に共鳴起動素材「悔恨の心」を獲得済みの守秘者は、余分な「悔恨の心」1個につき自動的に「薔薇金券」×5000に変換されます。\n"
  },
  Activity_56427_BannerText = {
