  Activity_56428_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「神国の降臨」と「王の神託」、「達成報酬」を通じてイベント通貨を収集できます。イベント通貨は「深淵の応答」で捧げものとして使用し、道具報酬を獲得できます。報酬には、イベント限定SR運命の札「深海の呼び声」、賢石の破片、ヘブンズコア、ルミナスコアなどが含まれます。\n2、イベント期間中、「異夢視界：冒涜」が無料で開放され、「達成報酬」の任務を完了すると、イベント限定アイコン「銀の鍵の名のもとに：ミリアム」を獲得できます！\n\n<Title:イベント期間>\n1、11月4日 15:00 - 11月18日 15:00の期間、すべてのイベント内容に参加できます。\n2、11月18日 15:00 - 11月25日 15:00の期間、参加できるのは「深淵の応答」と「達成報酬」のみです。他の内容は終了となります。\n\n<Title:神国の降臨>\n1、「神国の降臨」には5つのステージがあり、2日ごとに1つ自動で開放されます。\n2、挑戦ごとに120点のエンフェリンを消費し、イベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。\n※注意：「リプレイ」機能を使用すると同調率を獲得できません。\n4、フレンドの救援と「共鳴：海淵の祭儀」を利用すると、より簡単にクリアできます。\n\n<Title:祀物ボーナス>\n1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「神国の降臨」ステージのイベント通貨「祭祀者の涙」、「祭祀者の血」、「祭祀者の髄」の追加ドロップボーナスが得られます。（リプレイを含む）\nボーナスは以下の通り：\n・覚醒体「ミリアム」：\n霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「信仰の力」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「深海の呼び声」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体や運命の札の「祀物ボーナス」は累計で計算されます。\n3、特に、超難度の初回クリア報酬は上記のボーナスの影響を受けません。\n\n<Title:共鳴：海淵の祭儀>\n1、守秘者は達成報酬を完了することで「敬虔の心」を獲得できます。\n2、「敬虔の心」を消費し、「共鳴：海淵の祭儀」を起動すると、以下のボーナスを得られます：\n（1）イベントプレイ「神国の降臨」において守秘者が強化され、挑戦が容易になります。\n（2）「神国の降臨」クリア後に獲得できるイベント通貨が向上します。\n（3）イベントコンテンツ「王の神託」を起動できます。\n\n<Title:王の神託>\n・共鳴「生贄の試練」を起動後、1時間ごとに60の「祭祀者の涙」を自動で獲得できます。最大25時間分を貯められます。\n\n<Title:深淵の応答>\n1、「深淵の応答」には3つの祭壇があり、開放時間は以下の通りです。\n・「晶泪の祭壇」：11月4日 15:00〜11月25日 15:00。\n・「紅血の祭壇」：11月6日 15:00〜11月25日 15:00。\n・「霊髄の祭壇」：11月8日 15:00〜11月25日 15:00。\n2、1回の捧げ物ごとに「祭祀者の涙」/「祭祀者の血」/「祭祀者の髄」を1000消費し、祭壇内のアイテム報酬から5つをランダムに獲得します。\n3、各祭壇のアイテム報酬は「特別アイテム」と「通常アイテム」の2種類に分かれます。リセット時に指定アイテム報酬の残量を上限まで戻すことができます。\n具体的なルールは以下の通りです：\n（1）最初2回までのリセット：「特別アイテム」の数量がなくなった場合、守秘者がリセットを選ぶことができ、「特別アイテム」と「通常アイテム」の残量を上限まで戻せます。\nもしくは、そのまま交換を続けることもできますが、「通常アイテム」も数量がなくなった場合は、リセットを行う必要があります。\n\n（2）3回目以降のリセット：「通常アイテム」の残り数量がなくなった場合にのみリセット可能になります。リセットにより「通常アイテム」の残量を上限まで戻せますが、「特別アイテム」は戻りません。\n\n<Title: 異夢視界>\n1、イベント期間中「異夢視界：冒涜」が無料で開放されます。\n2、イベント終了後、「異夢視界：冒涜」の調査進捗は保持されます。\nイベント期間中に「異夢視界：冒涜」を解放していない場合、イベント終了後も「起点装置」×7を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「異夢視界：冒涜」をクリアすると「キーオーダー：海の祭」を獲得できます。\n\n<Title:復刻補償>\n1、以前に「異夢視界：冒涜」を解放した守秘者は、今回の復刻イベント期間中の再解放時に「祭祀者の涙」×700の補償を獲得します。\n2、以前に、イベント限定アイコン「銀の鍵の名のもとに：ミリアム」を獲得した守秘者は、再獲得時に自動的に「祭祀者の涙」×2000に変換されます。\n3、以前に、共鳴強化素材「敬虔の心」を獲得済みの場合、1個余分に獲得するたび、自動で「薔薇金券」×5000に変換されます。"
  },
