  Activity_56429_ActivityPlot = {
    Text = "彼女は常に人々の前を歩いている。\n一歩、二歩、彼女の足跡は人々の歩調を導いている。\nでも人々はすぐに忘れる。天才と狂人の間はわずか一歩であることを。"
