  Activity_56429_ActivityTips = {
    Text = "<Title:イベント概要>\nイベント期間中、守秘者は期間限定の「虚無の門」と「達成報酬」を通じて活動通貨「人形パーツ」を集めることができます。「人形パーツ」は「先生の教え」にて、活動限定SR運命の札「羊飼いの杖」やルミナスコア、ヘブンズコア、賢石の破片、擬態凝晶などの報酬と交換可能。\n\n<Title:虚無の門>\n1、「虚無の門」には探索なしで直接戦闘を行う9つのステージがあり、毎日自動的に1つ開放されます。\n2、チャレンジするたびに120ポイントのエンフェリンを消費し、チャレンジに成功すると、素材と活動通貨を獲得できます。\n3、ステージをクリアすると、そのステージの「リプレイ」機能が解放されます。注意：「リプレイ」機能を使用する場合、同調率を獲得できません。\n4、フレンドの救援で、より簡単にレベルをクリアできます。\n\n<Title:パペットパーツボーナス>\n1、守秘者が特定の覚醒体または生運命の札を所持している場合（戦場にいる必要はありません）、レベル任務「虚無の門」報酬の「人形パーツ」は、追加のドロップボーナス（再出現を含む）を獲得できます。具体的なボーナスは以下の通りです：\n・覚醒体「溶融・ドール」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「虚無に堕ちた人形」：強化0/1/2/3以上でボーナス20%/30%/40%/50%\n・SR運命の札「羊飼いの杖」：強化0/1/2/3以上でボーナス20%/30%/40%/50%\n2、異なる覚醒体や運命の札の「人形パーツボーナス」は加算方式で計算されます。\n3、特に、超難度の最初のチャレンジの報酬は、上記のボーナスの影響を受けません。\n\n<Title: 先生の教え>\n1、「パーツ交換」は1回につき「人形パーツ」750個を消費し、「先生の教え」からランダムで5つのアイテム報酬を獲得できます。\n2、「先生の教え」のアイテム報酬は「特別なアイテム」と「通常のアイテム」に分かれています。リセット時に特別アイテム報酬の残数が上限までリセットされることがあります。具体的なルールは以下のとおりです：\n(1)最初の5回のリセット：「スペシャルアイテム」の残数がなくなった場合、守秘者はリセットを選択できます。リセット後、「スペシャルアイテム」と「通常アイテム」の残数が上限にリセットされます。または交換を続行することを選択します。「通常アイテム」の残数がなくなった場合、交換を続行するにはリセットが必要です。\n(2)6回目以降のリセット：「通常アイテム」の残数がなくなったらリセットできます。リセットすると「通常アイテム」の残数が上限にリセットされ、「スペシャルアイテム」はリセットされなくなります。\n\n<Title:活動時間>\n1、2月17日15:00〜3月3日15:00まで、イベント概要のすべてのコンテンツに参加可能です。\n2、3月3日15:00～3月10日15:00までは、「先生の教え」と「達成報酬」のみが保持されます。その他のコンテンツは終了しており、参加できません。\n3、3月10日15:00以降、交換されていない「人形パーツ」は交換された「薔薇金券×40」1枚の割合で回収されます。メールを確認してください。"
  },
