  Activity_56431_ActivityPlot = {
    Text = "星辰正しき刻が迫り、胸の中の胎動は太鼓のように激しくなった。\n彼女を長年苦しめた暗夜の悪夢は、信者の熱い涙と共に終焉を迎える。\n神の@1闇の@2の中偉大なる@3が世界に降臨する。"
