  Activity_56431_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「聖胎孵化」のみ参加可能です。"
  },
  Activity_56431_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「暗き胎内」と「達成報酬」を通じて3種類の「胚」を収集し、「聖胎孵化」でアイテム報酬に交換できます。\n交換報酬には、イベント限定SR運命の札「氷河の下で眠る」、ヘブンズコア、ルミナスコア、賢石の破片、擬態凝晶などが含まれます。\n2、イベント期間中、「達成報酬」の任務を完了するとイベント限定アイコン「銀の鍵の名のもとに：ゴリア」、イベント限定SR運命の札「氷河の下で眠る」、大量の「胚」を獲得できます。\n\n<Title:イベント期間>\n1、7月29日 9:00 - 8月12日 9:00（GMT+8）の期間、すべてのイベント内容に参加できます。\n2、8月12日 9:00 - 8月19日 9:00（GMT+8）の期間、参加できるのは「聖胎孵化」と「達成報酬」のみです。他の内容は終了となります。\n\n<Title:暗き胎内>\n1、「暗き胎内」には7つのステージがあり、毎日1つ自動で開放されます。\n2、挑戦ごとに120点のエンフェリンを消費し、イベント通貨「無識の胚」、「無欲の胚」、「無我の胚」を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。\n※注意：「リプレイ」機能を使用すると同調率を獲得できません。\n4、フレンドの救援を利用すると、より簡単にクリアできます。\n5、任意の難易度でステージクリア後、超難度が解放されます。初回クリアで大量のイベント通貨報酬を獲得できます。\n6、注意：「超難度」はエンフェリンを消費せず、リプレイ不可で、初回以降は報酬はありません。\n\n<Title:胚ボーナス>\n1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「暗き胎内」ステージのイベント通貨「無識の胚」「無欲の胚」「無我の胚」の追加ドロップボーナスが得られます。（リプレイを含む）\nボーナスは以下の通り：\n・覚醒体「マーフィー」：\n霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「隠匿された誕生」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「氷河の下で眠る」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体や運命の札の「胚ボーナス」は累計で計算されます。\n3、特に、超難度の初回クリア報酬は上記のボーナスの影響を受けません。\n<Title:聖胎孵化>\n1、「聖胎孵化」は7月29日 9:00 - 8月19日 9:00（GMT+8）の期間、開放されます。\n2、8月19日 9:00（GMT+8）以降、未交換の「胚」は、1つにつき「薔薇金券×40」の比率で回収されますので、守秘者はメールをご確認ください。"
  },
