  Activity_56432_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「獣の野心」や「達成報酬」で3種類の「蕾」を集めることができ、「蕾」は「山嶺の大穴」でアイテムに交換可能。イベント限定SR命輪「雪山が溶けるまで」、ヘブンズコア、ルミナスコア、賢石の破片、擬態凝晶などを獲得可能。\n2、イベント期間「特務記録：雪山への帰還」が無料開放されます。\n\n<Title:イベント期間>\n1、10月7日9:00 - 10月21日9:00(GMT+8)、すべてのイベント内容に参加可能。\n2、10月21日15:00 - 10月28日15:00(GMT+8)、「山嶺の大穴」と「達成報酬」のみ参加可能、それ以外の内容は終了。\n\n<Title: 獣の本能>\n1、「獣の本能」は5つのステージがあり、2日ごとに1つ解放されます。\n2、毎回の挑戦で120点のエンフェリンを消費、成功するとイベント通貨「寒氷の蕾」、「銀霜の蕾」、「日光の蕾」を獲得。\n3、ステージクリア後、「リプレイ」機能が解放されます。「リプレイ」機能使用時、同調率は獲得できません。\n4、フレンドの救援や「共鳴：白銀の顎」を利用して通過しやすくします。\n5、ステージ解放の翌日、「超難度」も解放。初クリアで豊富なイベント通貨を獲得。\n6、「超難度」挑戦ではエンフェリンを消費せず、リプレイ不可。初クリア後、繰り返し挑戦しても通貨を獲得できません。\n\n<Title:蕾ボーナス>\n1. 守秘者が特定の覚醒体または命輪（参戦不要）を所有している場合、「獣の本能」の報酬に「寒氷の蕾」、「銀霜の蕾」、「日光の蕾」のドロップ率が増加（リプレイを含む）。具体的なブーストは以下の通り：\n・覚醒体「血ノ鎖・ヘロット」：霊知啓発0/1/2/3以上で、20%/30%/40%/50%アップ\n・SSR命輪「深紅に沈む」：強化0/1/2/3以上で、20%/30%/40%/50%アップ\n・SR命輪「雪山が溶けるまで」：強化0/1/2/3以上で、20%/30%/40%/50%アップ\n2. 異なる覚醒体や命輪の「蕾ボーナス」は累積されます。\n3. 特に「超難度」の初クリア報酬は「蕾ボーナス」には影響しません。\n\n<Title:共鳴：白銀の顎>\n1、守秘者はイベント実績を完了することで「獣の心」を獲得できます。\n2、 「獣の心」を消費し、「共鳴：白銀の顎」を発動、イベントプレイ「獣の本能」で強化され、挑戦が楽になります。\n\n<Title: 山嶺の大穴>\n1．「山嶺の大穴」には3つの交換商店があり、開店時間は以下の通り：\n・「貪食の野心」：10月7日9:00開放。\n・「復讐の戦意」：10月9日9:00開放。\n・「再生の希望」：10月11日9:00開放。\n2. 交換ごとに1000「寒氷の蕾」/「銀霜の蕾」/「日光の蕾」を消費し、ランダムで交換商店の5つのアイテムを獲得。\n3. 交換商店のアイテムは「特別アイテム」と「通常アイテム」に分かれ、リセット時「特別アイテム」の残量が上限にリセットされる。具体的なルールは以下の通り：\n（1）初回と2回目のリセット： 「特別アイテム」がなくなるとリセット可能、リセット後は「特別アイテム」と「通常アイテム」の残量が上限に。リセットせずに続けたい場合、「通常アイテム」もなくなるとリセットが必要。\n（2）3回目以降のリセット：「通常アイテム」がなくなるとリセット可能、リセット後「通常アイテム」の残量が上限に。「特別アイテム」はリセットされません。\n4. 10月28日9:00(GMT+8)以降、未交換の「蕾」は1個あたり薔薇金券×40で回収されますので、守秘者はメールをチェックしてください。\n\n<Title: 特務記録>\n1. イベント期間中、「特務記録：雪山への帰還」が無料開放。2日ごとに新しい事件が追加され、「特務記録：雪山への帰還」をクリアすることでシルバーコアやイベント限定SR命輪「雪山が溶けるまで」などの報酬が達成報酬として獲得可能。達成報酬はイベント期間中のみ有効、イベント終了後は完了および受取不可。\n2. イベント終了後、「特務記録：雪山への帰還」の調査進捗は保存されます。イベント期間中に「特務記録：雪山への帰還」を解放していない場合、イベント終了後も「起点装置」×7を消費して解放可能です。\n3. イベント期間を問わず、「特務記録：雪山の帰還」のクリア後、「キーオーダー：銀峰の覚悟」を獲得できます。"
  },
  Activity_56432_BannerText = {
    Text = "遊興イベント期間限定開催！"
  },
  Activity_56433_ActivityName = {
    Text = "名探偵マニュアル"
  },
  Activity_56433_ActivityPlot = {
    Text = "一見すると、平凡なマニュアル。\n名探偵が長年の仕事で得た心得と体験が記されている。\nいつか、このマニュアルが未来の名探偵を生み出すことを願って。"
