  Activity_56433_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「幸運倶楽部」のみ参加可能です。"
  },
  Activity_56433_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「月夜の伝説」と「達成報酬」を通じてイベント通貨「勝負チップ」を収集できます。\n「勝負チップ」は「幸運倶楽部」で豪華報酬と交換可能です。交換報酬には、イベント限定SR運命の札「運命のルーレット」、ヘブンズコア、ルミナスコア、賢石の破片、擬態凝晶などが含まれます。\n\n2、イベント期間中、「達成報酬」の任務を完了するとイベント限定アイコン「銀の鍵の名のもとに：ライカー」、イベント限定SR運命の札「運命のルーレット」、シルバーコア、そして大量のイベント通貨「勝負チップ」を獲得できます。\n\n3、イベント期間中、「特務記録：良き狩りを！」が無料開放されます。\n\n<Title:イベント時間>\n1、8月12日9:00 - 8月26日9:00（GMT+8）、すべてのイベント内容に参加できます。\n\n2、8月26日9:00 - 9月2日9:00（GMT+8）、参加できるのは「幸運倶楽部」と「達成報酬」のみです。\n\n<Title:月夜の伝説>\n1、「月夜の伝説」には9つのステージがあり、毎日1つ自動で開放されます。\n\n2、各挑戦には120点のエンフェリンを消費し、ステージ毎に異なる素材ドロップと、イベント通貨「勝負チップ」を獲得できます。\n\n3、本イベントのステージは直接戦闘の素材ステージです。クリア後リプレイ可能！各「リプレイ」には120点のエンフェリンを消費します。\n4、注意：「リプレイ」機能を使用すると同調率を獲得できません。\n\n<Title:チップボーナス>\n1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「月夜の伝説」ステージ報酬のイベント通貨「勝負チップ」の追加ドロップボーナスが得られます。（リプレイを含む）\n\n具体的なボーナスは以下の通り：\n・覚醒体「ライカー」：\n霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n\n・SSR運命の札「幸運の時」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n\n・SR運命の札「運命のルーレット」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n\n2、異なる覚醒体や運命の札の「チップボーナス」は累計で計算されます。\n\n3、特に、超難度の初回クリア報酬は「チップボーナス」の影響を受けません。\n\n<Title:幸運倶楽部>\n1、「幸運倶楽部」は8月12日9:00 - 9月2日9:00（GMT+8）の期間のみ開放されます。\n\n2、9月2日9:00（GMT+8）以降、残り未交換の「勝負チップ」は、1つの交換あたり「薔薇金券×40」の割合で回収されますので、守秘者はメールを確認してください。\n\n<Title:特務記録>\n1、「特務記録：良き狩りを！」では、守秘者はストーリー設定「ライカー」を含む特殊な編成を使用して挑戦します。\n\n2、「特務記録：良き狩りを！」をクリアすると、新しいキーオーダー「キーオーダー：一発の銃声」を獲得できます。"
  },
  Activity_56433_BannerText = {
    Text = "遊興イベント期間限定開催！"
  },
  Activity_56434_ActivityName = {
    Text = "万象の門"
  },
  Activity_56434_ActivityPlot = {
    Text = "誰も彼女が門で静かに過ごした年月を知らない。\n彼女はどの具体世界にも身を投じる意図がなく、時空の連続に絡まれることを避けた。いかなる存在にも窮地の門の静寂を乱すことは許されなかった。\n彼女とあなたが目を合わせた瞬間まで。"
  },
  Activity_56434_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「エコー」のみ参加可能です。"
  },
  Activity_56434_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「最終テスト」と「達成報酬」を通じてイベント通貨「終末の指針」を収集できます。「終末の指針」は「回声」で豪華な報酬と交換でき、イベント限定SR運命の札「真理の扉」、ヘブンズコア、ルミナスコア、賢石の破片、擬態凝晶などが含まれます。\n2、イベント期間中、「達成報酬」のタスクを完了することでイベント限定アイコン「銀の鍵の名のもとに：タヴィ」、イベント限定SR運命の札「真理の扉」、シルバーコアと大量のイベント通貨「終末の指針」を獲得できます。\n\n<Title:イベント時間>\n1、11月18日 9:00 - 12月2日 9:00（GMT+8）、すべてのイベント内容に参加可能です。\n2、12月2日 9:00 - 12月9日 9:00（GMT+8）、「回声」と「達成報酬」のみが残ります。他の内容は終了し参加できません。\n\n<Title: 最終テスト>\n1、「最終テスト」には9つのレベルが含まれており、毎日自動的に1つ開放されます。\n2、各挑戦は120ポイントのエンフェリンを消費します。異なるレベルに挑戦すると、異なる素材のドロップを獲得するだけでなく、イベント通貨「終末の指針」を獲得。\n3、本次イベントのレベルは直接戦闘の素材レベルです。クリア後にリプレイ可能です！毎回の「リプレイ」には120ポイントのエンフェリンを消費します。\n4、ご注意： 「リプレイ」機能を使用する際、同調率を獲得することができません。\n\n<Title: 終末の指針ボーナス>\n1、守秘者は特定の覚醒体または運命の札を持っていることで（出陣は必要ありません）、「最終テスト」レベルタスク報酬の「終末の指針」の追加ドロップボーナスを受けることができます（リプレイを含む）。具体的なボーナスは以下の通りです：\n・覚醒体「タヴィ」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「隠されし運命の輪」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「真理の扉」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体または運命の札の「終末の指針ボーナス」は重ね合わせ方式で計算されます。\n3、特に、超難度の初回クリア報酬は「終末の指針ボーナス」の影響を受けません。\n\n<Title: 回声>\n1、「回声」は11月18日 9:00 - 12月9日 9:00（GMT+8）の期間にのみ開放されます。\n2、12月9日 9:00（GMT+8）以降、未交換の「終末の指針」は「薔薇金券×40」との比率で回収されますので、守秘者はメールをチェックしてください。"
  },
  Activity_56434_BannerText = {
    Text = "期間限定イベント開催中！"
  },
  Activity_56435_ActivityName = {
    Text = "多重治療・復刻"
  },
  Activity_56435_ActivityPlot = {
    Text = "「Hysteria」——別名ヒステリー症。\nこの時代、それはすなわち死を意味した。\nだが幸運にも、ミサゴの科学者と調査員もまた、正気の沙汰ではなかった。彼らは、この難題を克服することを決意したのだ。"
  },
  Activity_56435_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「人格解析」のみ参加可能です。"
  },
  Activity_56435_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「記憶の収集」と「大脳辺縁系」、「達成報酬」を通じてイベント通貨「記憶パズル」を収集できます。\n「記憶パズル」は「人格解析」で報酬と交換でき、交換報酬には、イベント限定SR運命の札「銀ダラの決意」、ルミナスコア、ヘブンズコアなどが含まれます。\n2、イベント期間中、「特務記録：静かな分裂」が期間限定で無料解放され、「達成報酬」の任務を完了すると、イベント限定アイコン「銀の鍵の名のもとに：「24」」を獲得できます！\n\n<Title:イベント期間>\n1、10月21日 15:00 - 11月4日 15:00の期間、すべてのイベント内容に参加できます。\n2、11月4日 15:00 - 11月11日 15:00の期間、参加できるのは「人格解析」と「達成報酬」のみです。\n\n<Title:記憶の収集>\n1、「記憶の収集」には5つのステージがあり、2日ごとに1つ自動で開放されます。\n2、挑戦ごとに120点のエンフェリンを消費し、イベント通貨「記憶パズル」を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。\n※注意：「リプレイ」機能を使用すると同調率を獲得できません。\n4、フレンドの救援と「共鳴：解離性症候群」を利用すると、より簡単にクリアできます。\n\n<Title:理性ボーナス>\n1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「記憶の収集」ステージのイベント通貨「記憶パズル」の追加ドロップボーナスが得られます。\nボーナスは以下の通り：\n・覚醒体「「24」」：\n霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「奇体の反噬」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「銀ダラの決意」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n\n2、異なる覚醒体や運命の札の「理性ボーナス」は累計で計算されます。\n3、特に、超難度の初回クリア報酬は上記のボーナスの影響を受けません。\n\n<Title:共鳴：解離性症候群>\n1、守秘者は達成報酬を完了することで「分裂の心」を獲得できます。\n2、「分裂の心」を消費し、「共鳴：解離性症候群」を起動すると、以下のボーナスを得られます：\n（1）イベントプレイ「記憶の収集」と「特務記録：静かな分裂」において守秘者が強化され、挑戦が容易になります。\n（2）「記憶の収集」クリア後の獲得報酬が向上します。\n（3）イベントコンテンツ「大脳辺縁系」を起動できます。\n\n<Title:大脳辺縁系>\n1、共鳴「診断：人格分裂」を起動後、1時間ごとに60の「記憶パズルα」を自動で獲得できます。最大25時間分を貯められます。\n2、共鳴「認知同調」を起動後、1時間ごとに30の「記憶パズルβ」を自動で追加獲得できます。最大25時間分を貯められます。\n\n<Title:特務記録>\n1、イベント期間中、「特務記録：静かな分裂」が無料で解放されます。\n2、イベント終了後、「特務記録：静かな分裂」の調査進捗は保持されます。イベント期間中に未完了の調査イベントを完了した場合も、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「特務記録：静かな分裂」を解放していない場合、イベント終了後も「起点装置」×7を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「特務記録：静かな分裂」をクリアすると「キーオーダー：すべてが彼女」を獲得できます。\n\n<Title:復刻補償>\n1、以前に「特務記録：静かな分裂」を解放した守秘者は、今回の復刻イベント期間中の再解放時に「記憶パズルα」×700の補償を獲得します。\n2、以前に、イベント限定アイコン「銀の鍵の名のもとに：「24」」を獲得した守秘者は、再獲得時に自動的に「記憶パズルα」×2000に変換されます。\n3、以前に、共鳴強化素材「分裂の心」を獲得済みの場合、1個余分に獲得するたび、自動で「薔薇金券」×5000に変換されます。"
  },
