  Activity_61156_ActivityName = {
    Text = "終焉紀行"
  },
  Activity_61156_ActivityTips = {
    Text = "イベントルール：\n1、「終焉紀行」で指定された紀行任務を完了すると、報酬を受け取れます。\n2、「終焉紀行」は恒常的に開放されます。\n3、「上級紀行」を解放すると、任務完了後に追加報酬を受け取れます。\n\n注意：「上級紀行」は本イベント内のみ有効です。慎重にご活用ください。"
  },
  Activity_61369_ActivityName = {
    Text = "進行メロディ"
  },
  Activity_61369_ActivityPlot = {
    Text = "守秘者は以下の限定運命の札から1つを選んで覚醒できます！"
  },
  Activity_61369_ActivityTips = {
    Text = "<Title:概要>\n昏き海は波乱万丈で、運命の札は回転し、ハムリンの音楽に導かれ、無限の楽曲が奏でられ、あなたの歩んだ旅の運命の札へと繋がります。その助力があなたを終末の休止符まで導きますように。\n\n<Title:イベントルール>\n・イベント期間中に1日ログインするだけで、以下の12個の限定運命の札の中から1つを選んで覚醒できます：神王の讃歌、至高の収蔵品、薔薇の名において、苦痛の先へ、隠匿された誕生、女王の戒律、神知の石板、異形の捕食、信奉の心、詩の結び、慈悲深き哺育、幸運の時。"
  },
  Activity_61369_BannerText = {
    Text = "限定運命の札無料受取"
  },
  Activity_61370_ActivityName = {
    Text = "純銀の初心"
  },
  Activity_61370_ActivityPlot = {
    Text = "毎日ログインで記念限定SSR運命の札「純銀の心」を合計16個受け取り可能！"
  },
  Activity_61370_ActivityTips = {
    Text = "<Title:概要>\n世界がどれほど変わろうとも、誰もが初めの純銀の心を守り続ければ、物語は巡り、新たな生命が荒野に再び生まれる。\n\n<Title:イベントルール>\n・イベント期間中、守秘者は毎日「純銀の初心」で限定SSR運命の札「純銀の初心」をを受け取り可能、合計16回。\n・報酬は守秘者の累計ログインに応じて順次解放され、当日ログイン報酬は15:00に更新されます。"
  },
  Activity_61370_BannerText = {
    Text = "限定SSR運命の札無料受取"
  },
  Activity_61371_ActivityName = {
    Text = "六翼解放の願い"
  },
  Activity_61371_ActivityPlot = {
    Text = "昏き海の混沌の中、シルバーコアが次元の裂け目を通じて昏き海の岸辺に散乱した。タヴィはそれらを丹念に集めて、昏き海の隅に置いた。これらのシルバーコアは融蝕の拡大を防ぐことはできないが、その中に込められた思いや願いは永遠に輝き続ける。"
  },
  Activity_61371_ActivityTips = {
    Text = "<Title:概要>\n昏き海の混沌の中、シルバーコアが次元の裂け目を通じて昏き海の岸辺に散乱した。タヴィはそれらを丹念に集めて、昏き海の隅に置いた。これらのシルバーコアは融蝕の拡大を防ぐことはできないが、その中に込められた思いや願いは永遠に輝き続ける。\n\n<Title:イベントルール>\n・イベント期間中、守秘者は毎日ログインすることでシルバーコア×1000を受け取れ、最大6回受け取り可能。\n・イベント期間中、守秘者が累計7日間ログインすると、限定覚醒体「タヴィ」を直接受け取れます。\n・報酬は守秘者の累計ログインに応じて順次解放され、当日ログイン報酬は9:00（GMT+8）に更新されます。"
  },
  Activity_61371_BannerText = {
    Text = "サインインして大量のシルバーコアを受け取る"
  },
