  Activity_65387_ActivityName = {
    Text = "校猫の謝罪"
  },
  Activity_65387_ActivityPlot = {
    Text = "最近、学校の防護対策の不備により<Del:「仮テキスト、赤点」>融蝕がキャンパスに侵入する事態が増え、多くの不便をもたらしました。そこで、校務処は複数の補給ポイントを設置し、学生に物資を配布することにしました。（施設管理の失敗の責任から、今回の補給物資はすべて校猫が運搬します）"
  },
  Activity_65387_ActivityTips = {
    Text = "<Title:概要>\n最近、学校の防護対策の不備により、<Del:「仮テキスト、赤点」>融蝕がキャンパスに侵入し、多くの不便をもたらした。これに対し、校務部は複数の補給ポイントを設置し、学生に物資を配布することにした。（施設管理の失敗により、今回の補給物資はすべて校猫が運搬）\n\n<Title:イベントルール>\n・イベント期間中、守秘者は毎日ログイン後に「校猫の謝罪」でシルバーコア×500を受け取れる。最大5回まで。\n・報酬は守秘者の累計ログインに応じて順次解放され、当日ログイン報酬は9:00（GMT+8）に更新されます。"
  },
  Activity_65387_BannerText = {
    Text = "サインインしてシルバーコアを受け取る"
  },
  Activity_65502_ActivityName = {
    Text = "進行メロディ・デュエット"
  },
  Activity_65502_ActivityPlot = {
    Text = "守秘者は以下の限定運命の札から1つを選んで覚醒できます！"
  },
  Activity_65502_ActivityTips = {
    Text = "<Title:概要>\n昏き海は波乱万丈で、運命の札は回転し、ハムリンの音楽に導かれ、無限の楽曲が奏でられ、あなたの歩んだ旅の運命の札へと繋がります。その助力があなたを終末の休止符まで導きますように。\n\n<Title:イベントルール>\n・イベント期間中に1日ログインするだけで、以下の12個の限定運命の札の中から1つを選んで覚醒できます：神王の讃歌、至高の収蔵品、薔薇の名において、苦痛の先へ、隠匿された誕生、女王の戒律、神知の石板、異形の捕食、信奉の心、詩の結び、慈悲深き哺育、幸運の時。"
  },
  Activity_65502_BannerText = {
    Text = "限定運命の札無料受取"
  },
  Activity_65521_ActivityName = {
    Text = "調査供給ボックス"
  },
  Activity_65521_ActivityPlot = {
    Text = "ミサゴ校務室提供の調査補給。アリステアが昏き海の漂流物から精製したもの。"
  },
