  Activity_66375_ActivityName = {
    Text = "決戦：原初の影"
  },
  Activity_66375_ActivityPlot = {
    Text = "彼の視線が無数次元を横切り、彼と視線を交わしたのは無数の銀色の姿だ。\n彼らは小さく、脆弱だ。記憶を守るために戦い、死ぬまで続く。"
  },
  Activity_66375_ActivityStageEndContent = {
    Text = "イベント達成、調査を続けてください。"
  },
  Activity_66375_ActivityTips = {
    Text = "<Title: 共戦原初>\n・「共戦原初」には 7 つのリプレイ不可能な、原初の視線に直接挑戦するステージが含まれ、イベント初日には最初の 3 ステージが開放され、その後3日ごとに1つずつ開放される。\n・各挑戦で対応する原初の視線を打ち破ると、対応する報酬が獲得。\n・各原初の視線には大量の分身があり、特定のタイプの原初の視線が任意の守秘者に打ち破られた場合、そのタイプの原初の視線の「世界残余数量」が 1減少し、そのタイプの原初のすべての分身が排除された後、該当するステージは閉鎖され、再挑戦は不可能になる。\n・すべてのステージは「融災の黒潮・終末」の影響を受けるが、各ステージは異なる「純銀の核」遺物を提供し、強力なボーナスを与える。また、各ステージは「全知の眼」遺物を提供し、タヴィが戦闘開始時に 120の狂気を獲得し、タヴィのすべてのダメージ、シールド、生命回復効果が 50% 増加。\n・すべてのステージでは救援を選択する必要があり、イベント全体を通じて、相互フォローしている守秘者はあなたに救援を1回だけ提供できる。救援を使用するため、実際の同調率の報酬は基本報酬にさらに 50% 増加。\n・守秘者は少なくとも調査 2-9 を完了する必要があり、このイベントに参加可能である。\n\n<Title:調査：終章>\n・各原初の視線の本体は、調査 9-5 から 9-11 まで自分自身で打破する必要がある。これらの特別ステージには実績も星数もなく、「全知の眼」遺物の助けも利用できず、救援も使用できず、さらに高難度が高い。\n・「共戦原初」イベント終了後に「調査：終章」の後続ステージが解放される。ほかの守秘者と共にさまざまな原初の視線のすべての分身を排除することで、調査 9-5 から 9-11 において該当するステージを事前に解放することができる。"
  },
  Activity_66375_BannerText = {
    Text = "特別イベント期間限定開催！"
  },
  Activity_66908_ActivityName = {
    Text = "豊穣の息吹"
  },
  Activity_66908_ActivityTips = {
    Text = "<Title:イベントルール>\n・「豊穣の息吹」イベント開催中、守秘者はタイスを含む専用の編成を使用し、試遊ステージを体験できます。\n・試遊ステージでは、編成中の覚醒体の調整はできません。\n<Title:イベント報酬>\n・初めて試遊ステージをクリア後、イベント画面で報酬を受け取れます。"
  },
  Activity_67077_ActivityName = {
    Text = "9章クリアパス"
  },
  Activity_67077_ActivityPlot = {
    Text = "封印された記憶、過去の行程。追憶の時、敬意を忘れずに。"
  },
  Activity_67718_ActivityName = {
    Text = "春が散る前に・復刻"
  },
  Activity_67718_ActivityPlot = {
    Text = "少女たちの笑い声が、まだ炎を知らぬ花園に響き渡る。\nこの美しい過去に立ち止まるといい、友よ。\nいまだ枯れぬ春が、過去の物語を静かに語るのを聞いてほしい。"
  },
  Activity_67718_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「コレットの温室」のみ参加可能です。"
  },
  Activity_67718_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は限時ゲームプレイ「ガーデンの思い出」、「ミューズのキス」および「実績報酬」を通じて三種類の「詩文」を収集できます。「詩文」は「コレットの花房」で交換して道具報酬を獲得するために使用でき、イベント限定SR命輪「往日の花と詩」、「ヘブンズコア」、「ルーメンのコア」、「賢石の破片」、「擬態凝晶」などが含まれます。\n2、イベント期間中「特務記録：薔薇の住処」が無料開放されます。\n\n<Title:イベント期間>\n1、8月10日 9:00 - 9月7日 9:00（GMT+8）、すべてのイベント内容に参加できます。\n2、9月7日 9:00 - 9月14日 9:00（GMT+8）、「コレットの花房」と「実績報酬」のみ保留され、その他の内容は終了済みで参加できません。\n\n<Title: ガーデンの思い出>\n1、「ガーデンの思い出」には5つのステージが含まれ、2日ごとに1つ自動開放されます。\n2、挑戦するたびに「エンフェリン」× 120を消費し、挑戦成功でイベント通貨「憂愁の詩文」、「遺憾の詩文」および「歓喜の詩文」を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。ご注意：「リプレイ」機能使用時は同調率を獲得できません。\n4、校友会の救援と「共鳴：ガーデン・レクイエム」を使用して、より簡単にクリアすることができます。\n5、ステージ解放後2日目に、そのステージの狂気の難易度が解放されます。狂気の難易度の初回クリアで豊富なイベント通貨報酬を獲得できます。\n6、ご注意：狂気の難易度の挑戦はエンフェリンを消費せず、リプレイ不可で、初回クリア後の再挑戦ではイベント通貨報酬を再度獲得できません。\n\n<Title: 詩文ボーナス>\n1、守秘者が特定の覚醒体または命輪を所持している場合（出撃不要）、「ガーデンの思い出」ステージタスク報酬の「憂愁の詩文」、「遺憾の詩文」および「歓喜の詩文」に追加ドロップボーナスが適用されます（リプレイを含む）。具体的なボーナスは以下の通りです：\n·覚醒体「オルラ」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n·SSR命輪「最後の一節」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n·SR命輪「往日の花と詩」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体または命輪の「詩文ボーナス」は重複して計算されます。\n3、特に、狂気の難易度の初回クリア挑戦報酬は「詩文ボーナス」の影響を受けません。\n\n<Title:共鳴：ガーデン・レクイエム>\n1、守秘者は活動実績を達成することで「灰烬の心」を獲得できます。\n2、「灰烬の心」を消費して「共鳴：ガーデン・レクイエム」を発動すると、以下のボーナスを獲得できます：\n（1）イベントゲームプレイ「ガーデンの思い出」において守秘者を強化し、挑戦をより簡単にします。\n（2）「ガーデンの思い出」挑戦完了後に獲得できるイベント通貨を増加させます。\n（3）イベントゲームプレイ「ミューズのキス」を発動します。\n\n<Title: ミューズのキス>\n·共鳴「万物成長」を発動後、毎時間自動的に「憂愁の詩文」× 60を獲得し、最大25時間分を蓄積できます。\n·共鳴「詩で花を交換する」を発動後、「ミューズのキス」で毎時間追加で「遺憾の詩文」× 60を獲得できます。\n\n<Title: コレットの花房>\n1、「コレットの花房」には三つの花壇があり、開始時間は以下の通りです：\n·「アイリス花壇」： 8月10日 9時開始。\n·「桔梗花壇」： 8月12日 9時開始。\n·「ばら花壇」： 8月14日 9時開始。\n2、交換するたびに「憂愁の詩文」/「遺憾の詩文」/「歓喜の詩文」× 750を消費し、花壇内の5つのアイテム報酬をランダムに獲得します。\n3、各花壇のアイテム報酬は「特別アイテム」と「通常アイテム」の2種類に分かれており、リセット時に特別アイテム報酬の残り数量を上限までリセットできます。具体的なルールは以下の通りです：\n（1）最初の2回のリセット：「特別アイテム」の残り数量がなくなった後、守秘者はリセットを選択でき、リセット後に「特別アイテム」と「通常アイテム」の残り数量が上限までリセットされます；また交換を続けることも選択でき、「通常アイテム」も残り数量がなくなった後は、リセットしなければ交換を続けられません。\n（2）3回目以降のリセット：「通常アイテム」の残り数量がなくなった後にのみリセットでき、リセットにより「通常アイテム」の残り数量が上限までリセットされますが、「特別アイテム」はリセットされません。\n4、9月14日 9:00（GMT+8）以降、残り未交換の「詩文」は1つにつき「薔薇金券」× 40の比率で回収されます。守秘者はメールの受け取りにご注意ください。\n\n<Title: 特務記録>\n1、イベント期間中「特務記録：薔薇の住処」が無料開放されます。2日ごとに新しいイベントが追加され、「特務記録：薔薇の住処」をクリアすると実績報酬でシルバーコア、イベント限定SR命輪「往日の花と詩」などの報酬を獲得できます。実績報酬はイベント期間中のみ開放され、イベント終了後は完了および受け取りができません。\n2、イベント終了後、「特務記録：薔薇の住処」の調査進度は保留されます。イベント期間中に「特務記録：薔薇の住処」を解放しなかった場合、イベント終了後も「起点装置」×7を消費して解放できます。\n3、イベント期間中かどうかにかかわらず、「特務記録：薔薇の住処」をクリアすると「キーオーダー：春の詩」を獲得できます。"
  },
  Activity_67718_BannerText = {
    Text = "期間限定イベント開催中！"
