  Activity_67726_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「聖堂の道」、「市民の善意」と「達成報酬」を通じてイベント通貨「チャリティ券」を収集し、「聖堂チャリティ会場」でランダムアイテムと交換可能。イベント限定SR運命の札「鏡の中の人」、ヘブンズコア、ルミナスコアなどが含まれます。\n2、イベント期間中、「特務記録：血の色」が無料で開放され、イベント達成でイベント限定アイコン「銀の鍵の名のもとに：サルバドル」を獲得できます！\n\n<Title:イベント時間>\n1、3月24日15:00 - 4月7日15:00、すべてのイベント内容に参加できます。\n2、4月7日15:00 - 4月14日15:00、参加できるのは「聖堂チャリティ会場」と「達成報酬」のみで、他の内容は終了しています。\n\n<Title:聖堂の道>\n1、「聖堂の道」には5つのステージがあり、2日ごとに1つ自動で開放されます。\n2、各挑戦には120点のエンフェリンを消費し、成功するとイベント通貨「チャリティ券」を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。注意：「リプレイ」機能を使用すると同調率を獲得できません。\n4、フレンドの救援と「共鳴：魂の分岐点」を利用して、より簡単にクリアできます。\n\n<Title:輝光ボーナス>\n1、「魂の輝光」の影響下で、守秘者が特定の覚醒体や運命の札を持っていると（出陣不要）、聖堂の道ステージの任務報酬の「チャリティ券」に追加のドロップボーナスが得られます（リプレイを含む）。具体的なボーナスは以下の通り：\n・覚醒体「サルバドル」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%。\n・SSR運命の札「神知の石板」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%。\n・SR運命の札「鏡の中の人」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%。\n2、異なる覚醒体や運命の札の「輝光ボーナス」は積み重ねて計算されます。\n3、特に、超難度の初回クリア報酬は「輝光ボーナス」の影響を受けません。\n\n<Title:共鳴：魂の分岐点>\n1、守秘者は達成報酬を完了することで「懺悔の心」を獲得できます。\n2、「懺悔の心」を消費して「共鳴：魂の分岐点」を活性化すると、以下のボーナスを得られます：\n（1）守秘者がイベントプレイ「聖堂の道」と「特務記録：血の色」でより強くなり、挑戦がより簡単になります。\n（2）「聖堂の道」挑戦後に得られる同調率が向上します。\n（3）イベントプレイ「市民の善意」を活性化します。\n\n<Title:市民の善意>\n1、共鳴「簡単な方法」を活性化すると、毎時60「チャリティ券」を自動で獲得し、最大25時間まで蓄積できます。\n2、共鳴「贖罪、贖罪」を活性化すると、毎時1800薔薇金券を追加で自動獲得します。\n\n<Title:聖堂チャリティ会場>\n1、「聖堂チャリティ会場」には3つの商店があり、開店時間は以下の通り：\n・「グレイ夫人の小店」：3月24日15:00開放。\n・「ビッグジョンの不思議なチャリティ」：3月27日15:00開放。\n・「スミス特売」：3月30日15:00開放。\n2、各交換には750「チャリティ券」を消費し、商店からランダムで5つのアイテム報酬を獲得します。\n3、各商店のアイテム報酬は「特別アイテム」と「通常アイテム」の2種類に分かれ、リセット時に特別アイテム報酬の残り数量を上限までリセットできます。具体的なルールは：\n（1）最初の2回のリセット：特別アイテムの残り数量がなくなった場合、守秘者はリセットを選択できます。リセット後、特別アイテムと通常アイテムの残り数量が上限までリセットされます。または、通常アイテムの残り数量がなくなるまで交換を続け、通常アイテムの残り数量がなくなった場合、リセットを行う必要があります。\n（2）3回目以降のリセット：通常アイテムの残り数量がなくなった場合にのみリセットが可能で、リセットにより通常アイテムの残り数量が上限までリセットされ、特別アイテムはリセットされません。\n4、4月14日15:00以降、未交換の「チャリティ券」は、1つにつき「薔薇金券×40」の比率で回収されますので、守秘者はメールを確認してください。\n\n<Title:特務記録>\n1、イベント期間中「特務記録：血の色」が無料で開放されます。\n2、イベント終了後も「特務記録：血の色」の調査進捗は保持され、イベント期間中に解放されなかった場合でも「起点装置」×7を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「特務記録：血の色」をクリアすると「キーオーダー：奇蹟の夜明け」を獲得できます。\n\n<Title:復刻補償>\n1、以前に「特務記録：血の色」を解放した守秘者は、今回の復刻イベント期間中に再度解放すると「チャリティ券」×700の補償を受け取ります。\n2、以前にイベント限定アイコン「銀の鍵の名のもとに：サルバドル」を獲得した守秘者は、再度獲得すると自動で1つの「無形者の招待状」に変換されます。\n3、以前に共鳴活性化素材「懺悔の心」を獲得した守秘者は、余分な「懺悔の心」を1つ獲得するごとに自動で「薔薇金券」×5000に変換されます。\n"
  },
  Activity_67726_BannerText = {
