  Activity_67727_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「業の芽生え」のみ参加可能です。"
  },
  Activity_67727_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「波乱の情欲」と「達成報酬」を通じてイベント通貨「豊穣の種核」を収集できます。\n「豊穣の種核」は「業の芽生え」で報酬と交換でき、交換報酬には、イベント限定SR運命の札「熱い別れのキス」、ルミナスコア、ヘブンズコア、賢石の破片、擬態凝晶などが含まれます。\n2、イベント期間中、「繁栄狂宴」の参加条件が「調査行動2-9・通常をクリア」に緩和され、覚醒体の同調率の条件を満たさなくても「繁栄狂宴事件」を解放できます。\nさらに、消費する「起点装置」数の要件も1個に減少します！\n3、神秘的な力の到来により、守秘者と覚醒体との関係がより深まる助けとなるようです。\nイベント期間中、すべての方法で獲得する同調率が2倍になります！\n\n<Title:波乱の情欲>\n1、「波乱の情欲」には探索不要で直接戦闘を行うタイプの、10の素材獲得ステージがあり、毎日1つ自動で開放されます。\n2、これらの素材獲得ステージでは、すべての覚醒体が直接覚醒し、設定された遺物を獲得します。\nさらに、6ターン経過後に1度、タイスの助力を受けます。\n3、挑戦ごとに120点のエンフェリンを消費し、育成素材とイベント通貨を獲得できます。\n4、ステージクリア後、そのステージの「リプレイ」機能が解放されます。\n※注意：「リプレイ」機能を使用すると同調率を獲得できません。\n5、フレンドの救援を利用すると、より簡単にクリアできます。\n\n<Title:強欲ボーナス>\n1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「波乱の情欲」ステージのイベント通貨「豊穣の種核」の追加ドロップボーナスが得られます。（リプレイを含む）\nボーナスは以下の通り：\n・覚醒体「タイス」：\n霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「慈悲の育み」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「熱い別れのキス」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n\n2、異なる覚醒体や運命の札の「強欲ボーナス」は累計で計算されます。\n3、特に、超難度の初回クリア報酬は上記のボーナスの影響を受けません。\n\n<Title:業の芽生え>\n1、1回の交換ごとに「豊穣の種核」を1000枚消費し、「業の芽生え」内のアイテム報酬から5つをランダムに獲得します。\n2、「業の芽生え」のアイテム報酬は「特別アイテム」と「通常アイテム」の2種類に分かれます。リセット時に「特別アイテム」報酬の残量を上限まで戻すことができます。\n具体的なルールは以下の通り：\n（1）最初4回までのリセット：「特別アイテム」の数量がなくなった場合、守秘者がリセットを選ぶことができ、「特別アイテム」と「通常アイテム」の残量を上限まで戻せます。\nもしくは、そのまま交換を続けることもできますが、「通常アイテム」も数量がなくなった場合は、リセットを行う必要があります。\n\n（2）5回目以降のリセット：「通常アイテム」の残り数量がなくなった場合にのみリセット可能になります。リセットにより「通常アイテム」の残量を上限まで戻せますが、「特別アイテム」は戻りません。\n\n<Title:イベント期間>\n1、12月16日 9:00 - 12月30日 9:00（GMT+8）、すべてのイベント内容に参加できます。\n2、12月30日 9:00 - 1月6日 9:00（GMT+8）、参加できるのは「業の芽生え」と「達成報酬」のみです。他の内容は終了となります。\n3、1月6日 9:00（GMT+8）以降、未交換の「豊穣の種核」は、1つにつき「薔薇金券×40」の比率で回収されますので、守秘者はメールをご確認ください。"
  },
