  Activity_67731_ActivityPlot = {
    Text = "イサラウ、湖中の城……その場所はワンダの故郷と言い伝えられている。\n今、あなたは夢の門をくぐり抜け、無数の鐘が鳴り響く、古の塔群へと辿りつく……"
