  Activity_67731_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「ワンダの秘宝箱」のみ参加可能です。"
  },
  Activity_67731_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「燃える饗宴」と「達成報酬」を通じてイベント通貨「原生の脛骨」「円形菊石」「螺旋遺跡」を収集できます。\nイベント通貨は「ワンダの秘宝箱」でアイテム報酬に交換でき、交換報酬には、イベント限定SR運命の札「イサラウの眼差し」、ルミナスコア、ヘブンズコアなどが含まれます。\n2、イベント期間中、「意識潜行：燃える饗宴」が無料で開放され、「達成報酬」の任務を完了すると、イベント限定アイコン「銀の鍵の名のもとに：ワンダ」を獲得できます！\n\n<Title:イベント期間>\n1、9月23日 9:00 - 10月7日 9:00（GMT+8）、すべてのイベント内容に参加できます。\n2、10月7日 9:00 - 10月14日 9:00（GMT+8）、参加できるのは「ワンダの秘宝箱」と「達成報酬」のみです。\n\n<Title:湖中の城>\n1、「湖中の城」には7つのステージがあり、毎日1つ自動で開放されます。\n2、挑戦ごとに「エンフェリン」×120を消費し、イベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。\n※注意：「リプレイ」機能を使用すると同調率を獲得できません。\n4、フレンドの救援と「共鳴：代行の密令」を利用すると、より簡単にクリアできます。\n\n<Title:秘宝ボーナス>\n1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「湖中の城」ステージのイベント通貨の追加ドロップボーナスが得られます。\nボーナスは以下の通り：\n・覚醒体「ワンダ」：\n霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「女王の戒律」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「イサラウの眼差し」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体や運命の札の「秘宝ボーナス」は累計で計算されます。\n3、特に、超難度の初回クリア報酬は上記のボーナスの影響を受けません。\n\n<Title:共鳴：代行の密令>\n1、守秘者は達成報酬を完了することで「享楽の心」を獲得できます。\n2、「享楽の心」を消費して「共鳴：代行の密令」を活性化すると、守秘者は「湖中の城」で強くなり、挑戦が容易になります。また、クリア時に追加のイベント通貨を獲得できます。\n\n<Title:意識潜行>\n1、イベント期間中「燃える饗宴」が無料で開放されます。\n2、イベント終了後も「燃える饗宴」の調査進捗は保持され、未完了の調査イベントを完了すると、イベント期間中と同じ調査報酬を獲得できます。\nイベント期間中に「燃える饗宴」を解放しなかった場合、イベント終了後も「起点装置」×3を消費して解放できます。\n3、イベント期間中か否かにかかわらず、「燃える饗宴」をクリアすると「キーオーダー：腐敗の饗宴」を獲得できます。\n\n<Title:復刻補償>\n1、以前に「意識潜行：燃える饗宴」を解放した守秘者は、本復刻イベント期間中に再解放時に「原生の脛骨」×300の補償を得られます。\n2、以前に、イベント限定アイコン「銀の鍵の名のもとに：ワンダ」を獲得していた場合、再獲得時に自動的に「原生の脛骨」×2000に変換されます。\n3、以前に、共鳴活性材料「享楽の心」を獲得していた場合、余剰の「享楽の心」を1個獲得するごとに自動的に「薔薇金券」×5000に変換されます。"
  },
