  Activity_67734_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「安眠宮殿」のみ参加可能です。"
  },
  Activity_67734_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「轟鳴音」と「達成報酬」を通じてイベント通貨「高らかな楽章」を収集可能。「高らかな楽章」は「安眠宮殿」でSR運命の札「終わりなき演奏」、ヘブンズコア、ルミナスコア、賢石の破片、擬態凝晶などの豪華報酬と交換可能。\n2、イベント期間中、「達成報酬」の任務を達成すると、イベント限定アイコン「銀の鍵の名のもとに：ハムリン」、イベント限定SR運命の札「終わりなき演奏」、シルバーコア、及び大量の「高らかな楽章」を獲得可能。\n\n<Title:イベント期間>\n1、9月9日9:00 - 9月23日9:00（GMT+8）、すべてのイベント内容に参加できます。\n2、9月23日9:00 - 9月30日9:00（GMT+8）、「安眠宮殿」と「達成報酬」のみ利用でき、他の内容は終了します。\n\n<Title: 轟鳴音>\n1、「轟鳴音」は9つのステージを含み、毎日1つずつ自動で解放されます。\n2、各チャレンジごとに120エンフェリンを消費し、異なるステージで異なる素材のドロップや「高らかな楽章」を獲得可能。\n3、今回のステージは直接戦闘素材ステージであり、クリア後に「リプレイ」可能。「リプレイ」には120点エンフェリンを消費。\n4、「リプレイ」機能使用時、同調率は獲得不可なので注意。\n\n<Title: 楽章ボーナス>\n1、守秘者が特定の覚醒体または運命の札を所持している場合（出陣不要）、「轟鳴音」ステージの任務報酬「高らかな楽章」に追加ドロップボーナスが付与されます（リプレイ含む）。具体的なボーナスは以下の通り：\n・覚醒体「ハムリン」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「永遠のレクイエム」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「終わりなき演奏」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体や運命の札の「楽章ボーナス」は累積されます。\n3、特に、超難度の初回クリア報酬は「楽章ボーナス」の影響を受けません。\n\n<Title: 安眠宮殿>\n1、「安眠宮殿」は9月9日9:00 - 9月30日9:00（GMT+8）にのみ開放されます。\n2、9月30日9:00（GMT+8）の時点で交換していない「高らかな楽章」は1つにつき「薔薇金券×40」の比率で回収されるので、守秘者はメールをチェックしてください。"
  },
