  Activity_67741_ActivityPlot = {
    Text = "ドールの任務は簡単にはいかない。\n彼女が何度も「楽しんで」と、念を押しても、初めて集団の覚醒体たちを連れて外出するのは、守秘者にとっても緊張の連続だ。\nでも「楽しんで」を忘れないで。"
