  Activity_67741_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「魔法の脚本屋」のみ参加可能です。"
  },
  Activity_67741_ActivityTips = {
    Text = "<Title:イベント概要>\n1、復刻イベント「物語の魔法」が期間限定でオープン！\n「魔法の脚本屋」や「達成報酬」を通じて、再びイベント限定SR運命の札「35mmの魔法」や、イベント限定アイコン「銀の鍵の名のもとに：リリー」など様々な報酬を獲得できます。\n\n2、イベント期間中、「特務記録：物語の魔法」が無料開放されます。\n\n<Title:脚本の謎>\n1、「脚本の謎」には9つのステージがあり、毎日1つ自動で開放されます。\n\n2、各挑戦には120点のエンフェリンを消費し、チャレンジに成功するとイベント通貨を獲得できます。\n\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。\n※注意：「リプレイ」機能を使用すると同調率を獲得できません。\n\n4、フレンドの救援と「共鳴：監督の演出指示」を利用すると、より簡単にクリアできます。\n\n<Title:閃きボーナス>\n1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「脚本の謎」ステージ報酬のイベント通貨「揺蕩う閃き」の追加ドロップボーナスが得られます。（リプレイを含む）\n\n具体的なボーナスは以下の通り：\n・覚醒体「リリー」：\n霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n\n・SSR運命の札「痛みを越えて」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n\n・SR運命の札「35mmの魔法」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n\n2、異なる覚醒体や運命の札の「閃きボーナス」は累計で計算されます。\n\n3、特に、超難度の初回クリア報酬は上記のボーナスの影響を受けません。\n\n<Title:共鳴：監督の演出指示>\n1、守秘者は達成報酬を完了することで「演技の心」を獲得できます。\n\n2、「演技の心」を消費して「共鳴：監督の演出指示」を起動すると、イベントプレイ「脚本の謎」と「特務記録：物語の魔法」で守秘者がより強くなります。\n\n<Title:復刻補償>\n1、以前に「特務記録：物語の魔法」を解放した守秘者は、本復刻イベント期間中に再解放時に「揺蕩う閃き」×700の補償を得られます。\n\n以前に、イベント限定アイコン「銀の鍵の名のもとに：リリー」を獲得していた場合、再獲得時に自動的に「揺蕩う閃き」×2000に変換されます。\n以前に、共鳴活性材料「演技の心」を獲得していた場合、余剰の「演技の心」を1個獲得するごとに自動的に「薔薇金券」×5000に変換されます。\n\n<Title:イベント期間>\n1、1月13日15:00 - 1月27日15:00、すべてのイベント内容に参加できます。\n\n2、1月27日15:00 - 2月3日15:00、「魔法の脚本屋」と「達成報酬」のみが残り、他の内容は終了し参加できません。\n\n3、2月3日15:00以降、未交換の「揺蕩う閃き」は、1つにつき「薔薇金券×40」の比率で回収されますので、守秘者はメールをご確認ください。"
  },
