  },
  Activity_67742_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「薔薇の記憶」と「達成報酬」を通じてイベント通貨「霊鳥の羽扇」を収集できます。\n「霊鳥の羽扇」は「金紅祭典」で豪華報酬と交換可能です。交換報酬には、イベント限定SR運命の札「百万の寵愛の眼」、ヘブンズコア、ルミナスコア、賢石の破片、擬態凝晶などが含まれます。\n\n2、イベント期間中、「達成報酬」の任務を完了するとイベント限定アイコン「銀の鍵の名のもとに：ソレール」、イベント限定SR運命の札「百万の寵愛の眼」、シルバーコア、そして大量のイベント通貨「霊鳥の羽扇」を獲得できます。\n\n3、イベント期間中、「特務記録：薔薇の讃歌」が無料開放されます。\n\n<Title: 薔薇の記憶>\n1、「薔薇の記憶」には9つのステージがあり、毎日1つ自動で開放されます。\n\n2、各挑戦には120点のエンフェリンを消費し、ステージ毎に異なる素材ドロップと、イベント通貨「霊鳥の羽扇」を獲得できます。\n\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。\n※注意：「リプレイ」機能を使用すると同調率を獲得できません。\n\n4、フレンドの救援を利用して、より簡単にクリアできます。\n\n<Title: 羽扇ボーナス>\n1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「薔薇の記憶」ステージ報酬のイベント通貨「霊鳥の羽扇」の追加ドロップボーナスが得られます。（リプレイを含む）\n\n具体的なボーナスは以下の通り：\n・覚醒体「ソレール」：\n霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n\n・SSR運命の札「薔薇の名において」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n\n・SR運命の札「百万の寵愛の眼」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n\n2、異なる覚醒体や運命の札の「羽扇ボーナス」は累計で計算されます。\n\n3、特に、超難度の初回クリア報酬は「羽扇ボーナス」の影響を受けません。\n\n<Title:復刻補償>\n1、イベント期間中、以前に「特務記録：薔薇の讃歌」を解放した守秘者は、再解放時に「霊鳥の羽扇」×700の補償を得られます。\n\nさらに、活動限定アイコン「銀の鍵の名のもとに：ソレール」を獲得した守秘者は、再獲得時に自動的に「霊鳥の羽扇」×2000に変換されます。\n\n<Title:イベント時間>\n1、1月27日15:00 - 2月10日15:00、すべてのイベント内容に参加できます。\n\n2、2月10日15:00 - 2月17日15:00、参加できるのは「金紅祭典」と「達成報酬」のみです。\n\n3、2月17日15:00以降、未交換の「霊鳥の羽扇」は、1つにつき「薔薇金券×40」の比率で回収されますので、守秘者はメールをご確認ください。"
  },
