  Activity_67745_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「山岳の大口」のみ参加可能です。"
  },
  Activity_67745_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定ゲームプレイ「獣の野心」や「達成報酬」で3種類の「蕾」を集めることができ、「蕾」は「山脈の巨口」でアイテムに交換可能。イベント限定SR命輪「雪が溶けるまで」、ヘブンズコア、ルーメンのコア、賢石の破片、擬態凝晶などを獲得可能。\n2、イベント期間「特務記録：エルワースの帰人」が無料開放されます。\n\n<Title:イベント期間>\n1、7月13日9:00 - 8月10日9:00（GMT+8）、すべてのイベント内容に参加可能。\n2、8月10日9:00 - 8月17日9:00（GMT+8）、「山脈の巨口」と「達成報酬」のみ参加可能、それ以外の内容は終了済み。\n\n<Title: 獣の野心>\n1、「獣の野心」は5つのステージがあり、2日ごとに1つ自動解放されます。\n2、毎回の挑戦でエンフェリン×120を消費、成功するとイベント通貨「寒凍の蕾」、「銀霜の蕾」、「日光の蕾」を獲得。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。「リプレイ」機能使用時、同調率は獲得できません。\n4、校友会の救援や「共鳴：捕食山脈」を利用してクリアしやすくなります。\n5、注意：狂気の難易度挑戦ではエンフェリンを消費せず、リプレイ不可。初クリア後、繰り返し挑戦してもイベント通貨を獲得できません。\n\n<Title: 蕾ボーナス>\n1、守秘者が特定の覚醒体または命輪（出陣不要）を所有している場合、「獣の野心」のステージ任務報酬の「寒凍の蕾」、「銀霜の蕾」、「日光の蕾」のドロップ率が増加（リプレイを含む）。具体的なボーナスは以下の通り：\n·覚醒体「血鎖・ヘロット」：霊知啓発0/1/2/3以上で、20%/30%/40%/50%アップ\n·SSR命輪「深紅に沈む」：強化0/1/2/3以上で、20%/30%/40%/50%アップ\n·SR命輪「雪が溶けるまで」：強化0/1/2/3以上で、20%/30%/40%/50%アップ\n2、異なる覚醒体や命輪の「蕾ボーナス」は累積されます。\n3、特に、狂気の難易度の初クリア報酬は「蕾ボーナス」の影響を受けません。\n\n<Title:共鳴：捕食山脈>\n1、守秘者はイベント実績を完了することで「のどかん」を獲得できます。\n2、「のどかん」を消費し、「共鳴：捕食山脈」を発動することで、イベントゲームプレイ「獣の野心」で強化され、挑戦が楽になります。\n\n<Title: 山脈の巨口>\n1、「山脈の巨口」には3つの交換商店があり、開店時間は以下の通り：\n·「呑み込む野心」：7月13日9時開放。\n·「復讐の戦意」：7月15日9時開放。\n·「復活の希望」：7月17日9時開放。\n2、交換ごとに「寒凍の蕾」/「銀霜の蕾」/「日光の蕾」×750を消費し、ランダムで交換商店の5つのアイテムを獲得。\n3、交換商店のアイテムは「特別アイテム」と「通常アイテム」に分かれ、リセット時に特別アイテムの残り数量を上限にリセットできる。具体的なルールは以下の通り：\n（1）前2回のリセット：「特別アイテム」がなくなると守秘者はリセットを選択可能、リセット後は「特別アイテム」と「通常アイテム」の残り数量が上限に。リセットせずに続けることも可能で、「通常アイテム」もなくなるとリセットが必要。\n（2）3回目以降のリセット：「通常アイテム」がなくなるとリセット可能、リセット後「通常アイテム」の残り数量が上限に。「特別アイテム」はリセットされません。\n4、8月17日9:00（GMT+8）以降、未交換の「蕾」は1個あたり薔薇金券×40で回収されますので、守秘者はメールをチェックしてください。\n\n<Title: 特務記録>\n1、イベント期間中、「特務記録：エルワースの帰人」が無料開放。「特務記録：エルワースの帰人」をクリアすることで達成報酬としてシルバーコアやイベント限定SR命輪「雪が溶けるまで」などの報酬を獲得可能。達成報酬はイベント期間中のみ有効、イベント終了後は完了および受取不可。\n2、イベント終了後、「特務記録：エルワースの帰人」の調査進捗は保留されます。イベント期間中に「特務記録：エルワースの帰人」を未ロックの場合、イベント終了後も起点装置×7を消費して解放可能です。\n3、イベント期間を問わず、「特務記録：エルワースの帰人」のクリア後、「キーオーダー：山々の覚悟」を獲得できます。"
  },
