  Activity_67746_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「最終テスト」と「達成報酬」を通じてイベント通貨「終末針」を収集。「終末針」は「回声」で豊富な報酬と交換可能、限定SR運命の札「真理の扉」、ヘブンズコア、ルミナスコア、賢石の破片、擬態凝晶などを含む。\n2、イベント期間中、「達成報酬」の任務を完了すると、限定アイコン「銀の鍵の名のもとに：タヴィ」、限定SR運命の札「真理の扉」、シルバーコア、大量イベント通貨「終末針」を獲得できます。\n\n<Title:イベント期間>\n1、11月3日 9:00 - 11月17日 9:00（GMT+8）までの全コンテンツに参加可能。\n2、11月17日 9:00 - 11月24日 9:00（GMT+8）のみ「回声」と「達成報酬」利用可能、他コンテンツは終了。\n\n<Title:最終テスト>\n1、「最終テスト」は全9ステージ、毎日1ステージ自動解放。\n2、挑戦ごとにエンフェリン120点を消費、異なるステージで異なる素材が入手でき、「終末針」も獲得。\n3、今回のイベントステージは直接戦闘の素材ステージ、クリア後リプレイ可能！リプレイごとにエンフェリン120点を消費。\n4、「リプレイ」機能使用時、同調率は獲得できません。\n\n<Title:終末針ボーナス>\n1、特定の覚醒体または運命の札所持（編成不要）で、「最終テスト」ステージの「終末針」報酬に追加ボーナス（リプレイ含む）が適用、具体的なボーナスは以下の通り：\n・覚醒体「タヴィ」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「隠されし運命の輪」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「真理の扉」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体または運命の札の「終末針ボーナス」は累積されます。\n3、特に、超難度初回クリア報酬は「終末針ボーナス」の影響を受けません。\n\n<Title:回声>\n1、「回声」は11月3日 9:00 - 11月24日 9:00（GMT+8）期間限定オープン。\n2、11月24日 9:00（GMT+8）以降、未交換の「終末針」は「薔薇金券×40」換算で回収されるので、守秘者はメールを確認してください。"
  },
