    Text = "<Title: 星辰を超えて・期間限定予約>\n・この限定予約イベントは全8種類のギフトパッケージを含みます。\n初回ギフトは無料でお受け取り可能です。2～8番目のギフトは「星辰を超えて・期間限定予約」ご購入後にのみお受け取りいただけます。\n　\n・「星辰を超えて・期間限定予約」ご購入後は直ちに第2ギフトの特典をお受け取りいただけますが、以降のギフトは一定期間後にお受け取り可能になります。\n　\n・「星辰を超えて・期間限定予約」ご購入には時間制限があり、期限を過ぎますと再購入できません。適宜ご購入ください。"
