  Activity_68405_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「深海凝視」と「達成報酬」を通じてイベント通貨「疲弊の思念」「哀愁の思念」「歓喜の思念」を収集できます。イベント通貨は「意識の深淵」で商品を購入するのに使用でき、イベント限定SR運命の札「青石の玉座」、ルミナスコア、ヘブンズコア、賢石の破片、擬態凝晶などが含まれます。\n2、イベント期間中、イベント達成を完了すると、イベント限定アイコン「銀の鍵の名のもとに：トゥルー」、イベント限定SR運命の札「青石の玉座」、シルバーコアと大量のイベント通貨を獲得できます！\n\n<Title:イベント時間>\n1、12月30日 9:00 - 1月13日 9:00（GMT+8）、すべてのイベント内容に参加できます。\n2、1月13日 9:00 - 1月20日 9:00（GMT+8）、参加できるのは「意識の深淵」と「達成報酬」のみです。\n\n<Title:深海凝視>\n1、「深海凝視」には5つのステージがあり、2日ごとに1つ自動で開放されます。\n2、各挑戦には120点のエンフェリンを消費し、成功するとイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。\n※注意：「リプレイ」機能を使用すると同調率を獲得できません。\n4、フレンドの救援を利用して、より簡単にクリアできます。\n\n<Title:思念ボーナス>\n1、守秘者が特定の覚醒体や運命の札を持っていると（出陣不要）、深海凝視ステージの任務報酬のイベント通貨に追加のドロップボーナスが得られます。具体的なボーナスは以下の通り：\n・覚醒体「トゥルー」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「神王の讃歌」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「青石の玉座」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体や運命の札の「思念ボーナス」は累計で計算されます。\n3、特に、超難度の初回クリア報酬は「思念ボーナス」の影響を受けません。\n\n<Title:意識の深淵>\n1、「意識の深淵」は12月30日 9:00 - 1月20日 9:00（GMT+8）の期間にのみ開放されます。\n2、1月20日 9:00（GMT+8）以降、未交換の「疲弊の思念」「哀愁の思念」「歓喜の思念」は、1つにつき「薔薇金券×40」の比率で回収されますので、守秘者はメールをご確認ください。"
