  Activity_68406_ActivityPlot = {
    Text = "人々は渇望するものを記憶の奥深くに埋め、虚構の仮面をかぶって世界に迎合する。\n聞け、血肉の皮に覆われたものの叫びが、記憶の霧の中で響き渡っている。\n思考を空にし、血肉を捨て、真実の自分を迎えよう。"
