  },
  Activity_68406_ActivityTips = {
    Text = "<Title:イベント概要>\nイベント期間中、守秘者は期間限定の「恐怖癒療」と「達成報酬」を通じてイベント通貨を収集し、イベント通貨は「神経診療室」でアイテム報酬と交換可能。イベント限定SR運命の札「催眠霊振り子」、賢者の石、ヘブンズコア、ルミナスコアなどが含まれます。\n\n<Title:イベント時間>\n1、4月7日15:00 - 4月21日15:00、すべてのイベント内容に参加できます。\n2、4月21日15:00 - 4月28日15:00、参加できるのは「神経診療室」と「達成報酬」のみで、他の内容は終了しています。\n\n<Title:恐怖癒療>\n1、「恐怖癒療」には5つのステージがあり、2日ごとに1つ自動で開放されます。\n2、各挑戦には120点のエンフェリンを消費し、成功するとイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。注意：「リプレイ」機能を使用すると同調率を獲得できません。\n4、フレンドの救援を利用して、より簡単にクリアできます。\n\n<Title:イベントボーナス>\n1、守秘者が特定の覚醒体や運命の札を持っていると（出陣不要）、「恐怖癒療」ステージの任務報酬の「診断報告」に追加のドロップボーナスが得られます（リプレイを含む）。具体的なボーナスは以下の通り：\n・覚醒体「クレメンタイン」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「隠没の痛み」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「催眠霊振り子」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体や運命の札の「イベントボーナス」は積み重ねて計算されます。 \n3、特に、超難度の初回クリア報酬は「イベントボーナス」の影響を受けません。\n\n<Title:神経診療室>\n1、各「報告提出」には1000「診断報告」を消費し、「神経診療室」からランダムで5つのアイテム報酬を獲得します。\n2、「神経診療室」のアイテム報酬は「特別アイテム」と「通常アイテム」の2種類に分かれ、リセット時に特別アイテム報酬の残り数量を上限までリセットできます。具体的なルールは：\n（1）最初の5回のリセット：特別アイテムの残り数量がなくなった場合、守秘者はリセットを選択できます。リセット後、特別アイテムと通常アイテムの残り数量が上限までリセットされます。または、通常アイテムの残り数量がなくなるまで交換を続け、通常アイテムの残り数量がなくなった場合、リセットを行う必要があります。\n（2）6回目以降のリセット：通常アイテムの残り数量がなくなった場合にのみリセットが可能で、リセットにより通常アイテムの残り数量が上限までリセットされ、特別アイテムはリセットされません。\n3、4月28日15:00以降、未交換の「診断報告」は、1つにつき「薔薇金券×40」の比率で回収されますので、守秘者はメールを確認してください。"
  },
