  Activity_68410_ActivityName = {
    Text = "雨の町に潜む影"
  },
  Activity_68410_ActivityPlot = {
    Text = "その朧げで湿った夜の雨の中、運命の出会いがあなたを待っていた。\n彼女の名前、その姿は馴染み深く、穏やかで優雅な声はいつもあなたの心を不思議と安心させた。\nけれど、あなたは忘れていた。\n人間の願いを叶えるのはいつだって神か悪魔だけなのだと……\nさぁ、はたして彼女はどちらに属しているのか？"
  },
  Activity_68410_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「魔女の宝庫」のみ参加可能です。"
  },
  Activity_68410_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「魔女の店」と「達成報酬」を通じてイベント通貨を収集できます。\nイベント通貨は「魔女の宝庫」で交換してアイテム報酬を獲得でき、イベント限定SR運命の札「魔女のつば広帽子」、賢者の石、ヘブンズコア、ルミナスコアなどが含まれます。\n\n2、イベント期間中、「特務記録：雨の町に潜む影」が無料で開放され、イベント達成でイベント限定アイコン「銀の鍵の名のもとに：ダフォダイル」を獲得できます！\n\n<Title:イベント時間>\n1、2月24日9:00 – 3月10日9:00（GMT+8）、すべてのイベント内容に参加できます。\n2、3月10日9:00 – 3月17日9:00（GMT+8）、参加できるのは「魔女の宝庫」と「達成報酬」のみで、その他の内容は終了し参加できません。\n\n<Title:魔女の店>\n1、「魔女の店」には5つのステージがあり、2日ごとに1つ自動で開放されます。\n\n2、各挑戦には120点のエンフェリンを消費し、成功するとイベント通貨を獲得できます。\n\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。\n※注意：「リプレイ」機能を使用すると同調率を獲得できません。\n\n4、フレンドの救援を利用して、より簡単にクリアできます。\n\n<Title:イベントボーナス>\n1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「魔女の店」ステージ報酬のイベント通貨「蒼白の獣の頭蓋骨」「幽影の獣の頭蓋骨」「深紅の獣の頭蓋骨」の追加ドロップボーナスが得られます。（リプレイを含む）\n\n具体的なボーナスは以下の通り：\n・覚醒体「ダフォダイル」：\n霊知啓発0/1/2/3以上、ボーナス20％/30％/40％/50％\n\n・SSR運命の札「至高の収蔵品」：\n強化0/1/2/3以上、ボーナス20％/30％/40％/50％\n\n・SR運命の札「魔女のつば広帽子」：\n強化0/1/2/3以上、ボーナス20％/30％/40％/50％\n\n2、異なる覚醒体や運命の札の「イベントボーナス」は累計で計算されます。\n\n3、特に、超難度の初回クリア報酬は「イベントボーナス」の影響を受けません。\n\n<Title:魔女の宝庫>\n1、「魔女の宝庫」には「悩み解消の逸品」「華麗なる秘宝」「珠玉の珍品」の3つがあり、開放時間は以下の通りです：\n・「悩み解消の逸品」：2月24日9:00〜3月17日9:00\n・「華麗なる秘宝」：2月26日9:00〜3月17日9:00\n・「珠玉の珍品」：2月28日9:00〜3月17日9:00\n\n2、交換毎に「蒼白の獣の頭蓋骨」/「幽影の獣の頭蓋骨」/「深紅の獣の頭蓋骨」を750個消費し、宝庫のアイテムを5つランダムに獲得します。\n\n3、各宝庫のアイテム報酬は「特別アイテム」と「通常アイテム」の2種類に分かれます。リセット時に指定アイテム報酬の残量を上限まで戻すことができます。\n\n具体的なルールは以下の通りです：\n（1）最初2回までのリセット：「特別アイテム」の数量がなくなった場合、守秘者がリセットを選ぶことができ、「特別アイテム」と「通常アイテム」の残量を上限まで戻せます。\nもしくは、そのまま交換を続けることもできますが、「通常アイテム」も数量がなくなった場合は、リセットを行う必要があります。\n\n（2）3回目以降のリセット：「通常アイテム」の残り数量がなくなった場合にのみリセット可能になります。リセットにより「通常アイテム」の残量を上限まで戻せますが、「特別アイテム」は戻りません。\n\n<Title:特務記録>\n1、イベント期間中「特務記録：雨の町に潜む影」が無料で開放されます。\n\n2、イベント終了後も「特務記録：雨の町に潜む影」の調査進捗は保持します。\nイベント期間中に解放されなかった場合、「起点装置」×7を消費して解放できます。\n\n3、イベント期間中かどうかに関わらず、「特務記録：雨の町に潜む影」をクリアすると「キーオーダー：灰霧の真容」を獲得できます。"
  },
