  Activity_70438_ActivityName = {
    Text = "ウサネコのルール"
  },
  Activity_70438_ActivityPlot = {
    Text = "祈歳節が近づいており、皆が祝典の準備に集中している間に、隅にあった漆黒の塊が密かに蠢き、小さな囚人が液体となって檻から逃げ出した。\n次元の裂け目が閃く中、その黒い毛球は分裂を始めた……黒い猫の海がキャンパス全体を呑み込もうとしている！\n最初はそれを無視して、この奇妙な事件は校務処理に任せれば良いと考えた。\nしかし、それらがシルバーコアと金券をドロップすることを知り、気が変わった。"
  },
  Activity_70438_ActivityTips = {
    Text = "<Title:イベント概要>\n遊興イベント「ウサネコのルール」が期間限定で開放！イベント期間中、守秘者は「集まれ猫の乱舞」で校猫を暴打し、大量のシルバーコアと薔薇金券を獲得できます！\n\n<Title:イベント時間>\n1月24日9:00 - 2月5日9:00（GMT+8）、イベント期間中は毎日解放された「集まれ猫の乱舞」ステージに参加可能で、終了したステージには参加できません。\n\n<Title:集まれ猫の乱舞>\n1、「集まれ猫の乱舞」には12のステージがあり、毎日異なるステージが開放されるため、終了したステージには参加できません。\n2、チャレンジするたびにエンフェリンを消費せずに、1回のステージクリア後にヘブンズコア、シルバーコア、薔薇金券を獲得できます。\n3、今回のステージではフレンドの救援を使用できません。\n4、その日のステージには、各覚醒体が1回だけ出陣できます。\n5、各日のステージは指定の界域を使用して挑戦する必要があります。\n・1月24日：混沌界域\n・1月25日：深海界域\n・1月26日：血肉界域\n・1月27日：超次元界域\n・1月28日：制限なし\n・1月29日：制限なし\n・1月30日：混沌界域と深海界域\n・1月31日：血肉界域と超次元界域\n・2月1日：混沌界域と血肉界域\n・2月2日：深海界域と超次元界域\n・2月3日：混沌界域と超次元界域\n・2月4日：血肉界域と深海界域"
  },
  Activity_70438_BannerText = {
    Text = "特別イベント期間限定開催！"
  },
  Activity_71095_ActivityName = {
    Text = "サブステージ無料解放"
  },
  Activity_71095_ActivityTips = {
    Text = "<Title:参加条件>\n・「調査」2-9・通常をクリア後に参加可能。\n<Title:調査>\n・イベント期間中、毎日「物語の魔法」の新しい調査が公開され、守秘者は物資を消費せずに調査を解放して実施できます。調査を完了すると、ヘブンズコア、調査勲章、守秘者経験値がもらえます。\n・イベント終了後も、「物語の魔法」の調査進捗は維持され、特務記録で融蝕の珠を消費して未解放の調査を解放し、イベント中に完了できなかった調査を完了すると、イベント中と同じ報酬が得られます。<Title:限定報酬>\n・イベント期間中に限定報酬が公開され、守秘者が「物語の魔法」通常モードをクリアし、「物語の魔法」の調査を完了すると、ヘブンズコア、賢者の石、シルバーコアが得られます。限定報酬はイベント期間中のみ開放され、イベント終了後は完了および受領できません。"
  },
  Activity_71097_ActivityName = {
    Text = "仮テキスト"
  },
  Activity_71097_ActivityPlot = {
    Text = "仮テキスト"
  },
  Activity_71097_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「仮テキスト」のみ参加可能です。"
  },
  Activity_71097_ActivityTips = {
    Text = "<Title:イベント概要>\n仮テキスト"
  },
  Activity_71097_BannerText = {
    Text = "期間限定イベント開催中！"
  },
  Activity_71098_ActivityName = {
    Text = "一歩の隔たり·復刻"
  },
  Activity_71098_ActivityPlot = {
    Text = "彼女は常に人々の前を歩いている。\n一歩、二歩、彼女の足跡は人々の歩調を導いている。\nでも人々はすぐに忘れる。天才と狂人の間はわずか一歩であることを。"
  },
  Activity_71098_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「師の教え」のみ参加可能です。"
  },
  Activity_71098_ActivityTips = {
    Text = "<Title:イベント概要>\nイベント期間中、守秘者は期間限定の「虚無の扉」と「達成報酬」を通じてイベント通貨「人形パーツ」を収集することができます。「人形パーツ」は「師長の教え」の中で報酬と交換でき、イベント限定のSR運命の札「羊飼いの杖」、ルミナスコア、ヘブンズコア、賢石の破片、擬態凝晶などが含まれます。\n\n<Title:虚無の扉>\n1、「虚無の扉」には探索不要の直接戦闘ができる9つの素材レベルが含まれ、毎日1つがオープンされます。\n2、毎回の挑戦には120ポイントのエンフェリンが消費され、挑戦成功で育成素材とイベント通貨が得られます。\n3、レベルクリア後、該当レベルの「リプレイ」機能が解放されます。注意してください：リプレイ機能を使用する際に、同調率は得られません。\n4、フレンドの救援を利用して、より簡単にクリアすることができます。\n\n<Title:人形パーツボーナス>\n1、守秘者が特定の覚醒体や運命の札（編成なし）を持っていると、「虚無の扉」レベルのタスク報酬に含まれる「人形パーツ」が追加のドロップボーナスを受けます（リプレイを含む）、具体的なボーナスは以下の通り：\n・覚醒体「溶融・ドール」：霊知啓発0/1/2/3以上で、ボーナス20%/30%/40%/50%\n・SSR運命の札「虚無に堕ちた人形」：強化0/1/2/3以上で、ボーナス20%/30%/40%/50%\n・SR運命の札「羊飼いの杖」：強化0/1/2/3以上で、ボーナス20%/30%/40%/50%\n2、異なる覚醒体や運命の札の「人形パーツボーナス」は重ね合わせの形で計算されます。 \n3、特に、超難度の初クリア挑戦報酬は上記のボーナスの影響を受けません。\n\n<Title:師長の教え>\n1、毎回「パーツ交換」には750「人形パーツ」が消費され、「師長の教え」から5つのアイテム報酬をランダムに獲得。\n2、「師長の教え」のアイテム報酬は「特別アイテム」と「通常アイテム」の2種類に分かれ、リセット時に特別アイテム報酬の残りの数量を上限にリセットできます、具体的なルールは：\n（1）最初の5回のリセット：特別アイテムが残りの数量がなくなると、守秘者はリセットを選択できます。リセット後、「特別アイテム」と「通常アイテム」の残りの数量を上限にリセットします。または、続けて交換を選択し、「通常アイテム」も残りがなくなると、リセットを行わなければ続けて交換できません。\n（2）6回目以降のリセット：通常アイテムが残りの数量がなくなった後にのみリセットが行え、リセットにより通常アイテムの残りの数量が上限にリセットされ、特別アイテムは再リセットされません。\n\n<Title:イベント時間>\n1、6月16日 9:00 - 6月30日 9:00（GMT+8）、イベント概要のすべての内容に参加できます。\n2、6月30日 9:00 - 7月7日 9:00（GMT+8）、「師長の教え」と「達成報酬」のみが保持され、他の内容は終了して参加できなくなります。\n3、7月7日 9:00（GMT+8）以降、未交換の「人形パーツ」は「薔薇金券×40」の割合で回収されますので、守秘者はメールを確認してください。"
  },
  Activity_71098_BannerText = {
    Text = "期間限定イベント開催中！"
  },
  Activity_71100_ActivityName = {
    Text = "神王の復活"
  },
  Activity_71100_ActivityPlot = {
    Text = "果てなき渇望の祈りの中、彼は長き眠りから束の間目覚め、退屈な世界へと真実の視線を投じる。\n\nしかし、永遠の生命の中では——\nその一時すら、あまりに短い。"
  },
  Activity_71100_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「意識の深淵」のみ参加可能です。"
  },
  Activity_71100_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「深海凝視」と「達成報酬」を通じて、イベント通貨「疲弊の思念」、「哀愁の思念」、「歓喜の思念」を収集できます。イベント通貨は「意識の深淵」にて、イベント限定SR運命の札「青石の玉座」、ルミナスコア、ヘブンズコア、賢石の欠片、擬態凝晶などの商品を購入できます。\n2、イベント期間中、達成報酬を完了すると、イベント限定アイコン「銀の鍵の名のもとに：ケイクス」、イベント限定SR運命の札「青石の玉座」、シルバーコアおよび大量のイベント通貨を獲得できます！\n\n<Title:イベント期間>\n1、12月30日 9:00 - 1月13日 9:00（GMT+8）、すべてのイベント内容に参加できます。\n2、1月13日 9:00 - 1月20日 9:00（GMT+8）、参加できるのは「意識の深淵」と「達成報酬」のみです。\n\n<Title:深海凝視>\n1、「深海凝視」には5つのステージがあり、2日ごとに1ステージずつ自動で解放されます。\n2、各挑戦には「エンフェリン」×120を消費し、クリア時にイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。\n※注意：「リプレイ」機能を使用すると同調率を獲得できません。\n4、フレンドの救援を使用すると、より簡単にクリアできます。\n\n<Title:思念ボーナス>\n1、守秘者が特定の覚醒体または運命の札を所持している場合（編成は不要）、「深海凝視」ステージ報酬から獲得するイベント通貨に追加のドロップボーナスが発生します。具体的なボーナスは以下の通り：\n・覚醒体「トゥルー」：\n霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「神王の讃歌」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「青石の玉座」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体または運命の札の「思念ボーナス」は累計で計算されます。\n3、超難度の初クリア報酬は「思念ボーナス」の影響を受けません。\n\n<Title:意識の深淵>\n1、「意識の深淵」は12月30日 9:00 - 1月20日 9:00（GMT+8）の期間のみ開放されます。\n2、1月20日 9:00（GMT+8）以降、未交換の「疲弊の思念」、「哀愁の思念」、「歓喜の思念」は、1つにつき「薔薇金券」×40の比率で回収されますので、守秘者はメールをご確認ください。"
  },
