  Activity_71102_ActivityName = {
    Text = "物語の魔法・復刻"
  },
  Activity_71102_ActivityPlot = {
    Text = "ドールの任務は簡単にはいかない。\n彼女が何度も「楽しんで」と、念を押しても、初めて集団の覚醒体たちを連れて外出するのは、守秘者にとっても緊張の連続だ。\nでも「楽しんで」を忘れないで。"
  },
  Activity_71102_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「魔法の脚本屋」のみ参加可能です。"
  },
  Activity_71102_ActivityTips = {
    Text = "<Title:イベント概要>\n1、復刻イベント「物語の魔法」が期間限定でオープン！守秘者は「魔法の脚本屋」や「達成報酬」を通じて、再びイベント限定運命の札「35mmの魔法」や、イベント限定アイコン「銀の鍵の名のもとに：リリー」を獲得できます！\n2、イベント期間中、「特務記録：物語の魔法」が無料開放されます。\n\n<Title:イベント期間>\n1、6月3日 9:00 - 6月17日 9:00（GMT+8）、イベント概要のすべての内容に参加できます。\n2、6月17日 9:00 - 6月24日 9:00（GMT+8）、「魔法の脚本屋」と「達成報酬」のみが残り、他の内容は終了し参加できません。\n\n<Title:脚本の謎>\n1、「脚本の謎」には9つの素材ステージがあり、毎日1つ自動で開放されます。開放後、前提となる特務記録ステージのクリア後に挑戦できます。\n2、各挑戦には60点のエンフェリンを消費し、クリア時にイベント通貨「揺蕩う閃き」と育成素材を獲得できます。本イベントの素材ステージはクリア後すぐにリプレイが可能です。\n3、フレンドの救援や「共鳴：監督の演出指示」を利用すると、より簡単にクリアできます。\n\n<Title:閃きボーナス>\n1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「脚本の謎」ステージ報酬のイベント通貨「揺蕩う閃き」の追加ドロップボーナスが得られます。（リプレイを含む）\n具体的なボーナスは以下の通り：\n・覚醒体「リリー」：\n霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SSR運命の札「痛みを越えて」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n・SR運命の札「35mmの魔法」：\n強化0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体や運命の札の「閃きボーナス」は累計で計算されます。\n\n<Title:共鳴：監督の演出指示>\n1、守秘者は達成報酬を完了することで「演技の心」を獲得できます。\n2、「演技の心」を消費して「共鳴：監督の演出指示」を起動すると、イベントプレイ「脚本の謎」と「特務記録：物語の魔法」で守秘者がより強くなります。\nまた「脚本の謎」の挑戦後に獲得する「揺蕩う閃き」と、同調率の報酬を増加させることができます。\n\n<Title:達成報酬>\n1、達成報酬を完了すると、イベント限定アイコン「銀の鍵の名のもとに：リリー」、イベント通貨「揺蕩う閃き」、シルバーコアを獲得できます。\n2、以下の25の任務を含みます：「脚本の謎」各ステージを1回クリア、各界域の覚醒体を使用し「脚本の謎」を1回/2回クリア、「特務記録：物語の魔法」の各調査ステージを1回クリア、全任務を完了する。\n\n<Title:特務記録>\n1、イベント期間中「特務記録：物語の魔法」が無料で解放できます。\n2、「特務記録：物語の魔法」では、守秘者はストーリー専用「リリー」を含む特殊編成を使用して挑戦します。\n\n<Title:復刻補償>\n1、以前に「特務記録：物語の魔法」を解放した守秘者は、本復刻イベント期間中に再解放時に「揺蕩う閃き」×1000の補償を得られます。\n以前に、イベント限定アイコン「銀の鍵の名のもとに：リリー」を獲得していた場合、再獲得時に自動的に「揺蕩う閃き」×3000に変換されます。\n以前に、共鳴活性材料「演技の心」を獲得していた場合、余剰の「演技の心」を1個獲得するごとに自動的に「薔薇金券」×5000に変換されます。"
  },
