  Activity_71982_ActivityName = {
    Text = "魂の共鳴の贈り物"
  },
  Activity_71982_ActivityPlot = {
    Text = "あなたは校長室へやってきた。\nだが、部屋の中には誰もいなかった。\nどうやらあの手紙はただの悪戯だったらしい。\n部屋を離れようとしたそのとき、視界の端に、贈り物と、そこに貼られたメモが映った。\n——私の愛する君へ。"
  },
  Activity_71983_ActivityName = {
    Text = "運命を覗き見る贈り物"
  },
  Activity_71983_ActivityPlot = {
    Text = "静かな部屋の中でカタカタと音が鳴る。\nあなたは近づいて確認した。\n開け放たれた窓が見えた。\n『招かれざる客』はすでにいないようだ。\n暖かな陽光が机の上の贈り物を照らす。\n端正な筆致が銀色に輝いた。\n——運命がいつもあなたに微笑みますように。"
  },
  Activity_72101_ActivityName = {
    Text = "位相逆転"
  },
  Activity_72101_ActivityPlot = {
    Text = "「みんなに万象牌を遊ばせたい！」\n他の時空の来客が偶然の出来事で位相対人戦の空間に入り込み、元の姿とは大きく異なる形に改造した。\n空間を再び逆転させるために、異なる時空の守秘者が最強者を決め、この「お客様」に挑戦することに。"
  },
  Activity_72101_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は「対人戦」に参加して「達成報酬」の達成を完了し、「魔法のどんぐり」を受け取ることができます。\n2、「魔法のどんぐり」は「回合奇賞」で豊富な報酬と交換でき、イベント限定アイコン「逆転回合：万象牌」、10個のイベント限定表情、「割れた残夢」、「星々の残夢」などが含まれます。\n3、イベント期間中「多次元接続：逆転回合」が無料で開放されます！\n4、イベント期間中、「多次元接続：逆転回合：異界からの客人」をクリアした守秘者は、「対人戦」の対戦背景が期間限定で「逆転回合：意識空間」に変更されます。\n\n<Title:達成報酬>\n1、「達成報酬」には「覚醒体」勝利達成、「運命の札」勝利達成、「キーオーダー」勝利達成、カードプレイ数達成が含まれ、守秘者は達成を完了することで「魔法のどんぐり」を受け取ることができます。\n2、「対人戦」で異なる職業の「覚醒体」を使用して25枚のカードを使用するごとに30個の「魔法のどんぐり」を獲得できます。各職業の「カードプレイ」達成は最大80回まで完了できます。\n3、「覚醒体」達成：各「覚醒体」が「対人戦」で1/3/6/10回の勝利を達成すると10個の「魔法のどんぐり」を獲得できます。\n4、「運命の札」達成：各「運命の札」が「対人戦」で1/3/6回の勝利を達成すると10個の「魔法のどんぐり」を獲得できます。\n5、「キーオーダー」達成：各「キーオーダー」が「対人戦」で1/3/6回の勝利を達成すると10個の「魔法のどんぐり」を獲得できます。\n6、核心課題で一時的に解放された「覚醒体」、「運命の札」、「キーオーダー」は勝利カウントとカードプレイカウントが正常に行われますが、対応する「覚醒体」、「運命の札」、「キーオーダー」を獲得した後に勝利達成報酬を受け取る必要があります。\n\n<Title:回合奇賞>\n1、守秘者は「魔法のどんぐり」を累積して対応する報酬を受け取れ、累積2500「魔法のどんぐり」ですべての核心報酬を獲得し、累積5000「魔法のどんぐり」ですべての報酬を獲得できます！\n2、「逆転回合：異界からの客人」をクリアすると累積100–900「魔法のどんぐり」の報酬が解放され、「逆転回合：逆転万象の瞬間」をクリアすると累積1000–5000「魔法のどんぐり」の報酬が解放されます。\n\n<Title:多次元接続>\n1、イベント期間中「多次元接続：逆転回合」が無料で開放されます。\n2、イベント期間中、「逆転回合：意志を貫く絶対」は「魔法のどんぐり」を1000貯めることで解放されます。\n3、イベント終了後も「多次元接続：逆転回合」の調査進捗は保持され、イベント期間中に解放されなかった場合でも「起点装置」×3を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「多次元接続：逆転回合」をクリアすると「キーオーダー：酒場の扉」を獲得できます。\n\n<Title:イベント時間>\n今回のイベントは3月18日9:00 – 4月1日9:00（GMT+8）の期間のみ開放され、4月1日9:00（GMT+8）以降イベントは終了しますので、各守秘者は「回合奇賞」の報酬を受け取るのを忘れないでください！"
  },
