  },
  Activity_73879_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「暗き胎内」と「達成報酬」を通じて3種類の「胚」を収集し、「聖胎孵化」でアイテム報酬に交換できます。\n交換報酬には、イベント限定SR運命の札「氷河の眠り」、ヘブンズコア、ルミナスコア、賢石の破片、擬態凝晶などが含まれます。\n2、イベント期間中、「達成報酬」の任務を完了するとイベント限定アイコン「銀の鍵の名のもとに：マーフィー」、イベント限定SR運命の札「氷河の眠り」、大量の「胚」を獲得できます。\n\n<Title:イベント期間>\n1、3月10日9:00 – 3月24日9:00（GMT+8）、すべてのイベント内容に参加できます。\n2、3月24日9:00 – 3月31日9:00（GMT+8）、参加できるのは「聖胎孵化」と「達成報酬」のみで、その他の内容は終了し参加できません。\n\n<Title:暗き胎内>\n1、「暗き胎内」には7つのステージがあり、毎日1つ自動で開放されます。\n2、挑戦ごとに120点のエンフェリンを消費し、イベント通貨「無識の胚」、「無欲の胚」、「無我の胚」を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。\n※注意：「リプレイ」機能を使用すると同調率を獲得できません。\n4、フレンドの救援を利用すると、より簡単にクリアできます。\n5、任意の難易度でステージクリア後、超難度が解放されます。初回クリアで大量のイベント通貨報酬を獲得できます。\n6、注意：「超難度」はエンフェリンを消費せず、リプレイ不可で、初回以降は報酬はありません。\n\n<Title:胚ボーナス>\n1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n「暗き胎内」ステージのイベント通貨「無識の胚」「無欲の胚」「無我の胚」に追加ドロップボーナスが得られます。（リプレイを含む）\n\n具体的なボーナスは以下の通り：\n・覚醒体「マーフィー」：\n霊知啓発0/1/2/3以上、ボーナス20％/30％/40％/50％\n\n・SSR運命の札「秘められた誕生」：\n強化0/1/2/3以上、ボーナス20％/30％/40％/50％\n\n・SR運命の札「氷河の眠り」：\n強化0/1/2/3以上、ボーナス20％/30％/40％/50％\n\n2、異なる覚醒体や運命の札の「胚ボーナス」は累計で計算されます。\n3、特に、超難度の初回クリア報酬は「胚ボーナス」の影響を受けません。\n\n<Title:聖胎孵化>\n1、「聖胎孵化」は3月10日9:00 – 3月31日9:00（GMT+8）の期間のみ開放されます。\n2、3月31日9:00（GMT+8）以降、未交換の「胚」は、1つにつき「薔薇金券×40」の比率で回収されますので、守秘者はメールをご確認ください。"
  },
  Activity_73879_BannerText = {
    Text = "期間限定イベント開催中！"
  },
  Activity_74213_ActivityName = {
    Text = "星辰篇1章クリアパス"
  },
  Activity_74213_ActivityPlot = {
    Text = "封印された記憶、過去の行程。追憶の時、敬意を忘れずに。"
  },
  Activity_74340_ActivityName = {
    Text = "逆転回合"
  },
  Activity_74364_ActivityName = {
    Text = "名探偵マニュアル・復刻"
  },
  Activity_74364_ActivityPlot = {
    Text = "平凡なマニュアル。\n名探偵が長年の仕事で得た心得を記録。\n探偵を目指す若者に少しでも役立つことを願っている。"
  },
  Activity_74364_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「幸運倶楽部」のみ参加可能です。"
  },
  Activity_74364_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「月夜伝説」と「達成報酬」を通じて、イベント通貨「勝負チップ」を収集できます。「勝負チップ」は「幸運クラブ」で豪華な報酬と交換可能で、イベント限定SR運命の札「運命ルーレット」、ヘブンズコア、ルミナスコア、賢石の破片、擬態凝晶などがあります。\n2、イベント期間中に「達成報酬」のタスクを完了すると、イベント限定のアイコン「銀の鍵の名のもとに：ライカー」、イベント限定SR運命の札「運命のルーレット」、シルバーコアと大量のイベント通貨「勝負チップ」を獲得できます。\n3、イベント期間中、「特務記録：狩猟楽しい！」が無料で開放されます。\n\n<Title:イベント期間>\n1、9月22日9:00 - 10月6日9:00（GMT+8）、すべてのイベント内容に参加可能です。\n2、10月6日9:00 - 10月13日9:00（GMT+8）、「幸運クラブ」と「達成報酬」のみが残り、他の内容は終了しますので参加できません。\n\n<Title: 月夜伝説>\n1、「月夜伝説」には9つのステージがあり、毎日1つ自動的に開放されます。\n2、毎回の挑戦ではエンフェリン×120を消費し、異なるステージに挑戦することで、異なる素材のドロップを獲得することができます。また、イベント通貨「勝負チップ」を獲得。\n3、今回のイベントのステージは直接戦闘の素材ステージであり、クリア後にリプレイ可能です！毎回の「リプレイ」にエンフェリン×120が消費されます。\n4、注意：リプレイ機能を使用する際、同調率を獲得することはできません。\n\n<Title: チップボーナス>\n1、守秘者が特定の覚醒体または運命の札を持っている（出陣は不要）場合、「月夜伝説」のステージタスク報酬の「勝負チップ」に追加ドロップ加算があります（リプレイも含む）。具体的な加算は以下の通りです：\n・覚醒体「ライカー」：霊知啓発0/1/2/3以上、加算20%/30%/40%/50%\n・SSR運命の札「幸運の時」：強化0/1/2/3以上、加算20%/30%/40%/50%\n・SR運命の札「運命のルーレット」：強化0/1/2/3以上、加算20%/30%/40%/50%\n2、異なる覚醒体または運命の札の「チップボーナス」は累積されます。\n3、特別に、超難度の初回クリア報酬は「チップボーナス」の影響を受けません。\n\n<Title: 幸運クラブ>\n1、「幸運クラブ」は9月22日9:00 - 10月13日9:00（GMT+8）の期間のみ開放されます。\n2、10月13日9:00（GMT+8）以降、残り未交換の「勝負チップ」は、1つの交換あたり「薔薇金券」×40の割合で回収されますので、守秘者はメールを確認してください。\n\n<Title:特務記録>\n1、イベント期間中「特務記録：狩猟楽しい！」が無料で開放されます。\n2、イベント終了後、「特務記録：狩猟楽しい！」の調査進捗は保持されます。イベント期間中に「特務記録：狩猟楽しい！」を開放していない場合でも、イベント終了後に「起点装置」×7を消費して開放可能です。\n3、イベント期間中かどうかに関わらず、「特務記録：狩猟楽しい！」をクリアすると「キーオーダー：一発の銃声」を獲得できます。\n\n<Title:復刻補償>\n1、以前に「特務記録：狩猟楽しい！」を開放済みの守秘者は、今回の復刻イベント期間中に再度開放した際に「勝負チップ」×700の補償を獲得できます。\n2、以前にイベント限定アイコン「銀の鍵の名のもとに：ライカー」を獲得済みの守秘者は、重複獲得時に自動的に「無形者の招待状」×1に変換されます。\n"
  },
