    Text = "イベントルール：\n1、「異世界紀行」で指定された紀行任務を完了すると、報酬を受け取れます。\n2、「異世界紀行」は恒常的に開放されます。\n3、「上級紀行」を解放すると、任務完了後に追加報酬を受け取れます。\n\n注意：「上級紀行」は本イベント内のみ有効です。慎重にご活用ください。"
