  Activity_77970_ActivityTips = {
    Text = "<Title:イベントルール>\n・「御子・白夜」イベント開催中、守秘者はポリュクスを含む専用の編成を使用し、試遊ステージを体験できます。\n・試遊ステージでは、編成中の覚醒体の調整はできません。\n<Title:イベント報酬>\n・初めて試遊ステージをクリア後、イベント画面で報酬を受け取れます。"
