  Activity_78652_ActivityPlot = {
    Text = "「Hysteria」——別名ヒステリー症。\nこの時代、それはすなわち死を意味した。\n\nだが幸運にも、ミサゴの科学者と調査員もまた、狂気の沙汰ではなかった。彼らは、この難題を克服することを決意したのだ。"
