  },
  Activity_78652_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は期間限定の「記憶の収集」、「エッジストレージ」、「達成報酬」を通じてイベント通貨「記憶パズル」を収集できます。「記憶パズル」は「人格解析」で商品を購入するために使用でき、イベント限定SR運命の札「銀鱈の決意」、ルミナスコア、ヘブンズコアなどが含まれます。\n2、イベント期間中、「特務記録：静寂の裂殖」が期間限定で無料解放され、イベント達成でイベント限定アイコン「銀の鍵の名のもとに：「24」」を獲得できます！\n\n<Title:イベント期間>\n1、4月21日15:00 - 5月5日15:00、すべてのイベントプレイに参加可能。\n2、5月5日15:00 - 5月12日15:00、「人格解析」と達成報酬のみ参加可能。\n\n<Title:記憶の収集>\n1、「記憶の収集」は5つのステージを含み、2日ごとに1つ自動的に開放されます。\n2、挑戦するたびに120ポイントのエンフェリンを消費し、成功するとイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「リプレイ」機能が解放されます。注意：使用時に同調率は獲得できません。\n4、フレンドの救援と「共鳴：解離性症候群」を使用して、より簡単にクリアできます。\n\n<Title:理性ボーナス>\n1、守秘者が特定の覚醒体または運命の札を持っていると、「記憶の収集」ステージの報酬で「記憶パズル」の追加ドロップボーナスを得られます。具体的なボーナスは以下の通り：\n・覚醒体「24」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%。\n・SSR運命の札「異形の捕食」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%。\n・SR運命の札「銀鱈の決意」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%。\n2、異なる覚醒体または運命の札の「理性ボーナス」は累積されます。\n3、特に、超難度難易度の初回クリア報酬は「理性ボーナス」の影響を受けません。\n\n<Title:共鳴：解離性症候群>\n1、守秘者はイベント達成で「分裂の心」を獲得できます。\n2、「分裂の心」を消費して「共鳴：解離性症候群」を発動すると、以下のボーナスを得られます：\n（1）守秘者がイベントプレイ「記憶の収集」と「特務記録：静寂の裂殖」で強化され、挑戦がより簡単になります。\n（2）「記憶の収集」挑戦後の報酬が向上します。\n（3）イベントプレイ「エッジストレージ」を発動します。\n\n<Title:エッジストレージ>\n1、共鳴「診断：人格分裂」を発動後、毎時自動で60「記憶パズルα」を獲得し、最大25時間まで蓄積可能。\n2、共鳴「認知同調」を発動後、毎時自動で30「記憶パズルβ」を獲得し、最大25時間まで蓄積可能。\n\n<Title:特務記録>\n1、イベント期間中、「特務記録：静寂の裂殖」が無料で解放されます。\n2、イベント終了後も「特務記録：静寂の裂殖」の調査進捗は保持され、イベント期間中に未完了の調査を完了すると、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「特務記録：静寂の裂殖」を解放していない場合、イベント終了後も「起点装置」×7を消費して解放できます。\n3、イベント期間中であろうとなかろうと、「特務記録：静寂の裂殖」をクリアすると「キーオーダー：すべての彼女」を獲得できます。\n\n<Title:復刻補償>\n1、以前に「特務記録：静寂の裂殖」を解放した守秘者は、今回の復刻イベント期間中に再解放すると「記憶パズルα」×700の補償を受け取れます。\n2、以前にイベント限定アイコン「銀の鍵の名のもとに：「24」」を獲得した守秘者は、再度獲得すると自動的に1つの「無形者の招待状」に変換されます。\n3、以前に共鳴発動素材「分裂の心」を獲得した守秘者は、余分な「分裂の心」を1つ獲得するごとに自動的に「薔薇金券」×5000に変換されます。"
  },
  Activity_78652_BannerText = {
    Text = "期間限定イベント開催中！"
  },
  Activity_78722_ActivityName = {
    Text = "暗潮虫鳴・期間限定予約"
