  Activity_78722_ActivityTips = {
    Text = "<Title: 暗潮虫鳴・限定予約>\n・この限定予約イベントは全8種類のギフトパッケージを含みます。\n初回ギフトは無料でお受け取り可能です。2～8番目のギフトは「暗潮虫鳴・限定予約」ご購入後にのみお受け取りいただけます。\n　\n・「暗潮虫鳴・限定予約」ご購入後は直ちに第2ギフトの特典をお受け取りいただけますが、以降のギフトは一定期間後にお受け取り可能になります。\n　\n・「暗潮虫鳴・限定予約」ご購入には時間制限があり、期限を過ぎますと再購入できません。4月7日15:00までに購入をご検討ください。"
  },
