  Activity_81019_ActivityName = {
    Text = "掃除の奇旅"
  },
  Activity_81019_ActivityPlot = {
    Text = "夢幻のカダスを駆け巡り、ご主人様のためにゴミを片付けるのは誰？\nガレンだよ〜ガレンなの！\n融蝕をお掃除〜夢境を換気〜次元を消毒〜全部ピカピカにするよ〜\nだってお掃除に関しては、ガレンはプロなんだから！\nご主人様もやってみる？ガレンがお掃除の極意を、余すところなくご主人様に教えてあげるよ！"
  },
  Activity_81019_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密保持者は「掃除進捗」に参加して「清掃道具」を受け取ることができます。\n2、「清掃道具」が一定数量に達すると、「除塵手当」で豊富な報酬を受け取ることができます。イベント限定アイコン「清掃マスター」、銀芯、無垢の芯、賢石の欠片などが含まれます。\n\n<Title: 掃除進捗>\n1、「掃除進捗」には複数の異なるタイプの清掃任務が含まれており、秘密保持者は清掃任務を完了することで「清掃道具」を受け取ることができます。毎日すべてのタイプの清掃任務を完了すると、追加の報酬もあります！\n2、イベント期間中、初めて1種類の清掃任務を完了するたびに隠しストーリーが再生されます。\n3、「掃除進捗」はイベント期間中、毎日9:00（GMT+8）にリセットされます。\n\n<Title: 除塵手当>\n1、秘密保持者は「清掃道具」を累積することで対応する報酬を受け取ることができます。「清掃道具」が1000に達するごとに豊富な物資報酬を受け取ることができ、累計10000「清掃道具」に達すると掃除奇旅専用アイコン「清掃マスター」を獲得できます。\n\n<Title:ガレンのお礼>\nイベント期間中、「ガレンのお礼」でログインしてガレンが秘密保持者に用意したお礼を受け取ることができます！\n\n<Title:イベント期間>\n本イベントは4月28日 9:00 – 5月12日 9:00（GMT+8）の期間のみ開放されます。5月12日 9:00（GMT+8）以降イベントは終了しますので、秘密保持者の皆様は「除塵手当」の報酬を忘れずに受け取ってくださいね！"
  },
