  },
  Activity_81178_ActivityName = {
    Text = "暴雨の中で揺れ動く"
  },
  Activity_81178_ActivityPlot = {
    Text = "激しい雨が灰色の空から斜めに降り注ぎ、海面をバチバチと叩きつける。\n容赦ない雷光が轟き渡り、海面の下に潜む果てしない恐怖の到来を告げる。\n輝かしきノーチラス号は、よちよち歩きの赤子のように、荒れ狂う波濤の中で脆く揺れ動く。\n誰も自らの運命がどうなるか知る由もない。気まぐれな大海がその怒りを見せつけた時、人々はようやく、自分がいかにちっぽけな存在であるかを悟るのだ。"
  },
  Activity_81178_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「船員の秘宝」のみ参加可能です。"
  },
  Activity_81178_ActivityTips = {
    Text = "<Title:イベント概要>\n イベント期間中、秘密保持者は期間限定プレイ「深海漂流」と「実績報酬」を通じてイベント通貨「信号旗」を収集できます。「信号旗」は「船員の秘宝」で報酬と交換でき、イベント限定SR運命の輪「海上の先導者」、流明の芯、無垢の芯、賢石の欠片、擬態凝晶などが含まれます。\n\n<Title:深海漂流>\n1、「深海漂流」には探索不要で直接戦闘する素材ステージが9つ含まれ、毎日1つずつ開放されます。\n2、挑戦するたびに「霊啡肽」×120を消費し、挑戦成功で育成素材とイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能がアンロックされます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、校友会の助っ人を使用して、より簡単にクリアすることができます。\n\n<Title:信号旗ボーナス>\n1、秘密保持者が特定の覚醒体または運命の輪を所持している場合（編成不要）、「深海漂流」ステージ任務報酬の「信号旗」に追加のドロップボーナスが付与されます（再現を含む）。具体的なボーナスは以下の通りです：\n·覚醒体「クペルサント」：啓霊0/1/2/3以上、ボーナス20％/30％/40％/50％\n·SSR運命の輪「聖火の中の導き」：重位0/1/2/3以上、ボーナス20％/30％/40％/50％\n·SR運命の輪「海上の先導者」：重位0/1/2/3以上、ボーナス20％/30％/40％/50％\n2、異なる覚醒体または運命の輪の「信号旗ボーナス」は加算方式で計算されます。 \n3、特別に、狂乱難易度の初回クリア報酬は上記ボーナスの影響を受けません。\n\n<Title: 船員の秘宝>\n1、「旗を納品」するたびに750「信号旗」を消費し、「船員の秘宝」の中からランダムで5つのアイテム報酬を獲得します。\n2、「船員の秘宝」のアイテム報酬は「特殊アイテム」と「通常アイテム」の2種類に分かれ、リセット時に特殊アイテム報酬の残り数量を上限まで回復できます。具体的なルールは以下の通りです：\n（1）最初の5回のリセット：「特殊アイテム」の残り数量がなくなった後、秘密保持者はリセットを選択でき、リセット後は「特殊アイテム」と「通常アイテム」の残り数量が上限まで回復されます。また、交換を続けることも可能で、「通常アイテム」の残り数量もなくなった場合は、リセットを行わないと交換を続けることができません。\n（2）6回目以降のリセット：「通常アイテム」の残り数量がなくなった後にのみリセットが可能で、リセットにより「通常アイテム」の残り数量が上限まで回復されますが、「特殊アイテム」はリセットされません。\n\n<Title:イベント期間>\n1、5月5日 9:00 – 5月19日 9:00（GMT+8）、イベント概要のすべてのコンテンツに参加可能です。\n2、5月19日 9:00 – 5月26日 9:00（GMT+8）、「船員の秘宝」と「実績報酬」のみ利用可能で、その他のコンテンツは終了し参加できません。\n3、5月26日 9:00（GMT+8）以降、未交換の「信号旗」は1個につき「薔薇金券」×40の比率で回収されます。秘密保持者の皆様はメールをご確認ください。"
  },
  Activity_81178_BannerText = {
    Text = "期間限定イベント開催中！"
  },
  Activity_81179_ActivityName = {
    Text = "最後の誘導"
  },
  Activity_81771_ActivityName = {
    Text = "神国を窺う影"
  },
  Activity_81771_ActivityPlot = {
    Text = "神国の聖輝を窺い見た者はいない。しかし、偶然漏れ出たその真相から、人々は神国の影を感じ取ることができる。\nそれはそこにある、ずっとそこにある。そして無数の敬虔なる者たちが、それを真に降臨させるだろう。\nどれほど深い罪を犯すことになろうとも、その代償を厭わずに。"
  },
  Activity_81771_ActivityStageEndContent = {
    Text = "イベント終了"
  },
  Activity_81771_ActivityTips = {
    Text = "<Title: 異動海潮>\n·「異動海潮」には7つのステージがあり、イベント初日に最初の3つが開放され、以降3日ごとに1つずつ開放されます。各ステージにはそれぞれ異なる豪華報酬があります！\n·各種「異動海潮」には大量の集群が存在し、いずれかの秘密の守り手がある種類の集群に勝利するたびに、その種類の「異動海潮」の集群数が1減少します。その種類の異動海潮のすべての集群が殲滅されると、該当ステージは閉鎖され、再挑戦できなくなります。\n·各秘密の守り手は1日最大20回まで「異動海潮」集群を撃退でき、イベント期間中は毎日9:00（GMT+8）に回数がリセットされます。\n·各ステージでは異なる造物が提供され、強力なバフを得ることができます。\n·すべてのステージで助っ人の選択が必須です。イベント全体を通じて、相互フォローしている秘密の守り手はそれぞれ1回のみ助っ人として参加できます。\n·秘密の守り手は調査行動2–9を完了している必要があります。\n\n<Title: レベル補正>\n·「神国を窺う影：異動海潮」にはレベル補正メカニズムがあり、すべての秘密の守り手が共に侵攻に対抗できるようになっています！\nレベル補正ルールは以下の通りです：\n ·調査チーム内のレベル60未満の覚醒体は、今回のチャレンジ中レベル60まで補正されます。\n·調査チーム内のスキルレベル5未満の覚醒体は、今回のチャレンジ中スキルレベル5まで補正されます。\n·調査チーム内の「狂気の予兆」がレベル6未満の覚醒体は、今回のチャレンジ中レベル6まで補正されます。\n·調査チーム内の「霊塑適性」がレベル5未満の覚醒体は、今回のチャレンジ中レベル5まで補正されます。\n ·秘密の守り手のレベルが60未満の場合、今回のチャレンジ中レベル60まで補正されます。\n\n<Title:期間限定ミッション>\n·イベント期間中、累計30回異動海潮を撃退すると期間限定ミッションが完了し、「簡易幻衣デザイン券（第一期）」×1を獲得できます！\n·5月26日 9:00〜6月9日 9:00（GMT+8）の期間中、「ショップ：幻衣オーダー」で「簡易幻衣デザイン券（第一期）」を使用してシンプル幻衣と交換できます。\n·「簡易幻衣デザイン券（第一期）」のその他の入手方法については、コミュニティやお知らせをご確認ください。"
  },
  Activity_81771_BannerText = {
    Text = "特別イベント期間限定開催！"
  },
