  Activity_84175_ActivityName = {
    Text = "復学紀行"
  },
  Activity_84175_ActivityTips = {
    Text = "イベントルール：\n1、守秘者が指定の紀行任務を完了すると、「復律紀行」で報酬を受け取れます。\n2·任務は複数の区分に分かれており、イベントの開始後に毎日1区分が解放されます。\n3、「復律紀行」を解放すると、任務完了後に追加報酬を受け取れます。\n4、注意：このイベントで解放された「復律紀行」は、本イベント内でのみ有効です。守秘者は適切かつ理性的に消費してください。"
  },
  Activity_84176_ActivityName = {
    Text = "復学紀行"
  },
  Activity_84176_ActivityTips = {
    Text = "イベントルール：\n1、守秘者が指定の紀行任務を完了すると、「時絜紀行」で報酬を受け取れます。\n2·任務は複数の区分に分かれており、イベントの開始後に毎日1区分が解放されます。\n3、「時絜紀行」を解放すると、任務完了後に追加報酬を受け取れます。\n4、注意：このイベントで解放された「時絜紀行」は、本イベント内でのみ有効です。守秘者は適切かつ理性的に消費してください。"
  },
  Activity_89008_ActivityName = {
    Text = "回帰次元の追随"
  },
  Activity_89008_ActivityPlot = {
    Text = "彼女は無数の次元、無数の世界を渡り歩き、無数の希望と絶望を経験してきた。しかし、彼女は足を止めない。なぜなら、自分の目的地を明確に知っているから――あなたのいる場所を。"
  },
  Activity_89008_ActivityTips = {
    Text = "<Title:概要>\n1、イベント期間中、秘密保持者は毎日ログイン後、「回帰次元の追随」で当日のログインボーナスを受け取ることができます。\n2、報酬は秘密保持者の累計ログイン日数に応じて順次解放されます。当日のログインボーナスは9時（GMT+8）にリセットされます。\n\n<Title:期間限定任務>\n·イベント期間中、累計ログイン7日で期間限定任務を達成し、「シンプル幻衣デザイン券（第一期）」×1を獲得できます！\n·5月26日 9:00〜6月9日 9:00（GMT+8）の期間中、「ショップ：幻衣オーダー」で「シンプル幻衣デザイン券（第一期）」を使用してシンプル幻衣と交換できます。\n·「シンプル幻衣デザイン券（第一期）」のその他の入手方法はコミュニティやお知らせでご確認ください。"
  },
  Activity_89008_BannerText = {
    Text = "ログインで大量の無垢なるコアをゲット"
  },
  Activity_89576_ActivityName = {
    Text = "希望よ、再び芽吹け"
  },
  Activity_89576_ActivityPlot = {
    Text = "毎日ログインで記念限定SSR命輪「湮土での再誕生」を合計16個受け取り可能！"
  },
  Activity_89576_ActivityTips = {
    Text = "<Title:概要>\n世界は崩壊しつつある。このような世界では、絶望が常態であり、苦痛が常態である。私は慣れなければならない。しかし…………温もりはまだ私の心臓に潜み、胸を突き破って現れる時を待っている。\n\n<Title:イベントルール>\n·イベント期間中、秘密保持者は毎日ログイン後、「希望よ、再び芽吹け」で記念限定SSR運命の輪「湮土より再生す」を受け取ることができます。合計16回受け取り可能です。\n·報酬は秘密保持者の累計ログイン日数に応じて順次解放されます。当日のログインボーナスは9時（GMT+8）にリセットされます。"
  },
  Activity_89576_BannerText = {
    Text = "限定SSR命輪無料受取"
  },
  Activity_89729_ActivityName = {
    Text = "サブステージ無料解放"
  },
  Activity_89730_ActivityName = {
    Text = "鏡に映る囚人"
  },
  Activity_89730_ActivityPlot = {
    Text = "飛ぶ鳥よ、お前の足にはなぜ断ち切れた枷があるのか？\n飛ぶ鳥よ、お前はなぜ高空の上で孤独に鳴くのか？\n荊棘を振り払い、囚われの籠から逃れ、お前は翼を広げ果てしない黄砂を越えた。だがお前の悲しい鳴き声は止むことがない。一体誰が、お前の探し求める忠実な旅の伴なのか？一体どこが、お前の探し求める真の故郷なのか？"
  },
  Activity_89730_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「求知の願い」のみ参加可能です。"
  },
  Activity_89730_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密保持者は期間限定プレイ「飛翔青空」、「夢境巡梭」および「実績報酬」を通じてイベント通貨「常識の書」、「数理の書」、「文学の書」を収集できます。「常識の書」、「数理の書」、「文学の書」は「求知の願い」で商品の購入に使用でき、イベント限定SR運命の輪「孤羽」、流明の芯、無垢の芯などが含まれます。\n2、イベント期間中、「異夢視界：天の彼方·上」が期間限定で無料解放されます。イベント実績を達成すると、イベント限定アイコン「銀鍵の名の下に：カストル」も獲得できます！\n\n<Title:イベント期間>\n1、6月2日 9:00 – 6月16日 9:00（GMT+8）、すべてのイベントプレイに参加可能。\n2、6月16日 9:00 – 6月23日 9:00（GMT+8）、「求知の願い」と実績報酬のみ参加可能。\n\n<Title:飛翔青空>\n1、「飛翔青空」には7つのステージがあり、1日ごとに1つ自動開放されます。\n2、挑戦ごとに「霊啡肽」×120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能が解放されます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、校友会の助っ人を使用して、より簡単にクリアすることができます。\n\n<Title:求知の願い>\n「求知の願い」には3つのショップがあり、開放時間は以下の通りです：\n·「一般選修課」：6月2日 9時開放。\n·「科学選修課」：6月4日 9時開放。\n·「文学選修課」：6月6日 9時開放。\nショップ内で商品を選択して直接購入できます。\n\n<Title:イベントボーナス>\n1、秘密保持者が特定の覚醒体または運命の輪を所持している場合（出撃不要）、「飛翔青空」ステージ任務報酬の「常識の書」、「数理の書」、「文学の書」に追加のドロップボーナスが適用されます。具体的なボーナスは以下の通りです：\n·覚醒体「カストル」：啓霊0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SSR運命の輪「耐えられぬ自由」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SR運命の輪「孤羽」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%。\n2、異なる覚醒体または運命の輪の「イベントボーナス」は累積方式で計算されます。\n3、特別に、狂乱難易度の初回クリア挑戦報酬は「イベントボーナス」の影響を受けません。\n\n<Title:夢境巡梭>\n1、毎時間自動で60「常識の書」を獲得し、最大25時間分まで蓄積できます。\n\n<Title:異夢視界>\n1、イベント期間中、「異夢視界：天の彼方·上」を無料で解放できます。\n2、イベント終了後、「異夢視界：天の彼方·上」の調査進捗は保持されます。イベント期間中に未完了の調査イベントを完了した場合も、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「異夢視界：天の彼方·上」を解放しなかった場合、イベント終了後も「現実起点」×7を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「異夢視界：天の彼方·上」をクリアすると「鍵令：錯位の運命」を獲得できます。"
  },
  Activity_89730_BannerText = {
    Text = "期間限定イベント開催中！"
  },
  Activity_89899_ActivityName = {
    Text = "幻衣の縫製"
  },
  Activity_89899_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、守秘者は「モノクル」を使用して抽選ができます。抽選ごとに必要な「モノクル」の数が増加します。\n\n2、5回目の抽選から銀枢幻衣を獲得するチャンスがあります。\n最大10回の抽選で、必ず今回の銀枢幻衣を獲得できます。\n\n3、イベント終了後、残った「モノクル」は自動的にプラチナジェルに変換されます。"
  },
  Activity_89899_BannerText = {
    Text = "抽選イベント期間限定開催！"
  },
  Activity_90052_ActivityName = {
    Text = "腐敗の脳"
  },
  Activity_90052_ActivityTips = {
