  },
  Activity_90861_ActivityTips = {
    Text = "<Title: 共役の運命>\n·今回の期間限定紀行には8つのギフトパックが含まれ、最初のギフトパックは直接無料で受け取ることができ、第2〜8のギフトパックは「共役の運命」を購入後に受け取ることができます。\n·「共役の運命」を購入後、すぐに第2のギフトパック報酬を受け取ることができます。後続のギフトパックはそれぞれ一定時間経過後に受け取ることができます。\n·4月20日 9：00までに「共役の運命」を購入すると、追加報酬として専用アイコン「運命の織り手」、「無形者の招待状」×10を獲得できます！4月20日 9：00以降に購入した場合、期間限定専用報酬は獲得できなくなります。 \n· 購入後、今回の期間限定紀行の持続期間は永久となり、すべてのギフトパックを受け取った翌日にイベントが終了します。\n·「共役の運命」の購入には期間制限があり、期限を過ぎると購入できなくなります。秘密保持者の皆様は5月18日 9：00までにご検討の上ご購入ください。"
  },
