  Activity_90862_ActivityTips = {
    Text = "<Title: 仮テキスト>\n·今回の期間限定先行購入イベントには8つのギフトパックが含まれ、最初のギフトパックは直接無料で受け取ることができ、第2〜8のギフトパックは「仮テキスト」を購入後に受け取ることができます。\n·「仮テキスト」を購入後、すぐに第2のギフトパック報酬を受け取ることができます。後続のギフトパックはそれぞれ一定時間経過後に受け取ることができます。\n·「仮テキスト」の購入には期間制限があり、期限を過ぎると購入できなくなります。秘密保持者の皆様は4月7日9：00までにご検討の上ご購入ください。"
