  Activity_90863_ActivityName = {
    Text = "万願擬造"
  },
  Activity_90863_ActivityTips = {
    Text = "<Title: 万願擬造>\n·今回の期間限定旅程には8つのギフトパックが含まれており、最初のギフトパックは直接無料で受け取れます。第2～8のギフトパックは「万願擬造」を購入後に受け取ることができます。\n·「万願擬造」購入後、すぐに第2のギフトパック報酬を受け取れます；以降のギフトパックはそれぞれ一定時間待機後に受け取ることができます。\n·8月24日 9：00前に「万願擬造」を購入すると、追加報酬として専用アバター「策略進行中」、「無形者の招待状」×10が獲得できます！8月24日 9：00以降の購入では期間限定専属報酬は獲得できません。\n·「万願擬造」の購入には期限があり、期限を過ぎると購入できなくなります。守秘者は9月21日 9：00前にご検討の上ご購入ください。購入後、今回の期間限定旅程の終了時間が9月28日 9：00まで延長され、各守秘者が報酬を受け取るための十分な時間が確保されます！"
  },
  Activity_90863_BannerText = {
