  },
  Activity_90864_ActivityTips = {
    Text = "<Title: 頭蓋庭園の輓歌·期間限定紀行>\n·今回の期間限定紀行には8つのギフトパックが含まれ、最初のギフトパックは直接無料で受け取ることができ、第2〜8のギフトパックは「頭蓋庭園の輓歌·期間限定紀行」を購入後に受け取ることができます。\n·「頭蓋庭園の輓歌·期間限定紀行」を購入後、すぐに第2のギフトパック報酬を受け取ることができます。後続のギフトパックはそれぞれ一定時間経過後に受け取ることができます。\n·7月21日9：00までに「頭蓋庭園の輓歌·期間限定紀行」を購入すると、追加報酬として専用アイコン「永夜の飢えた凝視」、「無形者の招待状」×10を獲得できます！7月21日9：00以降に購入した場合、期間限定専用報酬は獲得できなくなります。\n·「頭蓋庭園の輓歌·期間限定紀行」の購入には期間制限があり、期限を過ぎると購入できなくなります。秘密保持者の皆様は8月18日9：00までにご検討の上ご購入ください。"
