  Activity_94859_ActivityTips = {
    Text = "イベントルール：\n1、秘密の番人が指定の紀行任務を完了すると、「夏日紀行」で報酬を受け取ることができます。\n2、「上級紀行」をアンロックすると、任務完了時に追加報酬を受け取ることができます。\n3、今回の「上級紀行」の購入には期限があり、期限を過ぎると購入できなくなります。秘密の番人の皆様は10月6日 9：00までに計画的にご購入ください。\n4、ご注意：本イベントでアンロックした「上級紀行」は本イベントでのみ有効です。秘密の番人の皆様は計画的にご利用ください。"
