  Activity_94860_ActivityPlot = {
    Text = "夏、海辺、眩い太陽、そして多くの見慣れた顔ぶれ。\n黒陽の照らす下、すべてを忘れ、あらゆる幻想を満たすこの狂宴の美夢に溺れよう。"
  },
  Activity_94860_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、「異夢視界：さよならネバーランド」が期間限定で無料解放！\n2、イベント期間中、累計ログイン7日で「真夏の狂宴」から「流明の芯」×10を獲得可能。7日目には限定対戦アイコン「バレーボール『大将』」を追加で獲得できます。\n\n<Title:イベント期間>\n1、9月1日 9:00 – 10月6日 9:00（GMT+8）、すべてのイベントに参加可能。\n\n<Title:異夢視界>\n1、イベント期間中、「異夢視界：さよならネバーランド」を無料で解放できます。\n2、イベント終了後、「異夢視界：さよならネバーランド」の調査進捗は保持されます。イベント期間中に未完了の調査イベントを完了した場合も、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「異夢視界：さよならネバーランド」を解放しなかった場合、イベント終了後も「現実起点」×7を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「異夢視界：さよならネバーランド」をクリアすると「鍵令：定格の仲夏の記念」を獲得できます。"
  },
  Activity_94860_BannerText = {
