  Activity_95190_ActivityName = {
    Text = "サブステージ無料解放"
  },
  Activity_95191_ActivityName = {
    Text = "降り注ぐ無数の輝き"
  },
  Activity_95191_ActivityPlot = {
    Text = "彼らは永遠に忘れぬ歌を高らかに唱え、永遠に消えぬ主を迎える。\n主は万千の輝光を携え、極天より墜ち、永世不滅の栄光を語る。\n主が降臨する時、琥珀色の光が世界を覆った。\nこれは主が世界に贈る葬礼。"
  },
  Activity_95191_ActivityStageEndContent = {
    Text = "イベントは終了しました。現在は「隠密の拠点」のみ参加可能です"
  },
  Activity_95191_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密保持者は期間限定プレイ「燼滅追猟」、「無紛の宴」および「実績報酬」を通じてイベント通貨「富の」印「」、「死の」印「」、「戦争の」印「」を収集できます。「富の」印「」、「死の」印「」、「戦争の」印「」は「隠密の拠点」で商品の購入に使用でき、イベント限定SR運命の輪「迫りくる太陽」、流明の芯、無垢の芯などが含まれます。\n2、イベント期間中、「不朽極昼」が期間限定で無料解放されます。イベント実績を達成すると、イベント限定アイコン「銀鍵の名の下に：ケティグラ」も獲得できます！\n\n<Title:イベント期間>\n1、8月18日 9:00 – 9月1日 9:00（GMT+8）、すべてのイベントプレイに参加可能。\n2、9月1日 9:00 – 9月8日 9:00（GMT+8）、「隠密の拠点」と実績報酬のみ参加可能。\n\n<Title:燼滅追猟>\n1、「燼滅追猟」には7つのステージがあり、1日ごとに1つ自動開放されます。\n2、挑戦ごとに「霊啡肽」×120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能が解放されます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、校友会の助っ人を使用して、より簡単にクリアすることができます。\n\n<Title:隠密の拠点>\n「隠密の拠点」には3つのショップがあり、開放時間は以下の通りです：\n·「蔵品宝庫」：8月18日 9時開放。\n·「委託密室」：8月20日 9時開放。\n·「作戦営帳」：8月22日 9時開放。\nショップ内で商品を選択して直接購入できます。\n\n<Title:イベントボーナス>\n1、秘密保持者が特定の覚醒体または運命の輪を所持している場合（出撃不要）、「燼滅追猟」ステージ任務報酬の「富の」印「」、「死の」印「」、「戦争の」印「」に追加のドロップボーナスが適用されます。具体的なボーナスは以下の通りです：\n·覚醒体「ケティグラ」：啓霊0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SSR運命の輪「琥珀色の死」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SR運命の輪「迫りくる太陽」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%。\n2、異なる覚醒体または運命の輪の「イベントボーナス」は累積方式で計算されます。\n3、特別に、狂乱難易度の初回クリア挑戦報酬は「イベントボーナス」の影響を受けません。\n\n<Title:無紛の宴>\n1、毎時間自動で60「富の」印「」を獲得し、最大25時間分まで蓄積できます。\n\n<Title:意識潜游>\n1、イベント期間中、「不朽極昼」を無料で解放できます。\n2、イベント終了後、「不朽極昼」の調査進捗は保持されます。イベント期間中に未完了の調査イベントを完了した場合も、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「不朽極昼」を解放しなかった場合、イベント終了後も「現実起点」×3を消費して解放できます。\n3、イベント期間中かどうかに関わらず、「意識潜游：不朽極昼」をクリアすると「鍵令：沈まぬ太陽」を獲得できます。"
  },
  Activity_95191_BannerText = {
    Text = "期間限定イベント開催中！"
  },
  Activity_95492_ActivityName = {
    Text = "君王の褒賞"
  },
  Activity_95492_ActivityPlot = {
    Text = "彼は寛大で、善良で、慈悲深い君主であり、死の国を統べている。ようこそ、見知らぬ未死の者よ。お前の芳しく馥郁たる香りは既に彼の寵愛を勝ち取った。この褒賞を受け取るがよい。この城の門は永遠にお前のために開かれている。"
  },
  Activity_95492_ActivityTips = {
    Text = "<Title:概要>\n1、イベント期間中、秘密保持者は毎日ログイン後、「君王の褒賞」で当日のログインボーナスを受け取ることができます。\n2、報酬は秘密保持者の累計ログイン日数に応じて順次解放されます。当日のログインボーナスは9時（GMT+8）にリセットされます。\n"
  },
  Activity_95492_BannerText = {
