  Activity_95977_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「王邸のレストラン」のみ参加可能です。"
  },
  Activity_95977_ActivityTips = {
    Text = "<Title:イベント概要>\nイベント期間中、秘密保持者は期間限定プレイ「噬霊の饗」および「実績報酬」を通じてイベント通貨を収集できます。イベント通貨は「王邸レストラン」で交換に使用でき、道具報酬を獲得できます。イベント限定SR運命の輪「珍馐」、賢者の石、無垢の芯、流明の芯などが含まれます。\n\n<Title:イベント期間>\n1、7月21日 9:00 – 8月4日 9:00（GMT+8）、すべてのイベント内容に参加可能。\n2、8月4日 9:00 – 8月11日 9:00（GMT+8）、「王邸レストラン」と「実績報酬」のみ保持され、その他の内容は終了し参加不可。\n\n<Title:噬霊の饗>\n1、「噬霊の饗」には5つのステージがあり、2日ごとに1つ自動開放されます。\n2、挑戦ごとに「霊啡肽」×120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能が解放されます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、校友会の助っ人を使用して、より簡単にクリアすることができます。\n\n<Title:イベントボーナス>\n1、秘密保持者が特定の覚醒体または運命の輪を所持している場合（出撃不要）、「噬霊の饗」ステージ任務報酬の「腐敗した手骨」に追加のドロップボーナスが適用されます（再現を含む）。具体的なボーナスは以下の通りです：\n·覚醒体「デュルセイン」：啓霊0/1/2/3以上、ボーナス20%/30%/40%/50%\n·SSR運命の輪「安息の口づけ」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%\n·SR運命の輪「珍馐」：重位0/1/2/3以上、ボーナス20%/30%/40%/50%\n2、異なる覚醒体または運命の輪の「イベントボーナス」は累積方式で計算されます。\n3、特別に、狂乱難易度の初回クリア挑戦報酬は「イベントボーナス」の影響を受けません。\n\n<Title:王邸レストラン>\n1、「報告提出」ごとに750「腐敗した手骨」を消費し、「王邸レストラン」の5つのアイテム報酬からランダムに獲得します。\n2、「王邸レストラン」のアイテム報酬は「特殊アイテム」と「通常アイテム」の2種類に分かれます。リセット時に特殊アイテム報酬の残数を上限まで戻すことができます。具体的なルールは以下の通りです：\n（1）最初の5回のリセット：「特殊アイテム」の残数がなくなった後、秘密保持者はリセットを選択でき、リセット後は「特殊アイテム」と「通常アイテム」の残数が上限まで戻ります。リセットせずに交換を続けることも可能で、「通常アイテム」の残数もなくなった場合、リセットを行う必要があります。\n（2）6回目以降のリセット：「通常アイテム」の残数がなくなった後にのみリセット可能で、リセットにより「通常アイテム」の残数が上限まで戻りますが、「特殊アイテム」はリセットされません。\n3、8月11日 9:00（GMT+8）以降、未交換の「腐敗した手骨」は1個につき「薔薇金券」×40の比率で回収されます。秘密保持者はメールをご確認ください。"
  },
