  Activity_97672_ActivityName = {
    Text = "神の誕生の儀式"
  },
  Activity_97672_ActivityPlot = {
    Text = "この華美なる犠牲の過去をもはや嘆く必要はない。\n血と骨を捧げよ、霊と肉を捧げよ、自由を捧げよ、命を捧げよ。\n彼女は至高の栄誉を定められ、彼女は孤独な苦痛を定められた。彼女は神の娘であり、彼女は神の母である。\nこの恐ろしくも忌まわしい運命を、彼女は喜んで受け入れた。"
