  Activity_97672_ActivityStageEndContent = {
    Text = "イベントは終了し、現在は「創生の七日間」のみ参加可能です。"
  },
  Activity_97672_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密保持者は期間限定プレイ「創生の七日」および「実績報酬」を通じてイベント通貨「安神アロマ」、「駆魘アロマ」、「捕夢アロマ」を収集できます。「安神アロマ」、「駆魘アロマ」、「捕夢アロマ」は「神母の寝宮」で商品を購入でき、イベント限定SR命輪「ブルーリング・トキシン」、流明の芯、無垢の芯などが含まれます。\n2、イベント期間中にイベント実績を達成すると、イベント限定アイコン「銀の鍵の名において：誕妄·マーフィー」を獲得できます！\n\n<Title:イベント期間>\n1、11月24日 9:00 – 12月15日 9:00（GMT+8）、すべてのイベントプレイに参加可能。\n2、12月15日 9:00 – 12月22日 9:00（GMT+8）、「神母の寝宮」と実績報酬のみ参加可能。\n\n<Title:創生の七日>\n1、「創生の七日」には7つのステージがあり、1日ごとに1つが自動開放されます。\n2、挑戦するたびに「霊啡肽」×120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能がアンロックされます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、校友会の助っ人を使用して、より簡単にクリアすることができます。\n\n<Title: 冒涜の狂宴>\n·イベント開始後、毎時間自動で60「安神アロマ」を獲得し、最大25時間分まで蓄積できます。\n\n<Title: 神母の寝宮>\n1、「神母の寝宮」には3つのショップがあり、開放時間は以下の通りです：\n·「異途の甘夢」：11月24日 9時に開放。\n·「誕神の深夢」：11月25日 9時に開放。\n·「無望の悪夢」：11月26日 9時に開放。\n2、毎回の奉納で750「安神アロマ」/「駆魘アロマ」/「捕夢アロマ」を消費し、寝宮内の5つのアイテム報酬をランダムに獲得します。\n3、各寝宮のアイテム報酬は「特殊アイテム」と「通常アイテム」の2種類に分かれており、リセット時に特殊アイテム報酬の残り数量を上限まで戻すことができます。具体的なルールは以下の通りです：\n（1）最初の2回のリセット：「特殊アイテム」の残り数量がなくなった後、秘密保持者はリセットを選択でき、リセット後は「特殊アイテム」と「通常アイテム」の残り数量が上限まで戻ります。また、奉納を続けることも可能で、「通常アイテム」の残り数量もなくなった場合は、リセットを行わないと奉納を続けることができません。\n（2）3回目以降のリセット：「通常アイテム」の残り数量がなくなった後にのみリセットが可能で、リセットにより「通常アイテム」の残り数量が上限まで戻りますが、「特殊アイテム」はリセットされません。\n\n<Title:イベントボーナス>\n1、秘密保持者が特定の覚醒体または命輪を所持している場合（編成不要）、「創生の七日」ステージ任務報酬の「安神アロマ」、「駆魘アロマ」、「捕夢アロマ」に追加のドロップボーナスが適用されます。具体的なボーナスは以下の通りです：\n·覚醒体「誕妄·マーフィー」：啓霊0/1/2/3以上で、ボーナス20％/30％/40％/50％。\n·SSR命輪「闇の中の安眠」：重位0/1/2/3以上で、ボーナス20％/30％/40％/50％。\n·SR命輪「ブルーリング・トキシン」：重位0/1/2/3以上で、ボーナス20％/30％/40％/50％。\n2、異なる覚醒体または命輪の「イベントボーナス」は累積方式で計算されます。 \n3、特別に、狂気難易度の初回クリア報酬は「イベントボーナス」の影響を受けません。"
