  Activity_97853_ActivityTips = {
    Text = "<Title:イベント概要>\n1、イベント期間中、秘密保持者は期間限定プレイ「日の下の新事」を通じてイベント通貨「海辺の特産貝殻」を収集できます。「海辺の特産貝殻」は「生徒会オフィスビル」で商品を購入でき、流明の芯、無垢の芯、賢石の欠片などが含まれます。\n2、イベント期間中、「異夢視界：さよなら、ネバーランド」が期間限定で無料アンロック！\n\n<Title:イベント期間>\n1、10月6日 9:00 – 10月20日 9:00（GMT+8）、すべてのイベントプレイに参加可能。\n2、10月20日 9:00 – 10月27日 9:00（GMT+8）、「生徒会オフィスビル」と実績報酬のみ参加可能。\n\n<Title:日の下の新事>\n1、「日の下の新事」には5つのステージがあり、2日ごとに1つが自動開放されます。\n2、挑戦するたびに「霊啡肽」×120を消費し、挑戦成功でイベント通貨を獲得できます。\n3、ステージクリア後、そのステージの「再現」機能がアンロックされます。ご注意：「再現」機能使用時、同調率は獲得できません。\n4、校友会の助っ人を使用して、より簡単にクリアすることができます。\n\n<Title:イベントボーナス>\n1、「休日紀行」の「上級紀行」をアンロックすると、「日の下の新事」ステージ報酬で追加100％の「海辺の特産貝殻」ドロップを獲得できます（再現を含む）。\n2、特別に、狂気難易度の初回クリア報酬は「イベントボーナス」の影響を受けません。\n\n<Title: 生徒会オフィスビル>\n「生徒会オフィスビル」にはショップが1つあり、10月6日 9時に開放されます。\nショップ内で商品を選択して直接購入できます。\n\n<Title:異夢視界>\n1、イベント期間中、「異夢視界：さよなら、ネバーランド」を無料でアンロックできます。\n2、イベント終了後、「異夢視界：さよなら、ネバーランド」の調査進捗は保持され、イベント期間中に未完了の調査イベントを完了した場合でも、イベント期間中と同じ調査報酬を獲得できます。イベント期間中に「異夢視界：さよなら、ネバーランド」をアンロックしなかった場合、イベント終了後も「現実起点」×7を消費してアンロックできます。\n3、イベント期間中かどうかに関わらず、「異夢視界：さよなら、ネバーランド」をクリアすると「鍵令：美夢の一瞬」を獲得できます。"
